"""定点上绳（climb）的执行器 —— P4「固定路径执行器」的第一块。

用户 2026-09-26 定的流程（照抄，别自己发明顺序）：

    ① **移动对齐**目标绳梯的 x：偏差 ≤ 「坐标对齐误差范围」，并且**保持**「坐标对齐
       误差时间」那么久，才算对齐成功（两个数都在 设置 → 判定参数 里）；
    ② **按住跳** + 按住 **↑**（向上爬）或 **↓**（向下爬）；
    ③ **判定到达** ⇒ 结束。两个方向各一条判据（**都是用户定的，别互相套**）：
       · **向上爬**：`y ≤ 绳梯**上端**的 y`（2026-09-26 用户改：原话"之前是按目标 foothold
         集合的 y，改为绳子上端的 y"）⇒ 再按着 ↑ 拖「坐标对齐误差时间」那一下收工；
       · **向下爬**：抓上绳稳一下 ⇒ **松 ↓、跳下绳梯**（朝目标集合中心）⇒ 落地判据
         三条先到算哪个（见 `ClimbJob.JUMP_DOWN` / `_landed`）。

**为什么先做「定点上绳」**：它是"贴着绳按上去"，**对起跳时机不敏感** —— 不必先做
跳跃标定（`docs/寻路设计.md` §6 的纪律：标定前不把视觉预测变成按键）。
"移动跳上绳"要在跑动中卡时机，属于标定之后的事；用户也说了最终会让 Agent 在两种
之间**随机挑**，所以这里留一个 `mode` 的位置（现在只有 `"定点"` 一种）。

**为什么这个模块不碰按键、不读画面**：
    · 它只回答"现在该**往哪边挪**、要不要**按跳**、**到了没有**"（`update()` 的回值）；
    · 按键下发仍走 `decision/agent.py` 那条路（`KeyState.set`），画面仍由感知层读；
    · 好处是它**能被自检用假坐标跑完整个流程**（`tools/selftest_route.py`），
      不用开游戏、不用按键 —— 爬绳最容易错的是"什么时候算对齐好了"，那正是它的活。

⚠ 世界坐标可能是**上一帧的**（小地图认不出黄点时沿用，见 `perception/minimap.py`）：
`update()` 收的是**调用方给的值**，"这帧的值新不新"由调用方负责 —— 别让它自己猜
（老代码里 `.held` 的坑就是这么来的）。
"""

MODE_FIXED = "定点"          # 唯一已实现的模式；将来加 "移动" 时在这里多一个取值

# ⚠ 这里原来有个 `ARRIVE_PAD = 14.0`（"离绳顶还差 14 像素就算到达"）——
# **2026-09-26 用户指出：他从没提过这个需求，那个数也没有任何数据支持**，已删除。
# 后果是实测角色停在 -204（平台面是 -208，差 4px 没上去）。判据现在只用**能指出
# 来源的数据**（绳梯那两端的 y / 目标平台的面），见 `ClimbJob._arrived`。要再加容差，
# 先说明来历并征得用户同意（见 README「工程约定：不许拍脑袋补数」）。

#: 一次上绳的总超时（秒）。对齐不了 / 卡在绳上不动，都不许无限等（P4 要求"超时报警"）。
DEFAULT_TIMEOUT_S = 12.0

#: 不在绳上多久算「掉下来了」（秒）。**必须留容错期**：按下跳之后人有几拍还在空中，
#: `ladder_id` 那时是 None —— 一离开就判失败会当场误杀。
OFF_LADDER_GRACE_S = 2.0

#: 「**开始点按微调**」的距离（像素）：离绳的 x 还差这么多以内就改**点按**
#:（2026-09-26 用户要求，当时是硬编码 20px）。
#: 为什么：按住方向键在游戏里就是"一直走"，快到位时一下就冲过头 ⇒ 来回抖（用户实测）。
#:
#: ⚠ 2026-09-27 用户要求**做成配置**（原话："攀爬对齐 x 时超过 20px 就按住方向键，
#:   太近了" —— 实测 20px 太贴着绳，精细那一段来得太晚）⇒ 上绳（`ClimbJob`）那份改由
#:   「攀爬参数 → **开始对齐绳梯x的距离(px)**」（`DecisionSettings.climb_align_near_px`）
#:   说了算，这里只是它的**默认值**（默认 20 = 老行为一点不变 ✓；用例
#:   `t_climb_align_near_px` 钉着"常量与设置默认值必须一致"）。
#: 走（`WalkJob`）仍然用这个常量 —— 用户没要求把走的那一份也做成配置 ✓。
NEAR_PX = 20.0

#: 点按的"按住"时长 / 点按周期（秒）。
#: ⚠ **"一帧"多长取决于来源**（原来这里写死一句"15fps 下 ≈ 按 1 帧、停 2 帧"，那是
#: **窗口抓帧模式**的口径）：窗口抓帧用「采集帧率」那个参数（默认 15.0 ⇒ 一帧 ≈67ms）；
#: **推流**按流自己的 fps（`live_thread` 里 `fps_ref[0] = src.fps`；实测 ≈30fps ⇒ 一帧
#: ≈33ms）。所以 `TAP_ON_S` 在前者是"≈1 帧"、在后者是"≈2 帧" —— 别拿"一帧"当固定 67ms
#: 推理 ✗（2026-09-27 就是这么误判过一次：见 `ClimbJob._dir_tap_at` 那条 ⚠）。
#: ⚠ 点按的"按住多久"是**按时长**算的、**与帧率无关**（`ClimbJob.update` 里"只在新按下
#: 时记时刻"那条 ✓；用例 `t_climb_align_tap_releases_any_fps` 按 15 / 34fps 两档钉着 ✓）。
#: ⭐⭐ **0.06 ⇒ 0.03**（用户 2026-10-06 ✓ 原话："**直接做成 30ms**"✓ —— 起因：现场观察到
#:   "对齐过程中方向键按住的时间有点长"✓，而"点按"这一档按的是这个数 ✓）。
#: ⚠⚠ **这是**全局**一个数**（不是某一种任务专属 ✗）—— 改它 = 下面这些都跟着变 30ms：
#:   · 爬绳对齐 x 的近处点按 / 「跳下绳梯」的点按跳 / 「中途跳下」的点按跳 ✓；
#:   · 下跳（`DropJob`）的「↓ ＋ 点按跳」与"脱离绳"那几下的跳 ✓；
#:   · 走不动时那个「单点跳」、走路的"微调"点按（`WalkJob` ✓）；
#:   · 传送点（`PortalJob`）：对齐期间那几下的 ↑ 点按、以及进容差后那一下"正式的 ↑" ✓。
#: ⚠ **"实际按住"仍受帧率量化**（这一点改不了、也别糊弄自己 ✗）：
#:   松手是"到点后的**下一拍决策**"才发的 ⇒ 推流 ≈30fps（一帧 33ms）⇒ 30ms 只够 **1 帧**
#:   （≈33ms，比原来的 2 帧 ≈66ms 短一半 ✓）；**窗口抓帧 15fps**（一帧 67ms）⇒ 30ms 也还是
#:   **1 帧 ≈67ms** ⇒ **低帧率下这个改动几乎看不出效果** ✗（真要让低帧率也变短，得改成
#:   "按 N 帧"的口径 —— 那是另一件事，用户没要求 ⇒ 没做 ✗）。
#: ⚠ `TAP_PERIOD_S - TAP_ON_S`（下爬"先松再按"那段的松窗 ✓）现在是 0.18−0.03 = **0.15** ✓
#:   仍然远大于一帧 ✓ 不受影响 ✓。
TAP_ON_S = 0.03
TAP_PERIOD_S = 0.18

# ⚠ 这里原来有 `OFF_X_PX = 18.0` / `OFF_X_GRACE_S = 0.6`（「偏离绳梯」判据的两个阈值）
# —— **2026-09-26 用户明确删掉那条判据**（理由见 `ClimbJob.update` 的 ② 那一段）✓。

# ⚠ **没有"最多试几次"了**（用户 2026-09-27 明确："我好像在寻路任务时看到一个 1/3 尝试的
# 显示……应该需要去掉，我们现在都走「寻路超时时间」"）：
#   一段寻路失败就**原地重来**，重来的次数**不封顶**，整天由 agent 的
#   「寻路超时时间」（`goto_timeout_s`，`_climb_tick` 里那道总闸 ✓）收口 ——
#   到点它会 `job.cancel("寻路超时：这一段已经跑了 N 秒…")` 并**整条路线**停掉 ✓。
#   所以这里原来那个 `DEFAULT_MAX_ATTEMPTS = 3` 已经删掉（连同各执行器的 `max_attempts`
#   属性和 OSD 上那个「第 N/M 次尝试」的分母 ✗）—— 谁要再加回来，先读这条 ✓。
#   仍然保留的是**重试之间的等待**（`agent.retry_delay_s`：基础 + 增量×已试次数 ✓），
#   它只影响节奏、不影响能不能放弃 ✓。

#: **「这一步正处在动作进行中」的相位**（人在绳上 / 空中 / 手持跳键）—— 用户 2026-09-27
#: 要求"位置状态一变就重新评判最优路径"时，**这些相位里先不重算**：
#:   人在绳上、脚离地、跳已经按下去了 —— 这时"重算最优路径"没有意义（新路径的第一步还是
#:   同一个动作），而且会把做了一半的动作打断 ✗（爬到一半松手 = 掉下来）。
#: 等它落地 / 离绳，下一拍再补上这次变化 ✓（agent 那边**故意不记状态**，见 `_maybe_replan`）。
#: ⚠ **加新执行器时把它的相位一并加进来**（沿用同一个词形：攀爬那套 `climb`/`jump_down`、
#:   下跳 `armed`/`drop`/`landing`、跳 `jump`；"还在往那边走 / 对齐"的相位**不算**
#:   —— 那些在地上，重算是安全的 ✓）。
INFLIGHT_PHASES = ("climb", "jump_down", "mid_jump", "armed", "drop", "landing", "jump")

#: 下跳：**先按住 ↓ 多久再补跳**（秒）。用户 2026-09-26 说的顺序是"按住 ↓ 再按跳"
#: —— 同一次 tick 里两个键一起发，在游戏里未必算"先↓后跳"，所以分两步发。
ARM_HOLD_S = 0.25

# ⛔ 这里原来有个 `DROP_DY_PX = 40.0`（下跳的几何兜底："y 比出发时增大 40 像素就算落地了"）——
# **2026-09-28 用户要求删掉**（原话："把『y 掉 40px』换成『**脚下这块面 == 目标面**』"）：
# 它**太松** —— 人往下掉 40px 就报"到了"，哪怕还在半空、或者落到了**别的**平台上 ✗
# （实测：追击反复下发同一条下跳任务，就是它误报"到了" ⇒ 人其实没下去 ⇒ 下一拍又判
#  "怪不在我这块平台" ⇒ 又下 ✗）。
# 现在用"广播的 `ground_y` 命中目标集合的面 y"（见 `DropJob._arrived` ✓）——
# **不新造常数**：容差就是现成的「坐标对齐误差范围」（`DropJob.y_tol_px` ✓）。

#: 「爬上去了但**不动了**」的判据（秒）：上绳阶段里 y 连续这么久没有变好 ⇒ 判失败，
#: 并把**两个数**（卡在哪个 y / 离目标面还差多少）写进 note。
#:
#: 为什么必须有（2026-09-26 用户报"角色在 Y=-170 就停了"，而这已经是**第二次**报同一个
#: 现象）：原来的行为是**默默超时** —— 30 秒里一直按住跳键，然后重试 3 次、放弃，界面上
#: 只看到"角色停住"，一个字的线索都没有 ⇒ 只能靠猜（是坐标口径不对？还是这段绳到不了顶？）
#: 而这两种原因的**修法完全相反**。现在让任务自己把话说清楚。
STALL_S = 3.0

#: ⭐ 「中途跳下」的**防抖门槛(s)**（2026-09-28 ✓）：必须**已经在绳上稳这么久**
#: 才允许判"爬到高度了、跳下去"。为什么需要：刚吸上绳/跳上绳的那一瞬间 `_on_ladder`
#: 就为真、而 `py` 常常刚好满足条件 ⇒ 会在**还没真开始爬**时就把 `_mid_jumped` 用掉 ✗
#: （用过就锁死，之后爬到顶也不跳 ✓ 用户报的那个 bug 的一半 ✓）。
#: 取 0.25s：够滤掉"刚贴上"那一瞬，又不至于让人在高度上白等 ✓。
MID_ARM_S = 0.25


def stall_s_from_retry_ms(ms):
    """「移动操作尝试间隔(ms)」→ 那些"多久没进展就算卡住"的判据要的**秒**（下限 0.5 ✓）。

    用户 2026-09-27 要求（原话）："移除卡住判定时长(s)，**统一采用移动操作尝试间隔(ms)**" ✓
    —— 原来那件 `DecisionSettings.stall_s` 已删 ✓；上爬「爬不动」/ 下爬「等落地」/ 跳跃「没落到」
    这些判据现在都从这一件参数换算 ✓。
    **一处实现**：三处调用（`agent.start_climb` 灌 job ✓、实时线程的解析器 ✓、面板预览 ✓）
    都走它 ⇒ 免得三处各写一份钳法、以后又分叉 ✗（下限 0.5 秒：再小就等于"刚按一下就判卡住"✗）。
    """
    try:
        n = int(ms)
    except (TypeError, ValueError):
        n = 3000
    return max(0.5, n / 1000.0)

#: y 要变好**这么多**才算"还在往上爬"（世界像素）。防抖：小地图读数本来就在抖几个像素，
#: 拿它当"还在动"会让卡死永远判不出来。
#: ⚠ **它必须大于"读数噪声"**（2026-09-27 定，用户要求把这类"名不副实"的容差一起改掉）：
#:   这张图上 **1 个实时小地图像素 ≈ 8.5 世界像素**（`docs/寻路设计.md` 的实测：16.08 ÷
#:   1.88；±0.5 面板像素 ⇒ ±4.3 世界像素）；双点标定的残差另有 ≈6 世界像素（同文档）。
#:   原来这里是 **2.0** —— 比噪声小 4 倍 ⇒ "y 动没动"永远判成"没动"（`STALL_S` 一到就报
#:   「爬不动了」✗，用户现场就见过这种误报）。取 **8** ≈ 1 个面板像素：既在噪声之上，
#:   也远小于任何一段真实爬升（几百像素）⇒ 真卡住照样判得出来 ✓。
STALL_GAIN_PX = 8.0

#: **对齐类判据的默认容差**（世界像素）：走位对齐 x / 上绳前对齐绳的 x 都用它。
#: ⚠ 为什么是 10 而不是 6（2026-09-27 定，同上面那条的来历）：这张图 **1 个面板像素 =
#:   8.5 世界像素** ⇒ 要"对齐到 6 像素"等于要求**亚一个像素**的精度，而读数本身就抖
#:   ±0.5 面板像素（±4.3 世界像素）、双点标定还有 ≈6 的残差 ⇒ 6 是名不副实的阈值：
#:   对齐判据会在噪声上反复"到了又没到"（现场观感就是"来回抖、按很久"）。
#:   10 ≈ 1.2 个面板像素，且**现场已经在用**（寺院通道2 的「坐标对齐误差范围」就是 10 ✓）。
#: ⚠ 它只是**默认值**：每个项目在「设置 → 判定参数」里各有自己的数（`project.yaml` 的
#:   `decision.align_tol_px`），改这里只影响**没配过的项目** ✓。
ALIGN_TOL_PX = 10.0


#: 打断短于这么多秒**不算打断** —— 那就是正常的拍间隔（窗口模式默认 15fps ≈ 67ms；
#: 推流按流 fps、实测 ≈30fps ≈ 33ms ⇒ 比本值小一个数量级 ✓）。
#: 拿正常间隔当打断，任务会每拍都"重新对齐" ✗（比不修还糟）。
PAUSE_MIN_S = 0.25


class _PausableJob:
    """三个执行器（走 / 爬 / 下跳）共用的「被战斗打断」契约。

    为什么需要它：「攻击范围内有怪」是 tick 里的**第一条总判据**（见 `docs/寻路设计.md`
    的"攻击优先"一节）⇒ 那一拍**整套任务都不跑**（`agent._climb_tick` 根本不被调用 ✓）。
    可任务内部全是**绝对时刻**锚点：`_best_at`（"不动了"）、`_off_since` / `_off_x_since`
    （"掉下来了 / 偏出去了"的宽限）、`_in_tol_since`（"站住保持"）—— 而 `now` 一直在走
    ⇒ 打完架回来，它会把**站着挨打的那几秒**当成"爬不动了 / 走不动了" ✗
    （用户 2026-09-26 报的"爬到 y=-170 就不再升了（3.0s 没变好）"就是这个形状 ✗）。

    契约两条（agent 只管叫一声，怎么继续由各执行器自己定 ✓）：
      · `interrupted(now)` —— "这一拍我没跑你"（幂等：只记第一次的时刻 ✓）；
      · `update()` 开头调 `_resume(now)` —— 回来时把上面那些锚点**整体往后挪**
        （等于"任务的时间停了一会儿" ✓），并返回被打断了几秒，各执行器据此决定从哪继续。

    ⚠ **`_t0`（整体超时）= 每次「进入战斗」就重新计时**（用户 2026-09-26 要求）：
      战斗中挨打不是"这段路卡住了"✗ ⇒ 打怪的时间不许算进寻路超时里 ✓。所以
      `interrupted()` 一被叫到（= 这一拍进了 attack ✓）就把 `_t0` 重打到当前时刻 ✓
      （同一段战斗只重打**一次** —— 每拍都重打就等于"超时永远不触发"✗）。
      代价说清楚：只要一直有怪，这一段路就**不会**被超时收掉 ✓（这正是用户要的：
      超时管的是"卡住"，不是"路上有怪"✓）；要结束只能靠走完 / 手动取消 / 战斗停了
      之后又卡住 ✓。（防"无限重来"的是 **agent 的「寻路超时时间」** ✓ —— 2026-09-27 起
      执行器自己**没有**"最多试几次"了，见文件头那段说明 ✓。）
    """

    #: 需要"跳过打断时长"的锚点名字（子类在 `__init__` 里列全）。
    #: 漏一个，那条判据就会把打架的那几秒算进去 ✗。
    _ANCHORS = ()

    def interrupted(self, now):
        """agent 在"这一拍没跑任务"时叫一声（同一段战斗里每拍都会叫，幂等 ✓）。

        **进场即重打超时**（用户 2026-09-26 要求："每次进入 attack，寻路超时要重新计时"）：
        战斗不是"这段路卡住了" ✗ ⇒ 挨打的时间不算超时 ✓。只在**这一段战斗的第一次**
        （`_paused_at is None` ✓）重打 —— 每拍都重打就等于"超时永不触发" ✗。
        ⚠ 重打的是**整体超时**（`_t0`，"这一段走了多久"的总账）；"爬不动了 / 走不动了"
        那几条细判据仍然只看**真正在走的那段时间**（由 `_resume` 把打断时长扣掉 ✓）。
        """
        if getattr(self, "_paused_at", None) is None:
            self._paused_at = float(now)
            self._t0 = float(now)          # ← 超时从"进战斗这一刻"重算（见上面说明）

    def _resume(self, now):
        """被打断后**回来那一拍**：把打断时长从进度/宽限锚点上扣掉 ⇒ 返回被打断了几秒。"""
        p = getattr(self, "_paused_at", None)
        if p is None:
            return 0.0
        self._paused_at = None
        dt = max(0.0, float(now) - p)
        for name in self._ANCHORS:
            v = getattr(self, name, None)
            if v is not None:
                setattr(self, name, v + dt)
        return dt

    # ⭐ 执行器回值的**统一形状**（2026-09-27 结构整理 ✓）：四个 `_out` 原来各拼一份一模一样的
    #   dict ✗ —— 现在**一处拼** ✓，形状与以前逐字一致 ✓。
    def _result(self, move, jump=False, dir=0, reassert=None, replan=False):
        """`reassert=None` = **不带**这个键（走 / 跳从不重发按键 ✗，带上反而误导 ✓）；
        `False/True` = 带上（爬 / 下跳会重发 ✓）。
        `replan=True` = **位置状态返回非目标**（上了别的绳 / 站在别的集合）⇒ 通知上层重启寻路
        （用户 2026-10-02 ✓ 治本：align 阶段按住 ↑ 是设计，但被非目标绳吸住时该立刻重启，不卡住）。"""
        out = {"phase": self.phase, "move": int(move), "jump": bool(jump),
               "dir": dir, "note": self.note,
               "done": self.phase == self.DONE,
               "failed": self.phase == self.FAILED}
        if reassert is not None:
            out["reassert"] = bool(reassert)
        if replan:
            out["replan"] = True
        return out

    def _cancel_common(self, why):
        """外部叫停的**统一收尾**（用户 2026-10-02 #8 ✓）—— 四个 `cancel()` 共用这一处。

        ⚠ 为什么必须这么做（原风险）：`cancel()` 原来**只置 `FAILED` + note**，**一个运行时
          字段都不清** ✗；而 `retry()` 要清的字段一大把（ClimbJob ~28 个）⇒ 将来谁复用同一个
          job 实例、或者新加字段忘了同步，就会带着**上一个任务的脏锚**（历史踩过：
          `_diag_at` / `_climb_sig` / `_rope_seen` ✓）。⇒ 让 `cancel` **复用 `retry` 的清单**
          （一处口径 ✓：以后加字段只改 `retry`✓），再盖成 `FAILED` + 原因 ✓。
        ⚠ `attempt` 会被 `retry()` +1：取消后这个对象就作废了，无副作用 ✓（用例只看相位/note ✓）。
        ⚠ **这里不碰 `_out`**：四个子类的 `_out` 形状不同（走是 `_out(move)`、跳是 `_out(move, jump)`
          ⇒ 没有共同的调用形状 ✗）—— 回值由各自的 `cancel()` 自己拼 ✓（见那四处 ✓）。
        """
        self.retry()
        self.phase = self.FAILED
        self.note = str(why)

    # ⭐ 共享的「进步跟踪」骨架（2026-09-27 结构整理 ✓）：ClimbJob 的"爬不动"与 WalkJob 的
    #   "走不动"原来**各写一遍** `best + best_at + 卡住时长` 的比较 ✗ —— 现在一处 ✓。
    #   ⚠ 另两个"卡住"（DropJob 的 DROP 相、JumpJob 的跳后超时）是**一次性计时**（"离某个
    #   时刻过了多久"），不是"best 值有没有变好"，语义不同 ⇒ 不硬塞进来（硬塞 = 增加耦合 ✗）。
    def _stalled_since(self, now, value, best, best_at, stall_s, better):
        """`better(value, best)` = 这一拍有没有**朝目标**变好（调用方给 ✓，方向各不同：
        上爬 = y 越小越好、下爬 = y 越大越好、走路 = 离落点越近越好 ✓）。
        变好 ⇒ 记新 best / 时刻、不算卡；否则 `now - best_at ≥ stall_s` ⇒ **卡住** ✓。
        返回 `(best, best_at, stalled)` —— 调用方把前两个存回自己的锚点 ✓。
        """
        if best is None or better(value, best):
            return value, now, False
        stalled = (best_at is not None) and (now - best_at) >= stall_s
        return best, best_at, stalled


class ClimbJob(_PausableJob):
    """一次「定点上绳」。`update()` 是纯的：喂当前状态，回下一步该干什么。

    用法（调用方每拍喂一次）：

        job = ClimbJob("L2", x=701.0, y1=-115.0, y2=231.0, direction=+1,
                       dst_set="上下过渡平台", tol_px=6, hold_ms=250)
        out = job.update(now, px=ws.player.x, py=ws.player.y,
                         ladder_id=ws.player.ladder_id,      # 现在在哪根绳上（可 None）
                         here_sets=ws.player.here_sets)      # 脚下属于哪些集合（可 None）
        if out["move"]:  ...按左右...
        if out["jump"]:  ...按住跳 + 按 out["dir"]...

    回值：`{"phase", "move", "jump", "dir", "note", "done", "failed"}`
        move  -1/0/+1 往哪边挪（0 = 站住别动）
        jump  True = **按住**跳键（不是点按）
        dir   -1/0/+1 对应 ↓ / 不按 / ↑（向上爬时是 ↑）

    **流程（用户 2026-09-27 定的口径，改这里之前先读）**：
      ① 对齐绳的 x（`tol_px` 内还要稳住 `hold_ms`）→ ② **按一下跳** + 按住方向（点按：
         按住等于只按过一次 ✗ —— `KeyState` 只在键集变化时才发键）；
         **还没上绳、人还站在起跳那块平台上**（`src_set`）⇒ 跳失败那几拍**人可能还在
          空中落**，那个当口**横着挪**会把他挪歪 ✗ ⇒ 按顺序做两件前置事（用户 2026-09-27）：
           ① **先站住等 y 稳定**（`_y_settled`：2px 内静 `STALL_S` ✓ 不新造常数；这几拍
              **不许横move** ✓）；
           ② **再补按一次目标方向**：⚠ **上爬只有"按住 ↑"和"补按住 ↑"**（用户 2026-09-27
              更正，原话："向上攀爬只有「按住 ↑」和「补按住 ↑」，**不能存在「松开 ↑」和
              「点按 ↑」**"）⇒ 上爬这一拍是 **按住 ↑ + `reassert`（只再发一次 PRESS ✓，不先松）**，
              见 `_retry_all_up` ✓；**下爬**才走老的"先松 `TAP_PERIOD_S - TAP_ON_S`、再按
              `TAP_ON_S`"（那几拍人已主动离开绳 ⇒ 松 ↓ 是语义本身 ✓）；
         两件做完才**回到 ① 重新开始**：两次尝试之间的间隔就是 ① 那个保持窗口
         （`hold_ms` ✓），而重来那一轮里**方向键继续按着**（空中松手就抓不住绳 ✗）；
         ⚠ **跳那一拍只在重来那一小段之外才按** ⇒ 「后续的跳」自然排在"稳定 + 点按 +
         对齐"完成之后 ✓（`_retry_stage`，见它的说明）；
      ①' **斜跳上绳**（用户 2026-09-27 的设计）：离绳**远**的时候不必先站到绳正下方 ——
          当 `开始对齐绳梯x的距离`(≈20px) **< 离绳的 x 距离 ≤** `起跳距离`(`jump_start_px`)，
          而且**人正站在绳要抓的那块 foothold 上** ⇒ 直接**按住朝绳的方向 + 点按跳**斜着过去 ✓；
          **一轮只斜跳一次**（`_diag_done` ✓，跳完继续朝绳走，近了自然交回 ① ✓）；
          `起跳距离` = 0（默认）⇒ **整条关掉**，行为与以前**完全一致** ✓（兼容开关 ✓）；
          ⚠ **许可条件只有一条：`开始对齐绳梯x的距离` < |dx| ≤ `起跳距离`** ✓ ——
            2026-09-27 用户明确否掉了原来那道"人得站在绳入绳端那块面上"的许可 ✗
            （原话："**对齐了就按跳开始爬啊，不需要判定别的**"）⇒ 与原地起跳一起拆了 ✓。
      ③ 上绳之后只按住方向键（↑/↓），**不再按跳**（再按跳会卡在绳上/绳顶 ✗）；
      ④ **被攻击打断之后回来重走一遍流程**（`phase` 回 `ALIGN`，锚点全清）—— 人在绳上时
         ① 那一步会**自己跳过横向对齐**（在绳上按左右 = 松手掉下来 ✗），所以是"重走一遍"
         而不是"接着上次跑" ✓（要求 ③）。
    """

    ALIGN = "align"          # ① 对齐绳的 x
    CLIMB = "climb"          # ② 按跳 + 方向
    #: ②' **下爬专属**：松 ↓ ⇒ 「跳下绳梯」（按住方向 → 按跳 → 松跳、方向继续按着）
    #: ⇒ 等落地。见 `update` 里那一支与 `_jump_down_beat`。
    JUMP_DOWN = "jump_down"
    DONE = "done"            # ③ 到了
    FAILED = "failed"        # 超时 / 中途掉下来
    MID_JUMP = "mid_jump"    # ④ **中途跳下**（上爬到「高度」就跳下来，用户 2026-09-28 ✓）

    def __init__(self, ladder_id, x, y1, y2, direction, dst_set="",
                 dst_y=None, dst_x=None, src_set="", align_gap_ms=None,
                 mode=MODE_FIXED, tol_px=ALIGN_TOL_PX, hold_ms=250, near_px=NEAR_PX,
                 stall_s=STALL_S, jump_start_px=None,
                 mid_dir="", mid_y=None, mid_hold_s=0.0,
                 timeout_s=DEFAULT_TIMEOUT_S):
        self.mode = mode
        self.ladder_id = str(ladder_id)
        self.x = float(x)
        self.y_top = float(min(y1, y2))
        self.y_bot = float(max(y1, y2))
        self.dir = 1 if direction >= 0 else -1     # +1 向上 / -1 向下
        #: ⭐ **中途跳下**（用户 2026-09-28 ✓：「爬」的**逐边**配置）：
        #:   · `mid_dir` = `""`/`"center"`/`"left"`/`"right"`（**`""` = 不启用** ✓ 老行为不变 ✓）；
        #:   · `mid_y`   = 「高度」= **世界坐标 y**（⚠ **越小越靠上**）。判据是**字面**的
        #:     `人的 y >= mid_y`（用户明确"照字面"✓）⇒ 等效于"**人在这点的下方**" ✓
        #:     （上爬时人一开始最低 ⇒ **一开始就满足** ⇒ 配大了等于"上去就跳" ⚠；
        #:      要"永不触发"得配得比绳**上端**还小 ✓。这套含义也写在界面 tooltip 里 ✓）。
        #:   · `mid_hold_s` = 落地之后**再按住 ↑ 这么久**才松（= 「移动操作尝试间隔」✓ ——
        #:     用户原话："**不松开 ↑**，直到**返回成功或失败后**再经过「移动操作尝试间隔」松开"✓）。
        #: ⚠ 只有**上爬**（`dir > 0`）走这条路（下爬本来就有它自己的"跳下绳梯"✓ 见 `JUMP_DOWN`）。
        self.mid_dir = str(mid_dir or "")
        self.mid_y = None if mid_y is None else float(mid_y)
        self.mid_hold_s = max(0.0, float(mid_hold_s or 0.0))
        self._mid_jump_at = None      # 「中途跳下」开始发键的时刻（`None` = 还没开始 ✓）
        self._mid_dir_done = False    # 方向键那"单独一拍"发过没（同 `_jump_down_beat` 的两步法 ✓）
        self._mid_land_at = None      # 判到落地（= 用户说的"返回成功或失败"）的时刻 ✓
        self._mid_jumped = False      # ⚠ **只触发一次**（触发过就不再进这一相，防来回抖 ✗）
        #: ⭐ 「在绳上（上爬）已经稳了多久」的**起点**（`MID_ARM_S` 的门槛用 ✓）——
        #:   `_on_ladder` 为真的每拍推进、离开绳就清。⚠ **独立字段**：`_on_ladder_since`
        #:   是**下爬分支专用**的计时起点（"稳住 hold_ms 再跳下"），混用会改掉下爬行为 ✗。
        self._mid_arm_since = None
        self.dst_set = str(dst_set or "")
        #: **起点集合名**（这条「爬」边从哪个集合出发）。没上绳时用它区分两件事
        #:（用户 2026-09-27 要求 ②）：
        #:   · 还站在**起跳那块平台**上 ⇒ 是"跳没生效" ⇒ **一下一下地再按跳**（继续尝试）；
        #:   · 已经离开那块平台、又不在绳上 ⇒ 才是"掉下来了"（容错期后判失败 ✓）。
        #: 空串 = 不知道（`job_for_edge` 一定给 ✓；手工建的测试任务可以不传）⇒ 那时
        #: 退回老行为（一直按住跳 / 照旧按"掉下来了"判失败 ✓）。命名与 `DropJob`
        #: 那一格同口径（它也是"这条边从哪个集合出发" ✓）。
        self.src_set = str(src_set or "")
        #: 「**绳要抓的那块 foothold**」= 绳的**入绳端**压着的那条面 ⇒
        #: `(左, 右, 面y最小, 面y最大, foothold id)`；None = 不知道（老任务 / 手工建 ✓）。
        #: ⚠ 用户 2026-09-27 报"**对齐 x 时一直在不正确的位置按跳**"⇒ 这道门就是治它的：
        #:   原来**只看 x 对齐**，可同一个集合里可能有好几块**不同高度**的 foothold
        #:   ⇒ x 对上了、人却站在别的高度 ⇒ 跳多少次都抓不到绳 ✗（现场看就是"一直在乱按跳"✗）。
        #: 判据走**数据**（绳的入绳端落在哪条 foothold 上，`zones.ladder_ends` ✓）+ 已有的
        #: 「坐标对齐误差范围」当容差 ⇒ **不新造常数** ✓；不知道就不拦（退回老行为 ✓）。
        # ⚠ 这里原来存「入绳端那块 foothold 的 (左右, y0, y1, id)」（`entry_span`）——
        #   2026-09-27 随「按跳许可」那道门一起删了（用户：
        #   “对齐了就按跳开始爬啊，不需要判定别的” ✓）。
        #: 「**起跳距离(px)**」= **斜跳上绳**的区间上界（世界像素；`None` / `0` = **关** ✓）。
        #: 用户 2026-09-27 的设计（原话）："现在利用「起跳距离范围」设计「斜跳上绳」逻辑，
        #: 要求使用「开始对齐绳梯x的距离」参数兼容旧的「对齐x原地起跳上绳」逻辑"：
        #:   · `开始对齐绳梯x的距离`（`near_px`）< |dx| ≤ 本参数 ⇒ **斜跳**（按住朝绳的方向
        #:     + 点按跳，斜着过去 ✓ —— 省掉"站住再原地跳"那一段 ✓）；
        #:   · |dx| ≤ `near_px` ⇒ **老的**"对齐 x → 站住 → 原地起跳" ✓（一个字没改 ✓）；
        #:   · |dx| > 本参数 ⇒ 老的"一口气按住走过去" ✓（离太远斜跳够不着 ✗）。
        #: ⇒ **`0`（默认）时整条斜跳关掉** ⇒ 与加这个功能之前**完全一致** ✓（这就是兼容底线 ✓）。
        #: 界面上是「路线识别 → 物理参数 → 起跳距离(px)」（`DecisionSettings.jump_start_px` ✓）——
        #: 「跳」那条边也在用它，语义同一个："进了这个距离就该按跳了" ✓。
        self.jump_start_px = (0.0 if not jump_start_px
                              else max(1.0, float(jump_start_px)))
        #: 「**这一轮斜跳过没**」—— 一轮只斜跳一次（跳完继续朝绳走，近了就交回老逻辑 ✓）；
        #: 不然每拍都按跳 = "一路乱跳" ✗。`retry()` / 被打断重走时重新武装 ✓。
        self._diag_done = False
        #: 「**斜跳飞行中**」—— 跳出去之后的几拍要**一直按住 ↑**（用户 2026-09-27 现场：
        #:   "现在斜跳上绳梯会有「**经过绳梯却没有上去**」的现象，**空中吸附绳梯的条件是
        #:   「正在按住 ↑」**"）⇒ 飞行期间一律 `vert=1`（按住 ↑）+ 朝绳走 ✓；
        #: 结束条件：① 吸上绳（`ladder_id` 变成这根 ⇒ 交下面"已在绳上"那支 ✓）；
        #: ② **落回起跳高度**（`_diag_y0` ± 「坐标对齐误差范围」，且中间**离开过** ⇒ 人已落地 ✓）。
        self._diag_flying = False
        self._diag_y0 = None            # 斜跳那一刻的 y（判断"落回起跳高度"用 ✓）
        self._diag_left = False         # 这一跳**离开过**起跳高度没有（没离开过就不算落地 ✓）
        self._diag_at = None            # 斜跳那一拍的时刻（"一直没离地"的兜底用 `stall_s` ✓）
        #: ⭐ **斜跳的"第一步"**（用户 2026-09-28 要求：**斜跳也拆成两拍发**）——
        #:   `None` = 没在斜跳起手；非 `None` = **已经发过"朝绳走"那一拍**、下一拍该按跳 ✓。
        #:   为什么拆（用户原话："朝目标绳梯的 x 方向对齐 x（**至少发 1 次点按方向键**）→
        #:   跳 → 按住 ↑，这三步要循环"）：同一次 tick 里把"方向"和"跳"一起发，游戏里未必算
        #:   "按住方向再跳"（`KeyState` 一次下发多个键**不保证顺序** ✗）—— 与「跳下绳梯」那条
        #:   "先按住方向、再按跳"**同一个理由** ✓（那里只隔一拍，不新造时长常数 ✓）。
        self._diag_arming = None
        #: ⭐ 「**这一轮发过水平方向键没有**」（用户 2026-09-28 要求："对齐 x（**至少发 1 次
        #:   点按方向键**）→ 跳 → 按住 ↑"）—— 记账只有**一处**（`_out` 里 ✓）：
        #:   按了跳 ⇒ 这一轮结束（置 `False`，**下一轮要重新发方向键** ✓）；
        #:   发了水平方向 ⇒ 这一轮满足（置 `True` ✓）。`_align_step` 据此插一道闸：
        #:   **`|dx| ≤ 容差` 也要先朝绳点按一次**（原来一次都不发就跳 ✗）。
        self._align_pressed = False
        #: **目标平台那条 foothold 的面**（世界坐标 y；None = 不知道）。
        #: ⚠ 2026-09-26 用户改了向上爬的口径之后，它**只给向下爬**当"落地面"用
        #:（见 `_landed`）—— 向上爬的到达判据已改成**绳梯上端的 y**（`y_top`，
        #: 来龙去脉写在 `_arrived` 的 docstring 里）。留着这一格是因为下爬仍然要用：
        #: 落地是"够到平台的面"，而不是"越过绳端" ✓。
        self.dst_y = None if dst_y is None else float(dst_y)
        #: **目标集合的 x 中点**（世界坐标）。**只有"下爬"用**（`_jump_down_beat` 要靠它
        #: 决定"跳下绳梯"时按住哪个方向键）。
        #: 口径是用户 2026-09-26 定的：集合里所有**非墙** foothold 的 x 中点
        #:（`(min + max) / 2`，和「走」那条边的目标点**同一套** ✓）。
        #: None = 算不出来（那条边的目标集合一条 foothold 都没圈）⇒ 这一跳没有方向可依，
        #: **如实写进 note**、不猜方向 ✓（同"不许拍脑袋补数"）。
        self.dst_x = None if dst_x is None else float(dst_x)
        #: **对齐 x 时两次按下方向键之间的最小间隔(ms)**（「对齐绳梯移动延迟」，用户
        #: 2026-09-27 加）：默认 = `TAP_PERIOD_S`（就是原来写死的那个 180 ms 点按周期 ✓，
        #: 所以老调用方行为**一点不变** ✓）；0 = 不限制（想按就按）。
        #: 远距离（> `NEAR_PX`）是**一口气按住走** —— 那只有"一次按下" ⇒ 天然满足间隔 ✓，
        #: 而且远距离点按会走得太慢、直接撞超时 ✗；受它约束的主要是**快到位时的点按** ✓。
        self.align_gap_ms = (int(TAP_PERIOD_S * 1000.0) if align_gap_ms is None
                             else max(0, int(align_gap_ms)))
        #: 「**开始对齐绳梯x的距离(px)**」（用户 2026-09-27 要求，从写死的 `NEAR_PX`
        #: 抽成一个设置）：差得比它远 ⇒ **一口气按住走**（那只有"一次按下" ⇒ `align_gap_ms`
        #: 天然满足 ✓，而且远距离点按会走得太慢、直接撞超时 ✗）；**进到它以内 ⇒ 改成点按**
        #:（一下一下，别冲过头 ✓，受 `align_gap_ms` 约束的就是这一段 ✓）。
        #: 默认 `NEAR_PX` = 20 ⇒ **老调用方行为一点不变** ✓（用例钉着这条）。
        self.near_px = max(1.0, float(NEAR_PX if near_px is None else near_px))
        #: 「**卡住判定时长(s)**」（设置 → 判定参数；用户 2026-09-27 要求做成可配）：
        #: **上爬「爬不动了」** 与 **下爬「等落地」** 共用它（默认 `STALL_S` = 3 ⇒ 老行为 ✓）。
        #: 下限 0.5：再小就等于"读数抖一下就算卡住"✗（同 `WalkJob.stall_s` 的钳法 ✓）。
        self.stall_s = max(0.5, float(stall_s))
        #: 对齐阶段"现在按着哪个方向"：0 = 没按着，±1 = 正按着那边。
        #: 用它区分**同方向一直按住**（算一次按下 ✓）和**松开过之后再按**（新的一次 ✓）——
        #: 「对齐绳梯移动延迟」约束的是后者 ✓。
        self._press_dir = 0
        #: 上一次**按下**方向键的时刻（`retry()` 会清 ✓）。
        self._press_at = None
        #: 这一轮尝试**按过跳了没** —— 用户 2026-09-27 定的流程是"按跳 + 按住 ↑，还没上绳
        #: （人还在起跳那块集合里）⇒ **回到对齐 x 重新开始**"：所以一轮里只按**一下**跳，
        #: 下一拍就退回 ALIGN 重走 ✓（见 `update` 里 ②' 那段）。
        self._jump_tried = False
        #: ⭐ **「对齐完成、即将起跳」的时刻**（用户 2026-09-28 要求 ✓）—— agent 靠观察它
        #:   "变成非 `None` / 变了"来在那一刻复核"有没有更便宜的怪"（`agent._climb_recheck` ✓）。
        #:   `DropJob` 有同名同义字段（那边是**计时起点**：`ARM_HOLD_S` 由它算 ⇒ 必须进
        #:   `_ANCHORS` ✓）；⚠ 这里**只是哨兵**（"这件事发生了没有"✓）⇒ **不进** `_ANCHORS`
        #:   （它不是计时起点，进表反而会让 `_resume` 去挪一个只用来比"变了没"的值 ✗）。
        self._armed_at = None
        #: 现在这一轮对齐是不是"跳没上去、回来重来"的那一轮 —— 是的话**方向键继续按着**：
        #: 用户原话是"按跳 + 按住 ↑"，中间松手的话人在空中那一下就抓不住绳 ✗
        #: （真抓上了会自动走"已在绳上"那条，不再按跳 ✓）。
        self._retrying = False
        #: 「跳没上去 ⇒ **先站住等 y 稳定** ⇒ 再补按一次目标方向 ⇒ 回 ① 对齐」这一小段的
        #: 状态（用户 2026-09-27 要求）："" = 不在这一小段里；"y" = 正站住等 y 稳定；
        #: "tap" = 正在点按目标方向。
        #: ⚠ 为什么必须有它：跳失败那几拍**人可能还在空中往下落** —— 那个当口按方向键会
        #:   把他挪歪 ✗ ⇒ 先什么键都别按，等 y 不再变了再说 ✓（判据复用下爬落地那套
        #:   `_y_settled`：2px / 3s，不新造常数 ✓）。
        #: ⚠ 跳那一拍只在 `_retry_stage == ""` 时才按 ⇒「**后续的跳**」自然也排在
        #:   "稳定 + 点按 + 对齐"完成之后 ✓（用户 2026-09-27 原话的后半句）。
        self._retry_stage = ""
        #: 「跳没上去 ⇒ 回到对齐 x 重新开始」**之前**那一次**目标方向（↑/↓）的点按**
        #: 是从哪一刻起算的（用户 2026-09-27 要求；None = 没在点按）。
        #: ⚠⚠ **上爬已经不走这套了**（用户 2026-09-27 更正："向上攀爬只有「按住 ↑」和
        #:   「补按住 ↑」，**不能存在「松开 ↑」和「点按 ↑」**"）⇒ 上爬改用 `_retry_all_up`
        #:   （**按住 ↑ + `reassert` 再发一次 PRESS ✓，绝不先松 ✓**），这个字段只剩**下爬**在用 ✓。
        #: ⚠ 下面这段"先松开、再按"的理由**只对下爬成立**（下爬那几拍人已主动离开绳 ⇒ 松 ↓ 是
        #:   语义本身 ✓）：按跳那一拍 ↑/↓ 本来就是**按着**的
        #:（`_out(0, True)` ⇒ `dir = self.dir` ✓），而游戏只认**新的一次按下**（一直按着
        #: 等于一次都没新按过 ✗ —— 和"跳键要松开再按"是同一条游戏习性，本机 `KeyState`
        #: 也只在键集变化时才发键 ✗）⇒ 不松一下再按，对面看到的还是"从跳那一下一直按着"
        #: ⇒ 这一下白按 ✗。
        #: 时序用现成的点按周期（`TAP_PERIOD_S`/`TAP_ON_S`，不新造常数 ✓）：先松
        #: `TAP_PERIOD_S - TAP_ON_S`，再按 `TAP_ON_S`，然后才退回 ALIGN ✓。
        self._dir_tap_at = None
        self.tol_px = max(1, int(tol_px))
        self.hold_ms = max(0, int(hold_ms))
        #: ⭐ **纯的「坐标对齐误差时间」**（= 设置里那格的原始值，**不含端到端延迟** ✓）。
        #: 用途：上爬到顶**收工后**再按住 ↑ 这么久才松（`_arrive_step` 的 `_arrived_hold`）。
        #: 为什么必须单独存一份：`agent._climb_tick` 会在喂拍前把 `self.hold_ms` 改成
        #: 「纯值 + 端到端延迟」给**对齐稳住**用（对齐依赖读数、读数有延迟 ⇒ 要加 e2e ✓）；
        #: 而「收工后 ↑ 延时」是**游戏机制**（迈上平台那一步要按着 ↑），跟读数延迟无关
        #: ⇒ 用纯值 ✓（用户 2026-09-28 重新审视："↑ 键也要再按这么多时间后再松"，明确
        #: 用纯 align_hold_ms，不再额外加端到端延迟）。
        self.base_hold_ms = max(0, int(hold_ms))
        self.timeout_s = float(timeout_s)
        #: 第几次尝试（失败重来会 +1，见 `retry`）—— ⚠ **只用来算重试等待的增量**，
        #: 不再是"上限"了（用户 2026-09-27：不设最多试几次，由「寻路超时时间」收口 ✓）。
        self.attempt = 1
        self.phase = self.ALIGN
        self.note = "对齐到 %s 的 x=%.0f（容许 ±%d px，要稳 %d ms）" % (
            self.ladder_id, self.x, self.tol_px, self.hold_ms)
        self._t0 = None
        self._in_tol_since = None
        self._off_since = None             # 从哪一刻起不在绳上（判"掉下来了"，带容错期）
        #: 有没有某一拍读到过"脚下已经是目标集合"。**只做提示/日志**，不作到达依据
        #:（到达是纯几何的，见 `_arrived`）。
        self._saw_dst_set = False
        #: 第一次判到达的时刻 + 那一刻定下的"再按住方向键多久"（毫秒）+ 到达那句话。
        #: 到达≠立刻松手（用户 2026-09-26 要求），见 update 里那段。
        self._arrived_at = None
        self._arrived_hold = 0
        self._arrived_why = ""
        # ---- 下爬（dir < 0）专属的三个锚点（见 `_jump_down_beat` / `_y_settled`）----
        #: 判定"已在绳上"的那一拍（None = 还没判定上绳）。**下爬**要在这儿起算
        #: "坐标对齐误差时间"（在绳上稳住这么久 ⇒ 松 ↓ 跳下去，用户 2026-09-26 定的）。
        self._on_ladder_since = None
        #: 「**确实确认过在绳上**」—— 感知说在绳上就记下；之后就算感知说不在（多半是
        #: **我们自己刚松开 ↑**，比如"点按重试"那几拍 ✓），只要**位置还在绳段里**就保持
        #: "在绳上"✓（真离开绳段才清 ✓）。存在理由：感知那份 `ladder_id` 带**按键许可**
        #: （没按 ↑/↓ 一律不算 ✓），而执行器自己会松键 ⇒ 只看它就会**自己把自己判成没上绳** ✗
        #: ⇒ 走"点按 / 回对齐"⇒ 又松键 ⇒ 原地打转（用户 2026-09-27 报的"执行器说没上" ✓）。
        #: ⚠ 它是**布尔**、不是时刻，**别**加进 `_ANCHORS`（那张表 `_resume` 会给它加 dt ✗）。
        self._rope_seen = False
        #: 上一拍 `_out` 请他按的**竖直键**（+1 上 / -1 下 / 0 没按 ✓）—— 用来判"这一拍感知
        #: 说不在绳上"是不是**我们自己松的键**（见 `update` 里那段 ✓）。
        self._last_vert = 0
        #: ⭐ **这一拍位置状态广播说"人在本任务那根绳的绳段里"**（纯几何、**与按键许可无关**
        #:   ✓ = `update` 里那个 `_in_rope_span`）—— 全项目只有一处用途：给 `_out` 那条
        #:   "自动按住 ↑"**开例外**（用户 2026-10-02 方案 B ✓：跳之前**不按 ↑**，但人
        #:   **已经挂在绳上**时照旧按住 ⇒ 接着爬；没有 ↑ 就没有"按键许可" ⇒ 广播给不出
        #:   `ladder_id` ⇒ 认不出"已上绳" ⇒ 会去横向对齐 = **在绳上按左右等于松手掉下来** ✗）。
        #: ⚠ 它是**布尔**、不是时刻 ⇒ **别**加进 `_ANCHORS`（那张表 `_resume` 会给它加 dt ✗）。
        self._in_rope_span_now = False
        #: ⭐ **这一拍离绳多远**（世界像素；`None` = 还没有 x 读数 ✓）—— 由 `_align_step` 在**唯一
        #:   一处**记账 ✓（`update` 里那两处 `self.x - px` 都改成读它 ✓）。
        #:   ⚠ 全项目只有两个读者：`walking_to_ladder()`（✅ 就是它要回答的）与"斜跳飞行中"那支 ✓
        #:     —— **别在别处再算一遍距离** ✗（约定 10：一条口径一处实现 ✓）。
        self._last_dx = None
        #: 「**按过跳了**」（`_out` 里 `jump=True` 的拍都会置上 ✓，**一次就够、永不清** ✓）——
        #: "从按下跳到攀爬成功期间不许进 attack"（用户 2026-09-27 ✓）要用它，见 `holds_player` ✓。
        self._jumped_once = False
        #: ⭐ **"按跳之后 y 升过没有"**（用户 2026-10-03 ✓ 口径「A + 发呆重试」）——
        #:   用来把两种情况分开：**压根没挂上**（跳那一下没贴上绳 ⇒ 该退回重试 ✓）
        #:   与 **挂上了但爬不动**（y 先往上走过才停住 ⇒ 照 2026-09-29 那条"继续按住 ↑"✓）。
        #:   `_jump_y` = 按跳那一拍的 y（基准）；`_rose_since_jump` = 之后有没有走过
        #:   `STALL_GAIN_PX`（现成那把"y 动没动"的尺 ✓ 不新造数 ✓）。
        self._jump_y = None
        self._rose_since_jump = False
        #: ⭐ **这一轮强制重走对齐**（只在"没挂上 ⇒ 退回重试"那一轮为 True ✓）：
        #:   因为那时广播可能**还**说"在绳上"（正是误判本身 ✗）⇒ 会当场被 ①' 那条
        #:   "已在绳上 ⇒ 跳过横向对齐"顶回去 ⇒ 重试变成空转 ✗。按跳那一下起就清掉 ✓
        #:   （那时该不该"跳过对齐"已经由 `/` 新的一轮自己决定 ✓）。
        self._force_align = False
        #: ⭐ **"锁定目标在哪边"的注入位**（`() -> +1/-1/0` ✓）—— 由 agent **每拍重挂**
        #:   （`agent._climb_tick` 里那一行 ✓；⚠ 锁定目标会换 ⇒ 必须现读，不许建任务时定死 ✗）。
        #:   ⚠ **与 `DropJob` 同一个属性名**（那边是"跳下绳子朝哪边按"✓）：**注入一处、两处读**
        #:   （约定 10 ✓）；没有目标 / 没注入 / 回调抛异常 ⇒ 读的地方一律当 `0` ✓（不许报错 ✗）。
        #:   本任务的用途只有一处：**到顶后"再按住一会儿"那几拍朝目标按方向键**（用户 2026-10-02 ✓
        #:   见 `_arrive_step` 与 `_arrive_dir` ✓）。
        self._target_dir_fn = None
        #: 「跳下绳梯」第一步（先单独按住方向键一拍）做过了没 —— 只做一次。
        self._press_dir_done = False
        #: 「按跳」的那一拍（点按 TAP_ON_S；None = 还没按）。
        self._jump_off_at = None
        #: 「等待 y 稳定」的锚点：上一次"动过"的 y + 那一刻（见 `_y_settled`）。
        self._y_ref = None
        self._y_still_since = None
        #: 被战斗打断时要"跳过时长"的锚点（见 `_PausableJob`）。
        #: ⚠ `_t0`（任务内部超时）**不在里面**：它由 `interrupted()` **重打**成"进战斗
        #:   那一刻"（用户 2026-09-26 要求"每次进 attack 重新计时"✓）；而且
        #:   `agent.start_climb()` 会把它设成很大的数 ⇒ **真正生效的超时在 agent 那边**
        #:   （`_climb_started` + 设置里的「寻路超时时间」✓，同样按每次进战斗重打 ✓）。
        #: `_arrived_at` 也不在（到达是既成事实，打架那几秒正好把"再按住一会儿"耗完 ✓）。
        #: 下爬那三个都在里面：打架那几秒不是"在绳上稳住"，也不是"在往下落" ✓。
        self._ANCHORS = ("_off_since", "_in_tol_since",
                         "_on_ladder_since", "_jump_off_at", "_y_still_since",
                         "_dir_tap_at",
                         # 中途跳下那两个（2026-09-28 ✓）：挨打那几秒不是"正在跳下"、
                         # 也不是"落地之后那一段按住 ↑" ⇒ 都得往后挪 ✓（漏了会让
                         # `mid_hold_s` 被战斗时长一口吃掉 ⇒ 该按的那几拍白按 ✗）
                         "_mid_jump_at", "_mid_land_at")

    # ---- 对外 ----

    def update(self, now, px, py=None, ladder_id=None, here_sets=None, at_top=None,
               at_bottom=None, ground_y=None, on_rope_pos=None,
               climb_failed=None, climb_stalled=None):
        """喂一拍 → 下一步该干什么。`now` 用 `time.monotonic()` 那种秒。

        ⚠ `px` 是**世界坐标 x**（`WorldState.Player.world_x`），不是画面坐标！
        2026-09-26 踩过：调用方一直喂的是画面检测框中心，而 `self.x` 是世界坐标 ⇒
        `dx` 永远是大数 ⇒ 角色朝一个方向一直走、来回抖（用户报的"卡在 -300~-380"）。
        `py` 从头到尾就是用 `world_y` 的 —— 一个画面一个世界，本身就是自相矛盾的。
        """
        if self._t0 is None:
            self._t0 = now
        if self.phase in (self.DONE, self.FAILED):
            return self._out(0, False)
        # ---- 被战斗打断过 ⇒ 回来这一拍**重新走一遍上绳流程**（见 `_PausableJob`）----
        # ⚠ 用户 2026-09-27 要求 ③：**不管在不在绳上，打断回来都重走一遍** —— 老写法是
        #   "已上绳就接着爬"，可打架那几秒里人可能已经被打下来、或者键被对面丢了 ✗，
        #   带着旧阶段硬接着跑，表现就是"回来以后不动了/一直按住跳"✗。
        # 为什么**没上绳**要退回重新对齐、而不是接着开跳（用户 2026-09-26 报的"跳被吞了"）：
        # 打架期间角色会**转身**（打身后的怪），而转身那一下就会**挪一点位置** ⇒ 原来的
        # "对齐好了"不再成立 ⇒ 直接开跳就是贴着绳边乱跳 ✗。
        # 为什么**已上绳**现在也敢退回：ALIGN 那一段自己认得出"已经在绳上"并**跳过横向
        # 对齐**（见下面那一支）—— 在绳上按左右在游戏里就是"松手"✗，那才是老写法不敢
        # 退回的真正原因 ✓。
        _paused = self._resume(now)
        # ⭐ **"位置还在绳段里"读位置状态广播**（用户 2026-09-27 要求**收编**：
        #   `ClimbJob._at_rope` 那套"自己算几何"**已删** ✗ —— 几何只在
        #   `perception/pos_state.py` 算一次 ✓）。
        #   为什么要这份**不看按键许可**的事实：执行器**自己会主动松开 ↑/↓**
        #   （下爬那一路还会松 ↓ ✓；上爬现在只有"按住/补按"、不松 ✓，但读数也会抖 ✓）——
        #   而 `ladder_id` 带**按键许可**（"没按 ↑/↓ 一律不算在绳上"✓）⇒ 那几十毫秒里它**必然**
        #   变空 ⇒ 拿它当"在不在绳上"就是**循环依赖**：执行器**自己把自己判成没上绳** ✗
        #   ⇒ 走"点按 / 回对齐"那一支 ⇒ **又松开** ✗ ⇒ 原地打转（人明明挂在绳上 ✓）。
        #   这就是用户 2026-09-27 报的"位置状态那行写着绳梯、执行器却说没上"✓。
        # ⚠ **只影响本任务**：走路/寻路照旧只看感知那份 ✓ ——"没按 ↑/↓ 不算在绳上"那条规则
        #   一个字没动 ✓（别顺手把它去掉：那会变回"碰到绳子就卡住" ✗）。
        # ⚠ **别用"位置在绳段里"直接当"已经在绳上"** ✗：人**站在绳底那块面上、从没抓过绳**
        #   时它同样成立 ⇒ 会误触发上面"已经在绳上 ⇒ 跳过横向对齐"⇒ 不先对齐就跳 ✗，
        #   也会让"跳失败 ⇒ 先站住等 y 稳定"（用户 2026-09-27 定的 ✓）永远走不到 ✗。
        #   ⇒ 口径仍是**"记住确实确认过在绳上"**：
        #     · 感知说在绳上 ⇒ 记下（`_rope_seen` ✓，它带按键许可 ⇒ 说明**真的**抓住了 ✓）；
        #     · 感知说不在 ⇒ **只要位置还在绳段里就不清** ✓（那多半是**我们自己刚把键松开**
        #       —— 比如下爬"点按重试"那几拍 ✓，位置当然没变）⇒ 仍算在绳上 ✓；
        #     · 位置也出了绳段（或这一拍读数判不出来 ✓）⇒ 清掉 ✓（那是真离开了 ✓）。
        # ⭐⭐ **斜跳那几拍不许采信"按键许可"**（用户 2026-10-03 ✓ 口径 A）：
        #   斜跳是"**先朝绳走 + 按住 ↑**（第 1 拍）、**第 2 拍才按跳**"（见下面 `_diag_arming`
        #   那一段 ✓）—— 那几拍的 ↑ 是**"为了抓绳"发的** ✗，**不是"已经在绳上"的证据** ✗。
        #   而位置状态那把尺**很宽**（`LADDER_DX=24` / `LADDER_PAD=12`）⇒ 飞行中怪/人的框
        #   扫过绳段就会给出 `ladder_id` ⇒ **许可 + 几何同时成立** ⇒ 下面 `_rope_seen` 一锁上
        #   就"跳过横向对齐、也不按跳"⇒ **在绳下按住 ↑ 发呆** ✗（用户现场：森林迷宫III
        #   底层"一直想往右走、角色往左"，事后就是这种卡住 ✓）。
        #   ⇒ 这几拍把 `_lid_ok` **一律压成 False** ✓（于是下面 `dir>0` 那支会把记忆清掉 ✓
        #     上爬本来就不靠记忆 ✓）；落到绳上之后再采信 ✓。
        #   ⚠ 只压**本执行器**的判据 ✗ —— 感知层那条"没按 ↑/↓ 不算在绳上"**一个字没动** ✓
        #     （别顺手去掉：那是治"碰到绳子就卡住"的规矩 ✓）。
        _diag_now = bool(self._diag_flying) or (self._diag_arming is not None)
        _lid_ok = (ladder_id is not None and str(ladder_id) == self.ladder_id)
        _in_rope_span = bool(on_rope_pos is not None
                            and str(on_rope_pos) == self.ladder_id)
        # ⭐ 存一份给 `_out`（它只有这一个用途：**跳之前也按住 ↑ 的那个例外** ✓，见 `_out` ✓）
        self._in_rope_span_now = _in_rope_span
        # ⭐⭐ **上了非目标绳 ⇒ 通知重启寻路**（用户 2026-10-02 ✓ 治本）：
        #   align 阶段按住 ↑ 是设计（用户 2026-09-27 定的"上爬一路按住 ↑"✓），但角色被
        #   **别的绳**吸住时，位置状态返回 ladder_id=别的绳（非目标）⇒ 立刻重启寻路，不卡在
        #   align（"龙族打猎场"bug：角色被 L1 吸住、往左走、卡左角 ✗）。
        #   ⚠ 只认**带按键许可的 `ladder_id`**（广播说真在绳上 ✓）—— `on_rope_pos`（位置在
        #   绳段里）不认：角色只是经过绳段、还没真吸上，不该重启 ✗。
        #   ⚠ `vert=0`：replan 这一拍不该按 ↑（要重启了，别再按 ↑ 把人按在别的绳上 ✗）。
        if (ladder_id is not None and str(ladder_id) != self.ladder_id
                and self.phase not in (self.DONE, self.FAILED)):
            self.note = ("上了 %s（非目标 %s）⇒ 通知重启寻路"
                         % (ladder_id, self.ladder_id))
            return self._out(0, False, vert=0, replan=True)
        if _lid_ok and not _diag_now:
            # ⭐⭐ **斜跳那几拍不许把"许可"锁成记忆**（用户 2026-10-03 ✓ 口径 A）：那几拍的
            #   ↑ 是"为了抓绳"发的、而位置状态那把尺很宽（`LADDER_DX=24`/`PAD=12`）⇒ 飞行中
            #   扫过绳段就会给 `ladder_id` ⇒ 记忆一锁上就"跳过横向对齐、也不按跳"⇒
            #   **绳下按住 ↑ 发呆** ✗（用户现场 ✓）。
            #   ⚠ `_lid_ok` 本身**不压**（见上面 `_diag_now` 的说明）：斜跳"吸上了"那条判据
            #     读的正是广播 ✓ 压了它就永远吸不上 ⇒ 用例当场红 ✓（真踩过 ✓）。
            self._rope_seen = True
        elif self.dir > 0:
            # ⭐ **上爬一律以广播的 `ladder_id` 为准**（用户 2026-09-27 定的第 1 条：
            #   "**位置状态变化即广播，且绝对权威**" ✓）—— **不留记忆、不用位置兜底** ✗：
            #   上爬那一路**从不松键**（用户定："只有『按住 ↑』和『补按住 ↑』，不能存在
            #   『松开 ↑』和『点按 ↑』" ✓）⇒ 广播**绝不会因为我们自己而变空** ⇒ 它说不在绳上
            #   就是不在绳上 ✓ 一个字都不许打折 ✗。
            #   ⚠ 记忆（`_rope_seen`）在上爬这里**只会害人**：人跳失败退回平台、位置仍落在
            #   绳段里（就站在绳底那块面上 ✓）⇒ 记忆永远不清 ⇒ CLIMB 相一直以为"在爬" ✗
            #   ⇒ 卡在「正爬升中：刚爬 -1」一直按住 ↑ 磨墙 ✗（用户 2026-09-27 报的正是它 ✗）。
            self._rope_seen = False
        elif not self._last_vert:
            # 这一拍我们**本来就没按 ↑/↓**（上一拍输出里 `dir=0` ✓）⇒ "广播说不在绳上"是
            # **我们自己造成的** ⇒ 不算证据、记忆留着 ✓（用户问的"↑ 丢了"就是这一种 ✓）
            pass
        elif not _in_rope_span:
            # 还按着 ↑/↓（不是自己松的 ✗）而且**广播说位置也不在绳段里**（或这一拍没有
            # 世界坐标读数 ⇒ 广播给不出绳号 ✓）⇒ 那是**真离开了**（跳没生效 / 掉下来了）⇒ 清掉 ✓
            self._rope_seen = False
        _on_ladder = bool(_lid_ok or self._rope_seen)
        # ⚠ **不要**在这儿加"人已经在 `dst_set` 里 ⇒ 算到达" —— 试过，被现有用例当场按住 ✗：
        #   `t_climb_flow_rules` 明钉"到达必须**双判据**（y 也得够到绳上端）"，
        #   只看集合会**提前收工** ✗（用户 2026-09-26 定的规矩，不许自己发明判据 ✓）。
        #   "人已经在目标集合里、可这一步还挂着"这种冗余步骤该怎么收，见 agent 那层 ✓。
        #: 还站在**起跳那块平台**上吗（`src_set` = 这条「爬」边的起点集合）—— 没上绳时
        #: 用它分"跳没生效（接着按跳）"和"真掉下来了（容错期后判失败）"（要求 ②）✓
        _in_src = bool(self.src_set) and self.src_set in set(here_sets or ())
        if (_paused >= PAUSE_MIN_S
                and self.phase not in (self.DONE, self.FAILED)
                and self._arrived_at is None):
            self.phase = self.ALIGN
            # 这一轮尝试的锚点**全清**（口径与实现都只有 `_reset_round` 一处 ✓）。
            # ⚠ `clear_jump=False`：这一支**不动** `_jumped_once`（老行为一字不变 ✓）。
            self._reset_round()
            self.note = "被战斗打断 %.1fs ⇒ 重新走一遍上绳流程%s" % (
                _paused,
                "（已经在绳上：跳过横向对齐，接着爬）" if _on_ladder else "")
        # ---- ①'' **这一轮压根没挂上 ⇒ 退回重试**（用户 2026-10-03 ✓ 口径「A + 发呆重试」）----
        # 判据（**与 2026-09-29 那条定稿不冲突** ✓）：`climb_stalled`（广播说 y 在「移动操作
        # 尝试间隔」内没变 ✓）**且** "**按跳之后 y 一次都没往上走过**"（`_rose_since_jump` ✓）
        # ⇒ 那不可能是"挂在绳上爬不动"（真挂上会立刻往上走 ✓）⇒ 是**跳那一下没贴上绳**
        # ⇒ 退回 `ALIGN` 重新对齐 + 重新按跳 ✓；而"升过之后才停住" ⇒ **不退**（继续按住 ↑ ✓
        # 那是 2026-09-29 定稿那条 ✓）。
        # ⚠ **不新造次数上限**：反复重试的兜底就是「寻路超时时间」（用户 ✓ 同约定 157 #2）。
        # ⚠ `_force_align`：广播这会儿**可能还**说"在绳上"（那正是误判本身 ✗）⇒ 不挡住 ①'
        #   那条"已在绳上 ⇒ 跳过横向对齐"的话，重试会被当场顶回去 ⇒ 空转 ✗。
        self._track_rose(py)
        if (self.phase == self.CLIMB and climb_stalled and not climb_failed
                and self._jumped_once and not self._rose_since_jump):
            self._reset_round(clear_jump=True)
            self.phase = self.ALIGN
            self._force_align = True
            self.note = ("这一轮没挂上（按跳之后 y 一次都没往上走）⇒ 退回重来："
                         "重新对齐 + 重新按跳")
        if now - self._t0 > self.timeout_s:
            return self._fail("超时 %.0fs：没能在 %s 上完成上绳" % (
                self.timeout_s, self.ladder_id))

        # ---- ①' **已经在绳上就别再做横向对齐**（战斗打断回来常见，见上面那段）----
        # 在绳上按左右键在游戏里就是"松手" ⇒ 人会掉下来 ✗（这是这个分支唯一存在的理由）。
        # 跳过之后**仍然算重走了一遍流程**：交给 ② 那段按当前状态重新决定
        #（下爬重新起算"稳住 hold_ms"、上爬接着按住 ↑ / 重新判爬不动 ✓）。
        # ⚠ `and not self._force_align`：**"没挂上 ⇒ 退回重试"那一轮**里，广播可能**还**说
        #   "在绳上"（那正是误判本身 ✗）⇒ 不挡住这一支的话，刚退回来就被顶成 CLIMB ⇒ 空转 ✗
        #   （用户 2026-10-03 ✓；按跳那一下起 `_force_align` 就清掉 ✓ 见 `_out` ✓）。
        if (self.phase == self.ALIGN and _on_ladder and not self._force_align
                and not _diag_now):
            # ⚠ `and not _diag_now`（用户 2026-10-03 ✓ 口径 A）：斜跳飞行中广播可能**误报**
            #   "在绳上" ⇒ 不挡住的话会当场被顶成 CLIMB ⇒ 不再按跳、在绳下按住 ↑ 发呆 ✗。
            #   （斜跳自己的"吸上了 ⇒ 收飞行相"那条判据不在这儿、也不受它影响 ✓ —— 那一条
            #     读的是广播原件 ✓ 见 `_align_step` 的斜跳段 ✓。）
            self._handoff_to_climb("已在 %s 上（战斗后回来）⇒ 跳过横向对齐，接着 %s" % (
                self.ladder_id, "爬" if self.dir > 0 else "下爬"))

        if self.phase == self.ALIGN:
            _o = self._align_step(now, px, py, _on_ladder)
            if _o is not None:
                return _o
        _o = self._arrive_step(now, px, py, here_sets, at_top, at_bottom, ground_y,
                               _lid_ok)
        if _o is not None:
            return _o
        return self._climb_step(now, px, py, _on_ladder, _in_src,
                                climb_failed, climb_stalled)

    def _climb_step(self, now, px, py, _on_ladder, _in_src,
                    climb_failed=False, climb_stalled=False):
        """② 上绳 / 「还没上绳」那一大段（`_on_ladder`、`_in_src` 由 `update` 算好传入 ✓）。"""
        # 还没上绳 / 中途掉下来：**给一段容错期**再判失败 —— 按跳那几拍人本来就还在
        # 空中（`ladder_id` 是 None），一离开就判失败会当场误杀。
        # ⚠ 但**站在起跳平台上**不算"在空中"（见下面 ②' 那段）✓
        if _on_ladder:
            # ⚠ 判据必须**和上面同一份**（`_on_ladder` ✓，含那条"位置兜底" ✓）——
            #   以前这里直接看原始参数 `ladder_id` ✗ ⇒ 兜底不生效、"点按重试"那几拍还是会
            #   走进下面"还没上绳"那一支 ⇒ 又松开 ↑ ⇒ 原地打转 ✗（用户 2026-09-27 报的 ✓）。
            self._off_since = None
            self._dir_tap_at = None
            self._retry_stage = ""     # 人已经在绳上了 ⇒ "等 y 稳定/点按"那一小段收干净 ✓
            if self._mid_arm_since is None:
                self._mid_arm_since = now   # ⭐ 上爬"在绳上"从这一刻算（`MID_ARM_S` 门槛 ✓）
            # ---- **下爬（dir < 0）：另一套收尾**（2026-09-26 用户定的新时序）----
            # 用户原话：「判定上绳梯后，经过『坐标对齐误差时间』，松开 ↓ 并执行一个
            # '跳下绳梯' 的操作行为：按住目标 foothold 集合的中心对应的方向键（向量运算
            # 就能解决）→ 按跳 → 松开跳 → 松开方向 → 等待 y 稳定」。
            # 为什么下爬**不再沿绳降到绳底**：绳只是个"把人从平台面上放下去"的抓手 ——
            # 抓住绳时人已经在平台面**下面**了（实测 105090600 的 L1：绳顶 y=-205、平台面
            # y=-208 ⇒ 人比平台面低 3px），松手就是往下落 ✓；按住"朝目标集合中心"的方向
            # 是为了**落点漂到平台中间**（绳常常正挂在平台边上）。
            # ⚠ 下面那条「爬不动了」**只对向上爬有效**（它的前提就是用户说的"在绳上、
            #   不偏离、↑ 没松就一定能上去"）；下爬在绳上只待 hold_ms，不走那段 ✓。
            if self.dir < 0:
                if self._on_ladder_since is None:
                    self._on_ladder_since = now
                    self.note = ("已上绳：按住 ↓ 稳 %d ms 再松手跳下（朝目标集合中心）"
                                 % self.hold_ms)
                    if self.hold_ms > 0:
                        return self._out(0, False, hold_dir=True)
                elif (now - self._on_ladder_since) * 1000.0 < self.hold_ms:
                    return self._out(0, False, hold_dir=True)   # 稳住，↓ 还按着
                self.phase = self.JUMP_DOWN
                self.note = "松 ↓，跳下绳梯"
                return self._jump_down_beat(now, px)
            # ⭐⭐ **「中途跳下」触发点**（用户 2026-09-28 ✓）：**已经在绳上往上爬**的时候，
            #   爬到「高度」就转去"跳下来"（见 `MID_JUMP` 相 ✓）。
            #
            # ⚠⚠ **判据方向 2026-09-28 改过**（用户："把右下爬跳到左上 A+B 也修掉"✓）：
            #   现在是 **`py <= mid_y`** = "**人的 y 已经爬到「高度」或更高**" ✓
            #   （世界 y **越小越靠上** ✓）。原来是 `py >= mid_y` ✗ ⇒ 那是"人还在该高度的
            #   **下方**" ⇒ **一上绳（y 最大）就满足** ⇒ 当场触发、还把 `_mid_jumped` 锁死
            #   ⇒ 之后**一路爬到顶也不跳** ✗（用户报的"**他爬到顶了都没跳出去**"✓）。
            #   ⚠ **为什么配 50 是合理的**：真实数据 L2 是 `y1=-115(上端) … y2=231(下端)`
            #     ⇒ 50 落在绳的**中上段** ⇒ "爬到那儿再往左跳"正是用户要的 ✓（原来那句
            #     "配大了就等于上去就跳"是**错的**，真相反过来 ✓）。
            #
            # ⚠⚠ **门槛 `MID_ARM_S`**（同一轮加 ✓）：必须**已经在绳上稳了一小会儿**才判 ——
            #   刚"吸上绳/跳上绳"的那一瞬间 `_on_ladder` 就为真、`py` 又常常刚好满足条件
            #   ⇒ 会在**还没真开始爬**的时候就把 `_mid_jumped` 用掉 ✗（防抖 ✓）。
            #   ⚠ 起点用**独立字段** `_mid_arm_since`（**不动** `_on_ladder_since` —— 那个是
            #     下爬分支专用的计时起点，混用会改掉下爬的"稳住 hold_ms"行为 ✗）。
            # ⚠ **只触发一次**（`_mid_jumped` ✓）：跳下来之后人可能会再贴到绳上，不加这道锁
            #   就会"上去了又跳"来回抖 ✗。
            # ⚠ 放在**下爬分支之后**：下爬有它自己那套收尾，别掺和 ✗。
            if (self.dir > 0 and not self._mid_jumped and self.mid_dir
                    and self.mid_y is not None and py is not None
                    and float(py) <= self.mid_y
                    and self._mid_arm_since is not None
                    and (now - self._mid_arm_since) >= MID_ARM_S):
                self._mid_jumped = True
                self.phase = self.MID_JUMP
                self.note = ("爬到中途：y=%.0f 已到「高度」%.0f ⇒ 跳下绳梯（向%s），↑ 不松"
                             % (float(py), self.mid_y,
                                {"center": "目标中心", "left": "左", "right": "右"}
                                .get(self.mid_dir, self.mid_dir)))
                return self._mid_jump_beat(now, px)
            # ⭐ 向上爬**只认广播**（用户 2026-09-28 核心思路：**位置状态机全权掌握坐标→状态的
            #   解析，执行器只负责发键和通知，不做任何坐标运算判定** ✓）：
            #   · 2a `climb_failed`（x 偏出「坐标对齐误差范围」）⇒ 攀爬失败 → 交给 agent 延迟重启；
            #   · 2c `climb_stalled`（y 在「移动操作尝试间隔」内没变）⇒ 补发按住 ↑（`reassert` ✓）；
            #   · 2b `at_ladder_top` 已由 `_arrive_step` 判（到顶收工 ✓）。
            #   ⚠ 原来这里自己比 y（`_stalled_by` / `_best_y` / `_best_at` / `_reassert_at` /
            #     `reassert_s` 那一套）**全删** ✗ —— 那是执行器做坐标判定的最后一处 ✗。
            if climb_failed or climb_stalled:
                # ⭐⭐ **两支同一动作：按住 ↑ + 补按，继续爬**（2026-09-29 用户流程图定稿 ✓：
                #   「失败后不是应该走流程吗？**至少得看到有按跳之后才可能接收失败**」——
                #   这两种广播都发生在"人已在绳上"⇒ 按流程图没有"失败"这个出口 ✓）：
                #   · 原来的 climb_failed ⇒ `_fail` ⇒ agent delay=0 立即重试 ⇒ 每拍失败+
                #     重试、↑ 被反复松开 ⇒ y 更卡 ⇒ 风暴自续（现场 0.3s 刷 1500 次
                #     attempt、OSD「第 1173 次尝试」✗）；
                #   · 也**不回对齐**：在绳上按左右 = 松手掉下来 ✗（见 ①' 那条捷径的理由 ✓）；
                #   · x 偏出不用管：真爬起来游戏会把人居中（现场 log：dx 22.8 → 2 ✓）；
                #   · 真爬不上去由「寻路超时时间」兜底（用户 2026-09-29 ✓）。
                self.note = ("广播说%s ⇒ 按住 ↑ 继续爬（在绳上按左右会松手；"
                             "x 偏出爬起来会自己居中）"
                             % ("x 偏出「坐标对齐误差范围」" if climb_failed
                                else "y 没变（爬不动）"))
                return self._out(0, False, hold_dir=True, reassert=True)
            # **已经上绳 ⇒ 只按方向键（↑），不再按跳**（用户 2026-09-26 定的规则：
            # "按 ↑ 直到玩家的真实世界坐标 ≤ 绳梯上端连接的 foothold 的 y"）。
            # 跳键**只用来贴上绳**：一直按住它，人会卡在绳上/绳顶不往上走
            #（用户实测：命令前往左上平台时"还在绳上、离平台还差一截"）。
            # 注意这里要 `hold_dir`：不按跳也得把 ↑ 按住，否则这一拍什么都不按=站着不动。
            # ⚠ 目标取 `_target_y()`（上爬 = 绳上端、下爬 = 落地面）—— 别在这儿再写一遍
            #   "目标是谁"，否则改口径时提示会和判据对不上（见 `_target_y` 的说明）。
            self.note = "已上绳：按住 %s 往上爬（到 y ≤ %.0f 算到）" % (
                "↑" if self.dir > 0 else "↓", self._target_y())
            return self._out(0, False, hold_dir=True)
        # ⚠ 人**不在绳上** ⇒ 「在绳上稳了多久」的起点清掉（下一回上绳必须重新攒够门槛 ✓）
        self._mid_arm_since = None
        # ---- ②' 还没上绳、人**还站在起跳那块平台上** ----
        # 用户 2026-09-27 定的流程（这一版）：对齐 x → 按跳 + 按住 ↑ → **如果还没上绳
        # （人还在起跳那块 foothold 集合里）⇒ 回到对齐 x 重新开始**（整个流程重来一遍）。
        # 所以一轮只按**一下**跳（点按，不是按住：跳键按住在游戏里只算"按过一次"，
        # 本机 `KeyState` 也只在键集**变化**时才发键 ⇒ 一直 True 等于只发过一次 ✗），
        # 下一拍就退回 ALIGN 重走 —— 于是**两次尝试之间的间隔 = ① 那个保持窗口**
        # （`hold_ms` = 设置里的「坐标对齐误差时间」+ 端到端延迟 ✓，不新造常数 ✓）。
        # ⚠ 站地上**不算"掉下来了"**（不记 `_off_since`），否则 2 秒就开始判失败、
        #   和"重来"这条直接打架 ✗；真掉下来（离开那块平台、又不在绳上）那条路照旧 ✓。
        # ⚠ 重来那一轮里**方向键继续按着**（`_retrying`）：用户原话"按跳 + 按住 ↑" ——
        #   中间松手，人在空中那一下就抓不住绳 ✗（抓上了会自动接"已在绳上"那条 ✓）。
        # ⚠ 退回对齐**之前**还补一次**目标方向（↑/↓）的点按**（用户 2026-09-27 要求）：
        #   "先松 `TAP_PERIOD_S - TAP_ON_S`、再按 `TAP_ON_S`" —— 因为按跳那一拍 ↑/↓ 是
        #   按着的，不松开再按就不算"新的一次按下" ✗（见 `_dir_tap_at` 那一段）。
        if _in_src:
            self._off_since = None
            # ---- ③ 跳失败之后：**直接补按一次目标方向**（用户 2026-10-01 ✓）----
            #   ⭐ **不再"先站住等 y 稳定 1 秒"了**：`_in_src` 这个入口本身就是**位置状态
            #      权威广播**（`here_sets` 含 `src_set`）⇒ 人已经站稳在起跳平台 ✓ ——
            #      人还在空中往下落时脚下没有 foothold、`here_sets` 不会是 `src_set` ⇒
            #      走到这里就已是"广播说落稳了" ✓。原来靠 `_y_settled`（y 在 1s 内 8px 静）
            #      那个**时间/几何**兜底纯属多余 ✗（原地起跳失败、斜跳吸上又掉下，两种落回
            #      都已被广播权威覆盖 ✓）。
            #   ⚠ **上爬没有"点按 ↑"**（用户 2026-09-27 更正："向上攀爬只有「按住 ↑」和
            #     「补按住 ↑」，不能存在「松开 ↑」和「点按 ↑」"）⇒ 上爬是"**按住 ↑ +
            #     `reassert`**"（只再发一次 PRESS ✓ 不先松 ✓，见 `_retry_all_up`）；
            #     **下爬**才走老的"先松再按"（`TAP_PERIOD_S - TAP_ON_S` + `TAP_ON_S` ✓）。
            #   补按完才回 ① 对齐 x ⇒ **后续的跳**自然排在"补按 + 对齐"之后 ✓。
            if self._retry_stage == "tap":
                # ⭐ **上爬没有"点按 ↑"**（用户 2026-09-27 明确："向上攀爬只有「按住 ↑」和
                #   「补按住 ↑」，**不能存在「松开 ↑」和「点按 ↑」**"）⇒ 上爬这一小段 =
                #   **按住 ↑ + 补按一次**（`reassert=True` = 只再发一次 PRESS ✓，绝不先松开 ✓），
                #   然后回对齐重走一遍 ✓ —— 见 `_retry_all_up` ✓。
                if self.dir > 0:
                    return self._retry_all_up(now)
                # ---- 下爬：走老逻辑（**先松再按**才算"新的一次按下"✓，见 `_dir_tap_at` 的说明）。
                #      为什么它能"先松"：那几拍人已经**主动离开绳**（"跳下绳梯"那一相 ✓）⇒
                #      松 ↓ 是语义本身 ✓，和上爬"不能松开 ↑"不冲突 ✓。
                #      按跳那一拍 ↓ 本来是**按着**的 ⇒ 不松开再按，对面只看到"一直按着" =
                #      **一次都没新按过** ✗ ⇒ 那一下白按 ✗；补一下就是"再试着直接抓一次绳" ✓。
                if self._dir_tap_at is None:
                    self._dir_tap_at = now
                    self.note = ("还没上绳（还站在 %s 上）⇒ 先松开 ↓ 再点按一次"
                                 "（要「松开再按」才算新的一次）" % self.src_set)
                    return self._out(0, False)            # dir=0 ⇒ 把 ↓ 松开
                _tap_dt = float(now) - self._dir_tap_at
                if _tap_dt < TAP_PERIOD_S - TAP_ON_S:
                    self.note = "还没上绳 ⇒ 再松 %.0f ms（松够了才好「重新按一次」）" % (
                        (TAP_PERIOD_S - TAP_ON_S - _tap_dt) * 1000.0)
                    return self._out(0, False)            # 松开中，别急
                if _tap_dt < TAP_PERIOD_S:
                    self.note = ("还没上绳（还站在 %s 上）⇒ **点按一次 ↓**"
                                 "（再试着直接抓绳）" % self.src_set)
                    return self._out(0, False, hold_dir=True)   # 这一拍才算"新按下"的 ✓
                return self._retry_back_to_align("点按过 ↓")
            if not self._jump_tried:
                # ⚠ 这里原来也有一道"按跳许可"（`_at_entry` ✓）—— 2026-09-27 用户明确否掉
                #   （"**对齐了就按跳开始爬啊，不需要判定别的**" ✓）⇒ **一起拆了** ✓。
                #   这一相里人可能已被挤走 / 被打飞 ⇒ 那交给"跳了没上去 ⇒ 回对齐重来"
                #   那一小段（就在下面 ✓）判，不再用 y 位置在按跳前拦 ✗。
                self._jump_tried = True
                self.note = "还没上绳（还站在 %s 上）⇒ 按跳 + 按住 %s" % (
                    self.src_set, "↑" if self.dir > 0 else "↓")
                return self._out(0, True)                 # 按跳 + 按住方向
            # ---- 跳也按过了、位置状态广播仍说"还站在起跳平台" ⇒ **直接进补按阶段** ----
            self._retry_stage = "tap"
            self._jump_tried = False
            self.note = ("还没上绳（还站在 %s 上）⇒ 补按目标方向后回对齐"
                         % self.src_set)
            # 这一拍只把阶段拨到"补按"（不横挪 / 不按跳 ✓）；上爬的 ↑ 由 `_out` 补上 ✓
            return self._out(0, False)
        if self._off_since is None:
            self._off_since = now
        elif (now - self._off_since) >= OFF_LADDER_GRACE_S:
            return self._fail("从 %s 上掉下来了（%.0fs 没回到绳上）" % (
                self.ladder_id, OFF_LADDER_GRACE_S))
        # 不知道起点集合（手工建的任务 / 老调用方）⇒ 退回老行为：一直按住跳
        return self._out(0, True)

    def _arrive_step(self, now, px, py, here_sets, at_top, at_bottom, ground_y,
                     on_rope):
        """到达 / 「跳下绳梯」相（`None` = 还没到，落到 CLIMB ✓）。"""
        if self._arrived_at is not None:
            # ⚠ 这里**只有向上爬**会走到（下爬在判到到达那一拍就直接收工了，见下面那段），
            # 所以"到达后再按住一会儿"只是 ↑ 的语义（用户 2026-09-26：↑ 要延迟『坐标对齐
            # 误差时间』再松）。2026-09-28 用户重新审视：**时长用纯「坐标对齐误差时间」**
            # （`base_hold_ms`，不含端到端延迟 ✓）—— 理由是**游戏机制**（"迈上平台"那一步
            # 要按着 ↑），跟读数延迟无关；端到端延迟只补偿在「对齐稳住」那边（对齐依赖读数 ✓）。
            if (now - self._arrived_at) * 1000.0 < self._arrived_hold:
                # ⭐ **到顶之后朝「锁定目标」那边按住方向键**（用户 2026-10-02 ✓ 原话："攀爬
                #   (追击)优化：到顶时如果存在锁定目标，就按住向着该目标的方向键（注意后续
                #   chase 的方向键处理）"）—— 这一段 ↑ 还要按住（游戏里"迈上平台"那一步 ✓），
                #   顺手把**水平方向**也给上 ⇒ 一落地就朝目标走 ✓（不然要等这一小段过完、
                #   由 chase 接手才动 ✓）。
                #   ⚠ **方向与后续 chase 用同一处口径**（就是用户提醒的那件事 ✓）：两边都是
                #     "**画面 x 的左右**"（chase 那边是 `_steer(target.x - px)`、`px = ws.player.x` ✓
                #     见 `agent.tick` ✓）⇒ 交接那一拍**不会翻向** ✓（`KeyState` 只在键集变化时
                #     才发键 ⇒ 方向一样时对面看到的是"一直按着" ✓）。
                #   ⚠ **没有锁定目标 / 目标正好同列 ⇒ `_arrive_dir()` 给 0** ⇒ 与加这个功能之前
                #     **一字不差**（只按住 ↑ ✓ 兼容底线 ✓）。
                return self._out(self._arrive_dir(), False, hold_dir=True)
            self.phase = self.DONE
            self.note = self._arrived_why
            return self._out(0, False)

        # ---- 下爬的「跳下绳梯」相：**落地**的几个判据（见 `_landed`）----
        # ⚠ 必须排在下面"不在绳上 ⇒ 判掉下来了"那条**之前**：这一相是**主动**离开绳子的
        #   （按住左右方向键在游戏里就是松手），`ladder_id` 当然是 None —— 拿它当"掉下来了"
        #   会在 OFF_LADDER_GRACE_S 之后把刚跳下去的人判成失败 ✗。
        if self.phase == self.JUMP_DOWN:
            _why = self._landed(now, py, here_sets, at_bottom=at_bottom,
                                ground_y=ground_y, on_rope=on_rope)
            if _why:
                self.phase = self.DONE
                self.note = _why
                return self._out(0, False)      # 落地即松手（方向键也一起松）
            return self._jump_down_beat(now, px)
        # ---- ⭐ 「中途跳下」（**上爬**中途，用户 2026-09-28 ✓）----
        # ⚠ 与 `JUMP_DOWN` **同一个理由**必须排在"不在绳上 ⇒ 判掉下来了"那条**之前** ✗：
        #   这一相本来就是**主动**离开绳（跳下来 ✓）⇒ `ladder_id` 当然没了 ⇒ 拿它判"掉下来了"
        #   会在 OFF_LADDER_GRACE_S 之后把刚跳下的人判成**失败** ✗（同下爬那条注释 ✓）。
        if self.phase == self.MID_JUMP:
            if self._mid_land_at is None:
                _why = self._mid_landed(now, py, on_rope)
                if _why is None:
                    return self._mid_jump_beat(now, px)      # 还在落 ⇒ 走那一相的时序 ✓
                self._mid_land_at = now                      # = 用户说的"**返回成功**"那一刻 ✓
                self.note = _why + "（↑ 再按住 %.0f ms 才松）" % (self.mid_hold_s * 1000.0)
                return self._out(0, False, hold_dir=True)    # ⚠ **先不松 ↑** ✓
            # ⭐ 落地之后**再按住 ↑ `mid_hold_s`** 才松（用户原话："直到**返回成功或失败后**
            #   再经过「**移动操作尝试间隔**」松开"✓）
            if (now - self._mid_land_at) < self.mid_hold_s:
                return self._out(0, False, hold_dir=True)    # ⚠ 还是不松 ↑ ✓
            self.phase = self.DONE
            self.note = ("中途跳下：已落地、↑ 又按住 %.0f ms ⇒ 收工"
                         % (self.mid_hold_s * 1000.0))
            return self._out(0, False)                       # 到这里才真松（方向与 ↑ 一起 ✓）
        why = self._arrived(py, here_sets, at_top,
                            at_bottom=at_bottom, ground_y=ground_y)
        if why:
            self._arrived_at = now
            self._arrived_why = why
            # ⚠ 不能 `max(1, …)`：误差时间设成 0 = **要立刻松手**（老行为），
            # 硬留 1 ms 会让"这一拍就该收工"的用例（和用户自己设 0 的情况）卡住 ✗。
            # ⭐ 用**纯的**「坐标对齐误差时间」（`base_hold_ms`），不是被端到端延迟加长后的
            #   `hold_ms`（那个是给「对齐稳住」用的 ✓）—— 用户 2026-09-28 重新审视 ✓。
            self._arrived_hold = max(0, int(self.base_hold_ms))
            # ⚠ **下爬（dir < 0）没有"再按住一会儿"这一步**（2026-09-26 用户定的新时序）：
            # 下爬的到达发生在「跳下绳梯」**落地**那一刻，落地后再按住水平方向键 hold_ms
            # 会顺着平台走出去 ✗（用户口径："方向键按住到 y 稳定为止"⇒ 落地就松手）。
            # ⇒ 直接收工；`_arrived_at` 不会被置上，上面那段"再按住"就只剩 ↑ 会走 ✓。
            if self.dir < 0 or self._arrived_hold <= 0:
                self.phase = self.DONE
                self.note = why
                return self._out(0, False)
            # ⭐ 到顶那一刻就把**朝目标的方向**给上（用户 2026-10-02 ✓ 见上面 `_arrived_at`
            #   那一支的说明 ✓）—— 同一处口径（`_arrive_dir()` ✓），别在这儿另写一份 ✗。
            _ad = self._arrive_dir()
            self.note = ("%s（再按住 ↑ %d ms 再松%s）"
                         % (why, self._arrived_hold,
                            "" if not _ad
                            else "，并朝目标按住 %s" % ("→" if _ad > 0 else "←")))
            return self._out(_ad, False, hold_dir=True)

        return None

    def _handoff_to_climb(self, note):
        """⛓ ALIGN → CLIMB 的交接：**唯一一处**（约定 10 ✓）。

        谁调（两个）：
          · `update` 里"**已在绳上**（战斗后回来）"那支 ✓（口径没变 ✓）；
          · `_align_step` 里"**斜跳吸上绳**"那一支 ✓（用户 2026-10-03 现场：
            "现在一跳上绳立马就跳下来了" ✗ —— 见那边的长注释 ✓）。

        为什么要抽出来：这一串是"**这一轮尝试的全部锚点**"，抄一遍必漏一个 ✗ ——
        漏掉哪个都是"脏状态带到下一轮"（`_armed_at` 漏 ⇒ agent 拿旧对齐时刻复核；
        `_diag_arming` 漏 ⇒ 下一拍又按一次跳 ✗ ⇒ 正好就是用户报的那个"跳下来" ✗）。

        ⚠ 「人已经在绳上」不是"对齐完成"那件事 ⇒ `_armed_at` 哨兵也清掉：不然 agent 会把
          **上一次**对齐的时刻当成新的一次去复核（那一步早就跳过了 ✓）。
        """
        self._in_tol_since = None
        self.note = str(note)
        self.phase = self.CLIMB
        self._retrying = False          # 已经在绳上了 ⇒ 不再是"回来重来"那一轮 ✓
        self._jump_tried = False
        self._armed_at = None
        self._retry_stage = ""          # 点按/等 y 那一小段也收干净（人已经在绳上）✓
        self._dir_tap_at = None         # 那一轮的点按也收干净（点按本身把它抓上来了 ✓）
        self._diag_flying = False       # "斜跳飞行中"也收干净（已经吸上了 ✓）
        self._diag_y0 = None            # 起跳高度 / 起跳时刻也收干净（吸上了用不着 ✓）
        self._diag_left = False
        self._diag_at = None
        # ⚠ 这里**不需要**清 `_diag_arming`（也刻意不留那一行 ✗ —— 它是个**测不到**的防御）：
        #   两个入口都保证进门时它就是空的 —— `update` 那支靠 `not _diag_now` ✓（那个判据
        #   里就含 `_diag_arming is None` ✓）；`_align_step` 的吸上支只在 `_diag_flying`
        #   为真时进 ⇒ 而"按跳"那一拍已经把 `_diag_arming` 清掉了 ✓。
        #   （反向验证实测：把那一行删掉，用例照样绿 ⇒ 说明它永远不生效 ✓。）

    def _align_step(self, now, px, py, _on_ladder):
        """① 对齐相：斜跳 / 横向对齐 / 按跳（`None` = 对齐好了，落到下一段 ✓）。"""
        # ⭐ **这一拍离绳多远 —— 唯一记账**（`_last_dx` ✓，用户 2026-10-02）：
        #   读者两处：`walking_to_ladder()`（"还在起跳距离外朝绳走么" ✓ 给 agent 每拍复核用 ✓）
        #   与下面"斜跳飞行中"那一支 ✓ ⇒ **一处算、两处读** ✓（约定 10；别在别处再算一遍 ✗）。
        self._last_dx = None if px is None else (self.x - float(px))
        # ---- ①'' **斜跳飞行中：朝绳走 + 按住 ↑**（用户 2026-09-27 现场）----
        # 原话："现在斜跳上绳梯会有「**经过绳梯却没有上去**」的现象，**空中吸附绳梯的
        #   条件是「正在按住 ↑」**"。
        # 为什么单开这一段：斜跳是"按住朝向 + 跳"跳出去的 ✓，但**跳完那一拍**开始就走回
        #   下面的对齐逻辑了 —— 它每拍发的是"**只按水平方向**"（`_out(sign, False)`
        #   ⇒ `dir=0`）✗ ⇒ **↑ 被松开** ⇒ 人从绳梯旁边飞过去**吸不上** ✗。
        # 所以飞行期间：朝绳走（`move=sign`）+ **按住 ↑**（`vert=1`）、**不再按跳**（一轮一次 ✓）。
        # ⚠ 一律按 **↑**（不是 ↓）：用户给的条件就是"空中吸附绳梯要按住 ↑" ✓ —— 下爬开局
        #   吸上绳也一样，吸上之后才由 CLIMB 相按 ↓ 往下走 ✓。
        # ⚠ 结束只有两条路：吸上绳 ✓ / **落回起跳高度**（其间必须**离开过**一个「坐标对齐
        #   误差范围」，否则刚起跳那几拍就自己结束了 ✗）⇒ 之后交回下面的老逻辑 ✓。
        if self._diag_flying:
            if _on_ladder:
                # ⭐⭐ **吸上绳 ⇒ 本拍就交接到上爬，而且这一拍只按住 ↑**
                #   （用户 2026-10-03 现场原话："**现在一跳上绳立马就跳下来了**"✓）：
                #   以前这里只清掉"飞行中"就**继续往下走** ✗ ⇒ 落到下面"斜跳第 1 拍起手 /
                #   对齐按跳"那两支 ⇒ ① **按住左右**（在绳上按左右 = **松手** ⇒ 掉下来 ✗）
                #   ② 下一拍**又按一次跳**（在绳上按跳 = **跳下来** ✗）—— 现场 `behavior.log`
                #   实证（17:03:54）：`climb_on_ladder v=1` 之后紧接着两条
                #   "斜跳上绳：离绳 -12 px ⇒ **先按住 ← 朝绳走**" + "⇒ **按跳**"，
                #   然后 `climb_on_ladder v=0`（掉了）⇒ 一秒多一轮**死循环** ✓。
                #   ⇒ 现在：交接走 `_handoff_to_climb`（**唯一一处** ✓ 它会把这一轮的锚点全清，
                #     包括 `_diag_arming` —— 那正是"下一拍又按一次跳"的来源 ✗），
                #     本拍返回"只按住 ↑"（不按跳、不按左右 ✓）。
                #   ⚠ 交接**必须在本拍**（不能拖到下一拍）：`agent` 的 `route_diag` 判"吸上 /
                #     没吸上"看的就是**这一拍相有没有变成 CLIMB**（`agent.py` 那段 ✓）——
                #     拖一拍会被记成"结束·没吸上"✗（用例当场红 ✓ 真踩了 ✓）。
                self._handoff_to_climb("斜跳吸上 %s ⇒ 交给上爬"
                                       "（本拍只按住 ↑：不按跳、不按左右 ✓）" % self.ladder_id)
                return self._out(0, False, vert=1)
            elif py is not None:
                if self._diag_y0 is None:
                    self._diag_y0 = float(py)
                if abs(float(py) - self._diag_y0) > self.tol_px:
                    self._diag_left = True
                elif self._diag_left:
                    self._diag_flying = False    # 落回起跳高度 ⇒ 这一跳结束 ✓
            # ⚠ **兜底**：飞行相**总时长**超过「卡住判定时长」⇒ 这一跳**无论吸没吸上、落没落回
            #   起跳高度**都结束，交回下面的老逻辑 ✓（不新造时长：用的就是攀爬那件
            #   「卡住判定时长」✓）。
            #   ⛔ 2026-09-28 修：原来只兜"**没离开过**起跳高度"（`not self._diag_left`）✗ ——
            #   那是给"这一跳根本没飞起来"兜的；可人一旦**离开过**起跳高度（`_diag_left=True`）
            #   而**既没吸上绳、也没落回起跳高度**（斜跳落到了绳旁另一个高度 / 或挂在绳上广播
            #   还没判"在绳上"）⇒ 兜底失效 ⇒ **永远卡在飞行相** ✗（用户 2026-09-28 报
            #   "一楼到二楼又出问题、斜跳飞行会卡" ✗）。所以改成**只看总时长** ✓。
            if (self._diag_flying and self._diag_at is not None
                    and (float(now) - self._diag_at) >= self.stall_s):
                self._diag_flying = False
            if self._diag_flying:
                _dxf = self._last_dx          # 本拍离绳多远（本函数开头那**唯一一处**算的 ✓）
                _sgf = 1 if _dxf > 0 else (-1 if _dxf < 0 else 0)
                self.note = ("斜跳飞行中：朝绳%s + **按住 ↑**"
                             "（空中吸绳要 ↑ 一直按着，跳不再按 ✓）"
                             % ("→" if _sgf > 0 else ("←" if _sgf < 0 else "（已对上）")))
                return self._out(_sgf, False, vert=1)

        dx = self._last_dx          # 本拍离绳多远（本函数开头那**唯一一处**算的 ✓）
        # ⭐ **斜跳第 2 拍**（上一拍已经发过"朝绳走" ⇒ 这一拍**才按跳** ✓，见下面第 1 拍那段）——
        #   ⚠ 放在 `|dx| > tol` 判断**之前**：朝绳走了一步可能就进容差了，那一拍**照样要跳** ✓
        #   （这一轮的目的就是跳上去 ✓）。`_out` 里按了跳会清 `_align_pressed` ⇒ 下一轮又要点 ✓。
        if self._diag_arming is not None:
            _sgn = 1 if dx > 0 else (-1 if dx < 0 else 0)
            self._diag_arming = None
            self._diag_done = True          # 一轮只斜跳一次（这一拍才算真跳了 ✓）
            self._diag_flying = True        # 跳出去 ⇒ 进"飞行相"（见上面那段 ✓）
            self._diag_y0 = None if py is None else float(py)
            self._diag_left = False
            self._diag_at = float(now)
            self._press_dir = _sgn
            self._press_at = now
            self.note = ("斜跳上绳：离绳 %.0f px（区间 %d~%d）⇒ **按跳**"
                         "（方向键上一拍已经发过 ✓）"
                         % (dx, self.near_px, self.jump_start_px))
            # ⚠ 竖直方向**一律 ↑**（`vert=1`，不是 `self.dir`）：用户给的条件是
            #   "**空中吸附绳梯要按住 ↑**" —— 下爬那一跳也在空中，同样得按 ↑ 才吸得上
            #   （吸上之后才由 ③ 那一相按 ↓ 往下走 ✓）。
            return self._out(_sgn, True, vert=1)   # 朝绳走 + 按跳 + 按住 ↑ ✓
        if abs(dx) > self.tol_px:
            self._in_tol_since = None
            sign = 1 if dx > 0 else -1
            # ---- ①' **斜跳上绳**（用户 2026-09-27 的设计）----
            # 原话："现在利用「起跳距离范围」设计「斜跳上绳」逻辑，要求使用「开始对齐绳梯x
            # 的距离」参数兼容旧的「对齐x原地起跳上绳」逻辑" ⇒ 一段里**两个区间**：
            #   · `开始对齐绳梯x的距离`(near_px) < |dx| ≤ `起跳距离`(jump_start_px)
            #     ⇒ **斜跳**：按住朝绳的方向 + 点按跳（斜着过去 ✓，省掉"站住再原地跳"那段 ✓）；
            #   · |dx| ≤ near_px ⇒ **老逻辑一个字没改**（点按对齐 → 站住 → 原地起跳 ✓）；
            #   · |dx| > 起跳距离 ⇒ 老逻辑"一口气按住走"（离太远斜跳够不着 ✗）。
            # ⚠ 这里原来还有一道"人得站在绳底那块面上"的许可（`_at_entry` ✓）—— 2026-09-27
            #   用户明确否掉（"**对齐了就按跳开始爬啊，不需要判定别的**" ✓）⇒ 与原地起跳
            #   **同一道门一起拆** ✓（口径只有一条：**对齐 x 就按跳** ✓）。
            # ⚠ **一轮只斜跳一次**（`_diag_done` ✓）：跳完继续朝绳走 ⇒ 近了自然交回老逻辑；
            #   每拍都按跳就成了"一路乱跳" ✗（`retry()` / 被打断重走时会重新武装 ✓）。
            # ⚠ `jump_start_px` = 0（默认）⇒ 整条**关掉** ⇒ 与加这个功能之前**完全一致** ✓。
            # ⛔⛔ **2026-09-28 去掉 `and not self._diag_done`**（用户原话："我从未提过
            #   「一轮只斜跳一次」这个限制，**只要满足条件就可以无限斜跳**"✗）。
            #   ⚠ 那条限制的**后果**（用户当场报的 bug ✓）：本轮斜跳过一次之后 `_diag_done`
            #     为 True ⇒ 这一档被挡住 ⇒ 流程落到下面"先朝绳点按一次"那支 ⇒ 画面上显示成
            #     "**在对齐 x 范围外触发了对齐**"✗（本该斜跳 ✓）。
            #   ⚠ **不会因此每拍都跳**：斜跳本身是"第 1 拍只发方向、第 2 拍才按跳"✓，按下
            #     那一拍就进 `_diag_flying`（斜跳飞行中）⇒ **由它防重入** ✓；落回 / 吸上才
            #     结束 ⇒ 之后只要**再次满足** `near_px < |dx| ≤ jump_start_px` 就**再斜跳一次** ✓
            #     （这正是用户要的"无限斜跳"✓）。
            #   ⚠ `_diag_done` 的**写点暂时留着**（`retry` / 复位那几处）—— 它**已不再被读**，
            #     不影响任何行为 ✗；清它面比较大（7 处），下次顺手清 ✓。
            if (self.jump_start_px and abs(dx) > self.near_px
                    and abs(dx) <= self.jump_start_px):
                # ⭐ **第 1 拍：只发"朝绳走"**（用户 2026-09-28 要求："斜跳也**先发方向键、
                #   下一拍再按跳**" ✓）—— 同一次 tick 里把"方向"和"跳"一起发，游戏里未必算
                #   "按住方向再跳"（`KeyState` 一次下发多个键**不保证顺序** ✗），与
                #   「跳下绳梯」那条**同一个理由** ✓ ⇒ 记下"起手了"（`_diag_arming` ✓），
                #   **这一拍不按跳** ✓（下一拍照样要跳，哪怕已经进容差 ✓，见 `update` 顶上那段）。
                self._diag_arming = float(now)
                self._press_dir = sign      # 记成"正按着这边"（对齐延迟的记账要一致 ✓）
                self._press_at = now
                self.note = ("斜跳上绳：离绳 %.0f px（区间 %d~%d，且人正站在这块面上）"
                             "⇒ **先按住 %s 朝绳走**（下一拍再按跳 ✓）"
                             % (dx, self.near_px, self.jump_start_px,
                                "→" if sign > 0 else "←"))
                # ⚠ 竖直方向**交给 `_out` 那条"自动按住 ↑"**（`vert=None` ✓，用户 2026-10-02）：
                #   这一拍**还没按跳** ⇒ 第一次爬的这一轮**不按 ↑**（旧写法写死 `vert=1` ⇒
                #   一进这个区间 ↑ 就按住 ✗，"从任务下达一直被按住"里有它一份 ✓）；
                #   已经按过跳 / 人已在绳段里 ⇒ 由那条规则照旧按住 ✓（例外见 `_out` ✓）。
                return self._out(sign, False)   # 只朝绳走（**不按跳**；↑ 由规则决定 ✓）
            # 「**对齐绳梯移动延迟(ms)**」（用户 2026-09-27 加的参数）：对齐 x 时
            # **两次按下方向键之间至少要隔这么久**。怎么算"一次按下"：**同方向的连续
            # 按住算一次**（`_press_dir` 记着现在按着哪边）—— 所以远距离那种"一口气
            # 按住走"天然满足 ✓（而且远距离点按会走得太慢、直接撞超时 ✗）。
            # 真正受它约束的是**快到位时的一下一下点按**（原来写死的 `TAP_PERIOD_S`
            # 周期就是这里的默认值 ✓）：按够 `TAP_ON_S` 就松开，下一次按要等间隔到 ✓。
            # ⭐⭐ **对齐的规则搬进 `align_x_decide`**（**一处实现** ✓ 约定 10 ✓）——
            #   用户 2026-10-06："我们应该**整套照搬对齐式爬绳梯的逻辑**，**还要补按方向**"✓
            #   ⇒ 规则抽成模块级函数，**爬绳与走传送点都调它** ✓（原来只在这儿内联着 ✓）。
            #   ⚠ **`retry_ms=0`：爬绳的对齐相不补按** ✓（它 CLIMB 相本来就有自己的"补按 ↑"✓
            #     别叠两层 ✗）—— 用户要的那个新行为**只给传送点** ✓ **这边行为一个字不改** ✓。
            #   记账仍写在 `ClimbJob` 自己那几个字段上 ✓（别的地方也在读它们 ✓ 不搬走 ✗）。
            _kind, _move, _unused_re, _why, _st = align_x_decide(
                now, dx, press_dir=self._press_dir, press_at=self._press_at,
                progress_at=getattr(self, "_alx_progress_at", None),
                best_dx=getattr(self, "_alx_best_dx", None),
                gap_ms=self.align_gap_ms, near_px=self.near_px,
                tol_px=self.tol_px, retry_ms=0)
            self._press_dir = _st["press_dir"]
            self._press_at = _st["press_at"]
            self._alx_progress_at = _st["progress_at"]
            self._alx_best_dx = _st["best_dx"]
            # 点按的"松开那一下" / "等移动延迟"两拍 ⇒ 什么都不按 ✓（note 由函数给 ✓）
            if _kind == "wait":
                self.note = _why
                return self._out(0, False)
            if _kind == "press":
                if abs(dx) <= self.near_px:
                    # 已经走近了 ⇒ 斜跳**重新武装**（这一轮的下一次"离远"还能再试一次 ✓）
                    self._diag_done = False
                self.note = _why
                return self._out(_move, False)
            # `in_tol` ⇒ 落到下面的"站住 `hold_ms` ⇒ 按跳"（note 与后续动作都由那儿管 ✓）
        # ⭐ **本轮还没发过方向键 ⇒ 先朝绳点按一次**（用户 2026-09-28 要求，原话："朝目标绳梯
        #   的 x 方向对齐 x（**至少发 1 次点按方向键**）→ 跳 → 按住 ↑，这三步要循环"）。
        #   ⛔ 原来这一支直接"站住等 `hold_ms` ⇒ 跳"，**一次方向键都不发** ✗ —— 用户要的是
        #   **每一轮都真的朝绳发过一下**才跳 ✓（`_align_pressed` 由 `_out` 一处记账 ✓：
        #   按跳那拍会清掉它 ⇒ 下一轮又要点一次 ✓）。
        #   ⚠ `dx == 0`（正对绳、没有方向可依）⇒ **不硬点**（点哪边都是把人推离绳 ✗）✓。
        #   ⚠ 点完把站住窗口**重新起算**（`_in_tol_since = None`）：那一下可能把人挪出/挪进
        #     容差 ⇒ 让"进容差 ⇒ 站住 `hold_ms` ⇒ 跳"照旧从**发完键之后**算 ✓。
        if not self._align_pressed and abs(dx) > 1e-9:
            _sgn = 1 if dx > 0 else -1
            self._align_pressed = True      # 这一拍就发（`_out` 里也会置 ✓，这儿写明白）
            self._press_dir = _sgn
            self._press_at = now
            self._in_tol_since = None
            self.note = ("对齐 x：本轮还没发过方向键 ⇒ **先朝绳点按一次 %s**"
                         "（差 %.0f px，已在容许 %d 以内 ✓）"
                         % ("→" if _sgn > 0 else "←", dx, self.tol_px))
            return self._out(_sgn, False)
        self._press_dir = 0            # 进误差范围 ⇒ 方向键松开（"站住等" ✓）
        # 已经对齐了（|dx| ≤ tol）⇒ 斜跳**重新武装**：这一轮的下一次"离远"还能再试 ✓
        self._diag_done = False
        # ⚠ 但**"跳没上去、回来重来"那一轮例外**：那几拍方向键要继续按着
        #   （`_retrying`，用户原话"按跳 + 按住 ↑"）—— 中间松手，人到绳边上那一下
        #   就抓不住 ✗（真抓上了会被上面的"已在绳上"接走 ✓）。
        _hold = bool(self._retrying)
        if self._in_tol_since is None:
            self._in_tol_since = now
            self.note = "进误差范围了（差 %.0f px）—— 站住等 %d ms" % (
                dx, self.hold_ms)
            if self.hold_ms > 0:
                return self._out(0, False, hold_dir=_hold)   # 要等就这一拍先站住
            # 不要等（hold=0）⇒ **同一拍就上绳**，别白拖一拍
        if (now - self._in_tol_since) * 1000.0 < self.hold_ms:
            return self._out(0, False, hold_dir=_hold)   # 保持中，别动（动就把对齐弄丢了）
        # ⚠ **按跳的许可条件**（用户 2026-09-27："对齐 x 时一直在不正确的位置按跳"）：
        #   ⚠ 2026-09-27 起**只看 x**：对齐（`tol_px` 容差 + `hold_ms` 站住 ✓）⇒ 直接按跳 ✓
        #     （用户原话："对齐了就按跳开始爬啊，不需要判定别的" ✓）。
        #   不满足 ⇒ **绝不按跳**（跳了也抓不到，只会"在不对的位置一直按跳"✗），
        #   但**保持窗口不重算**（`_in_tol_since` 不动）⇒ 人一落到那块面上就能立刻跳 ✓。
        # ⭐ 用户 2026-09-27 明确（原话）："**对齐了就按跳开始爬啊，不需要判定别的**" ⇒
        #   这里**不再有**"按跳许可"那道门（原来要求 `_at_entry` = 人站在绳底那块面上 ✓）。
        # 为什么拆掉（用户当天连着两次踩到）：
        #   ① 绳的两端常常**不属于同一个集合**（截图那条爬边是「三楼 → 顶层」：绳底那块面
        #      #99 属「三楼」、人脚下 #74 属「顶层」）⇒ 那个判据本身就没意义 ✗；
        #   ② 就算同一个集合，y 也常差十几像素（读数口径 / 站的深浅 ✓）⇒ 门一直拦着，
        #      人**站着不动** ✗（用户原话："这个卡住了"）。
        # ⇒ "对齐 x" 才是能不能按跳的**唯一**前提 ✓；跳了没上去由下面的"点按 / 重来"
        #   那一小段 + 「寻路超时」兜底 ✓（那条链一个字没动 ✓）。
        self.phase = self.CLIMB
        self._retrying = False
        # ⭐ **「对齐完成、即将起跳」这个时刻**（用户 2026-09-28 要求 ✓）：agent 要在这一刻
        #   复核一次"有没有更便宜的怪"（见 `agent._climb_recheck` ✓）⇒ 这里把时刻记下来，
        #   外面靠 `getattr(job, "_armed_at", None)` 观察它（同一个字段 `DropJob` 也有 ✓
        #   —— 那边就是进 `ARMED` 相的那一刻 ✓ 口径一致 ✓）。
        # ⚠⚠ **如实说一句**：本执行器"对齐完成"与"按跳"在**同一拍**内发生
        #   （`_align_step` 返回 None ⇒ 同一次 `update` 里紧接 `_climb_step` 就 `_jump_tried = True`
        #   ✓，见下面 759 那一段）⇒ agent 最早只能在**下一拍**看到这个时刻 ⇒ 那一下跳**已经发出去了**
        #   ✗。⇒ 复核在这里的意义是"**还没真爬上去，及时换目标**"（损失 = 一次点按跳 ✓），
        #   不是"跳之前拦住" ✗ —— 真正能"起跳前拦住"的是 `DropJob`（`ARMED` 相有 `ARM_HOLD_S`
        #   那么长一个窗口 ✓）。
        self._armed_at = now
        self.note = ("对齐好了（人就在绳底那块面上）⇒ 按住跳贴上去，上去之后只按 %s"
                     % ("↑" if self.dir > 0 else "↓"))

        return None


    def _retry_back_to_align(self, how=""):
        """「跳没上去」那一小段的收尾：**回到对齐 x 重新开始**（整个流程重来一遍 ✓）。

        `how` 只说给用户听（"补按过 ↑" / "点按过 ↓" ✓）。⚠ 收尾也必须 `hold_dir=True`
        —— 上爬这一路 ↑ **一直按着**（`_out` 里那条规则 ✓），收尾松了就是"松开 ↑" ✗。
        """
        self._dir_tap_at = None
        self._retry_stage = ""            # 这一小段结束 ⇒ 之后才允许再按跳 ✓
        self._jump_tried = False
        # 回对齐重来 ⇒ 「对齐完成时刻」也清掉：下一轮对齐到点时会重新记上 ✓
        #（不然 agent 会把**上一轮**那个时刻当成新的 ⇒ 少复核／早复核一次 ✗）
        self._armed_at = None
        # ⭐ 回对齐重走一遍 ⇒「这一轮发过方向键没有」也重置（用户 2026-09-28：三步循环里
        #   **对齐那一步每轮都要真发一次** ✓）—— 这次循环的下一次按跳前**又要点一次** ✓。
        self._align_pressed = False
        self._retrying = True
        self._in_tol_since = None         # 保持窗口重新起算 = 两次尝试之间的间隔 ✓
        self._press_dir = 0               # 允许重新按方向键（「对齐绳梯移动延迟」照管 ✓）
        self._press_at = None
        self.phase = self.ALIGN
        self.note = ("还没上绳（还站在 %s 上）⇒ %s，回到对齐 x 重新开始"
                     % (self.src_set, how or ("补按过 ↑" if self.dir > 0 else "点按过 ↓")))
        return self._out(0, False, hold_dir=True)   # 方向键别松（上爬就是 ↑ ✓）

    def _retry_all_up(self, now):
        """**上爬**的「补按住 ↑」那一小段（用户 2026-09-27：上爬**只有**"按住 ↑"和"补按住 ↑" ✓）。

        ⚠ **不是"点按"**：**绝不先松开** ✓ —— 只按 `reassert` 请调用方**再发一次 PRESS** ✓
        （对面把键丢了也是这么补的 ✓，见 `_stalled_by` 那段"y 不动 ⇒ 先补按 ↑"）。
        等够 `TAP_PERIOD_S` 就回对齐重走一遍 ✓（时长沿用现成常数 ✓，不新造 ✓）。
        """
        if self._dir_tap_at is None:
            self._dir_tap_at = now
            self.note = ("还没上绳（还站在 %s 上）⇒ **按住 ↑ 并补按一次**"
                         "（补按 = 再发一次按下，**不松开**）" % self.src_set)
            return self._out(0, False, hold_dir=True, reassert=True)
        _dt = float(now) - self._dir_tap_at
        if _dt < TAP_PERIOD_S:
            self.note = ("还没上绳（还站在 %s 上）⇒ 按住 ↑ 再等 %.0f ms 就回对齐"
                         % (self.src_set, (TAP_PERIOD_S - _dt) * 1000.0))
            return self._out(0, False, hold_dir=True)
        return self._retry_back_to_align("补按过 ↑")

    def holds_player(self, on_rope_pos=None):
        """「**这一趟攀爬正在进行**」—— 人已经在"要跳 / 在爬"这一段里了吗？

        用户 2026-09-27 要求（原话）："**在执行攀爬时，从「按下跳」到「攀爬成功」期间都不应该
        进 attack**"（实测现场：三楼 → 顶层，对齐 x、正起跳那一刻还是进了 attack ✗）。
        agent 那层用它屏蔽 attack（`agent.tick` 的 `_on_rope` 一路 ✓）。

        判据两件**任一**成立（都要求**还没到 `DONE`/`FAILED`** ✓）：
          · **已经按过跳**（`_jumped_once` ✓，`_out` 里凡是 `jump=True` 的拍都会记上 ✓）
            —— 正跳到落地、以及失败重来的那些拍都算"还在攀爬" ✓；
          · **位置就在这根绳的范围里**（⭐ **读位置状态广播的 `on_rope_pos`** ✓ ——
            "**只看位置**编出来的绳号"，与按键许可无关 ✓）—— 人在绳底正对齐、
            **这一拍就要按跳**也算"在攀爬" ✓。
        ⚠ 为什么必须**这一拍就能算**（不能只等"按过跳"）：调序上**攻击判定在任务 tick 之前**
          ⇒ 只要附近有怪，任务就**永远轮不到按跳** ⇒ `_jumped_once` 永远是 False ⇒
          **攻不进去、也爬不上去**（用户现场那个"进了 attack"就是这个 ✗）。
        ⚠ 这里原来自己比坐标（`_at_rope`：x 在**本任务的对齐容差 `tol_px`** 内、y 在绳段 ±
          `tol_px` ✓）—— 2026-09-27 用户要求**收编** ⇒ 那套**已删** ✗：几何只在
          `perception/pos_state.py` 算一次（它用的是**感知那把尺**：x 半宽
          `mapdata.LADDER_DX`(**24**) + y 上下 `LADDER_PAD`(**12**) ✓）。两把尺的关系：
          `LADDER_DX(24) ≥ tol_px(10)` ✓（宽的不许比窄的更紧 ✓）⇒ 换过来只会"更粘一点" ✓，
          不会误清 ✓。
        ⚠ 广播给不出绳号（这一拍没读数 / 没地形）⇒ 传进来是 `None` ⇒ 这一件**不成立** ✓
          = **判不出来就不硬认** ✓（"自己松的键才留记忆"那条在 `update` 里 ✓）。
        """
        if self.phase in (self.DONE, self.FAILED):
            return False
        _in_span = bool(on_rope_pos is not None
                        and str(on_rope_pos) == str(self.ladder_id or ""))
        return bool(self._jumped_once or _in_span)

    def holding_up(self):
        """是否正处在「到顶后再按住 ↑ 那一下」的阶段（收工前的延时按住 ✓）。

        用户 2026-09-28（诉求 2）：攀爬到顶判到达后，`_arrived_at` 被置上、`phase` 还没到
        `DONE` 的那几拍 = "再按住 ↑ `base_hold_ms` 再松"阶段 ✓。agent 的「这趟目的地人已经
        站进去了 ⇒ 提前收工」检查要**避开**这个阶段 —— 不然人刚迈上平台（`ladder_id` 空 +
        `here_sets` 变目的地）就被那条提前收工，`base_hold_ms` 那一下"再按住 ↑"被截断 ✗
        （用户观察到的"位置状态切为目的地后立马停了"就是它 ✓）。
        """
        return bool(self._arrived_at is not None
                    and self.phase not in (self.DONE, self.FAILED))

    def _arrive_dir(self):
        """**到顶"再按住一会儿"那几拍，水平方向按哪边**（`+1` 右 / `-1` 左 / `0` 什么都不按 ✓）。

        口径（用户 2026-10-02 ✓ 原话："到顶时**如果存在锁定目标**，就按住**向着该目标**的方向键
        （注意后续 chase 的方向键处理）"）：
          · **有锁定目标** ⇒ **朝它**（读注入的 `_target_dir_fn()` ✓ —— 和"跳下绳子"那次
            **同一处注入** ✓ 一处实现 ✓）；没有注入 / 回调抛异常 ⇒ 当"没有目标" ✓（**绝不
            因为拿不到目标就报错或停住** ✗，同 `DropJob._detach_dir` 那条纪律 ✓）；
          · **没有目标 / 目标正好同列** ⇒ `0` = **老行为**（只按住 ↑ ✓ 兼容底线 ✓）。
        ⚠ `0` 里包含"同列"：**别瞎挑一边**（挑错了就是朝反方向迈出平台边 ✗ —— 同
          `agent._target_dir` 的口径 ✓）。
        ⚠ 与**后续 chase** 的方向口径**同一条**（都是"画面 x 的左右" ✓ 见 `_arrive_step` 那段 ✓）
          ⇒ 交接那一拍**不翻向** ✓（这正是用户提醒的"注意后续 chase 的方向键处理" ✓）。
        """
        fn = getattr(self, "_target_dir_fn", None)
        if not callable(fn):
            return 0
        try:
            d = int(fn() or 0)
        except Exception:                     # noqa: BLE001 —— 注入坏了 ⇒ 当"没目标" ✓
            return 0
        return 0 if d == 0 else (1 if d > 0 else -1)

    def walking_to_ladder(self):
        """⭐ 「**离绳还远、正朝绳走**」= **起跳距离外**、还没起跳那一段（用户 2026-10-02 ✓）。

        给 `agent._climb_recheck_walk` **每拍**复核用（用户原话："处于**起跳距离外**向绳梯移动时，
        每拍查询：如果在当前 foothold 集合有**代价更低的目标**就结束任务"）——
        这一段时间人还在地上走、"只是朝那边挪"，**换个主意几乎不花代价** ✓。

        成立四条（**任一不成立就 False** ✓）：
          · ① 还在 `ALIGN` 相（`_climb_step` 之后就不算了 ✓）；
          · ② **没按过跳**（`_jumped_once` 为假 ✓）—— 按过跳就说明这一轮已经进了攀爬流程，
               后面那一段该交给 `agent._climb_recheck` 的节点①/② ✓（**别在这儿拦** ✗）；
          · ③ **人不在绳上**（`_in_rope_span_now` 为假 ✓）—— 在绳上按左右 = 松手掉下来 ✗；
          · ④ 斜跳**没在进行**（`_diag_arming` / `_diag_flying` 都空 ✓ —— 已经起手跳了就别拦 ✓）。
        再加上"`|dx| > 起跳距离`"：`dx` 取**本拍算出来的那个**（`_last_dx` ✓，见 `_align_step` ✓）。

        ⚠ `起跳距离 = 0`（默认 ⇒ 斜跳整条关着 ✓）⇒ 只要没对上绳就算 ✓（这正是用户要的那段 ✓）。
        ⚠ **不自己算距离** ✗：`|dx| > 起跳距离` 这个分档本来就是 `_align_step` 里那段
          （"一口气按住走过去" vs "斜跳/点按" ✓）—— 这里只读它记账的结果 ✓（约定 10 ✓）。
        """
        if self.phase != self.ALIGN or self._jumped_once:
            return False
        if self._in_rope_span_now or self._diag_arming is not None or self._diag_flying:
            return False
        if self._last_dx is None:
            return False                       # 没有 x 读数 ⇒ 判不了（不猜 ✓）
        return bool(abs(float(self._last_dx)) > self.jump_start_px)

    def _reset_round(self, clear_jump=False):
        """把"**这一轮尝试**"的进度锚点**全清**（重走一遍上绳流程 ⇒ 从零算 ✓ 一处实现 ✓）。

        谁调（**只有这两处** ✓ —— 各写一份迟早漏掉一两个锚点 ✗，而漏掉的表现就是
        "刚回来第一拍就判爬不动 / 带着半截斜跳状态回来"）：
          · **被战斗打断太久**（`_paused` ≥ `PAUSE_MIN_S`，见 `update` ✓）⇒ `clear_jump=False`
            （**老行为一字不变** ✓：那一支原来就不动 `_jumped_once`）；
          · **这一轮压根没挂上** ⇒ 退回重试（用户 2026-10-03 ✓）⇒ `clear_jump=True`
            （必须把"按过跳"也归零，否则重来那一轮会一进来就被当成"已经跳过了" ✗）。
        """
        self._in_tol_since = None
        self._on_ladder_since = None     # 下爬"稳住 hold_ms"那一段也重算 ✓
        self._rope_seen = False          # 「确认过在绳上」那条记忆也清（重走一遍流程 ✓）
        self._off_since = None
        # 对齐阶段的"按过方向键"也重算（同 `retry()` ✓）：不然会被上一轮的
        # 「对齐绳梯移动延迟」挡住第一拍 ✗。
        self._press_dir = 0
        self._press_at = None
        self._jump_tried = False        # 重新走一遍 ⇒ "按过跳了没"也从零算 ✓
        self._armed_at = None           # 同理：「对齐完成」这个哨兵也清掉（对齐要重来 ✓）
        self._retrying = False
        self._dir_tap_at = None         # "点按到一半"也一样，别带着半个状态回来 ✗
        self._retry_stage = ""          # 重来那一小段（等 y 稳定 / 点按）同理从零 ✓
        self._diag_done = False         # 斜跳也重新武装（重走一遍流程 ⇒ 允许再斜跳一次 ✓）
        self._diag_flying = False       # "飞行中"同理清掉（不许带着上一轮的飞行状态回来 ✗）
        self._diag_y0 = None
        self._diag_left = False
        self._diag_at = None            # 起跳时刻也清（脏状态不留 ✓）
        self._diag_arming = None        # 斜跳"起手了"那步同理清（残留会误触发按跳 ✗）
        self._align_pressed = False     # 重走一遍 ⇒ 方向键也算没发过（要先点按一次 ✓）
        if clear_jump:
            self._jumped_once = False   # ⭐ 新一轮 ⇒ 得**重新按跳**（见上面两条分工 ✓）
            self._jump_y = None
            self._rose_since_jump = False

    def _track_rose(self, py):
        """记账：**按跳之后 y 有没有真的往上走过** → `_rose_since_jump`（用户 2026-10-03 ✓）。

        这是"没挂上"与"挂上了但爬不动"之间**唯一**的判据（见 `update` ①'' 那段 ✓）：
        真贴上绳会立刻往上走 ✓；没贴上（跳空了 / 斜跳没落上去）则 y 一直不动 ⇒ 后者
        才该退回重试 ✓。
        尺子用现成的 `STALL_GAIN_PX`（= 8px，"y 动没动"那一把 ✓ 不新造数 ✓）；
        方向按 `dir` 分（上爬 y **变小**、下爬 y **变大** ✓）。只记账、**不发键** ✓。
        """
        if py is None or not self._jumped_once:
            return
        try:
            y = float(py)
        except (TypeError, ValueError):
            return
        if self._jump_y is None:
            self._jump_y = y            # 按跳那一拍的 y 当基准 ✓
            return
        d = (self._jump_y - y) if self.dir > 0 else (y - self._jump_y)
        if d >= STALL_GAIN_PX:
            self._rose_since_jump = True

    def retry(self):
        """**失败后重新激活**（用户 2026-09-26：「失败触发后重新激活就行」）。

        回到第一步"重新对齐"，把超时 / 保持 / 偏离 / 离绳那几个计时全清掉，`attempt` +1
        （「**斜跳**」也在这一轮重新武装 ✓）。
        ⚠ **没有"最多试几次"**（2026-09-27 用户要求删掉）：失败就一直原地重来，
        整天由 agent 的「**寻路超时时间**」收口 ⇒ 最终由它 `cancel` + 整条路线停 ✗。
        """
        self.attempt += 1
        self.phase = self.ALIGN
        self._t0 = None
        self._in_tol_since = None
        self._off_since = None
        # 到达后的"再按住一会儿"同理要清：留着上一次的时刻会让新一轮一上来就收工 ✗。
        self._arrived_at = None
        self._arrived_hold = 0
        self._arrived_why = ""
        # 下爬那三个锚点同样要清：留着上一次的"已在绳上"时刻，重来这一轮会在**还没上绳**
        # 的时候就以为"稳够了" ⇒ 当场把 ↓ 松掉 ✗。
        self._on_ladder_since = None
        self._rope_seen = False             # 「确认过在绳上」同理：新的一轮从"没确认过"开始 ✓
        self._press_dir_done = False
        self._jump_off_at = None
        self._y_ref = None
        self._y_still_since = None
        # 对齐阶段"按过方向键"的记账也清：重来这一轮，「对齐绳梯移动延迟」要**重新起算**
        #（留着上一轮的时刻，重来第一拍就会被自己的间隔挡住 ✗）。
        self._press_dir = 0
        self._press_at = None
        # "这一轮按过跳了没"与"是不是回来重来那一轮"同理要清（新的一轮从 ① 开始 ✓）；
        # "点按到一半"（`_dir_tap_at`）也一样：留着会让新的一轮一上来就"松/按"接着上次跑 ✗
        self._jump_tried = False
        self._armed_at = None             # 同 `_jump_tried`：新的一轮从 ① 对齐开始 ⇒ 哨兵清掉 ✓
        # 「中途跳下」同理**重新武装**（⚠ 失败重来之后应该**允许再跳一次** ✓ —— 不重置的话
        #   第一轮触发过就永久失效，重来一轮反而"爬到底" ✗ 与配置不符）
        self._mid_jumped = False
        self._mid_arm_since = None
        self._mid_jump_at = None
        self._mid_dir_done = False
        self._mid_land_at = None
        # 「斜跳」同理**重新武装**（新的一轮可以再斜跳一次 ✓）——
        # ⚠ 它不能进 `_ANCHORS`（那个是**时刻**表，`_resume` 会给它们加 dt ✗）。
        self._diag_done = False
        self._diag_flying = False           # 新的一轮从"还没跳出去"开始 ✓
        self._diag_y0 = None
        self._diag_left = False
        self._diag_arming = None            # 斜跳"起手了"那一步也清（残留会误触发按跳 ✗）
        self._align_pressed = False         # 新一轮 ⇒ 方向键算没发过（一定要先点按一次 ✓）
        self._retrying = False
        self._dir_tap_at = None
        self._retry_stage = ""          # "等 y 稳定 / 点按"那一小段同理从零开始 ✓
        # ⚠ 这里**不再写分母**（原来 `第 N/M 次尝试`，M = `max_attempts`）—— 用户
        #   2026-09-27：那条"最多试几次"已经去掉，一切由「寻路超时时间」收口 ✓。
        self.note = "第 %d 次尝试：重新对齐 %s" % (self.attempt, self.ladder_id)
        return self._out(0, False)

    def cancel(self, why="取消"):
        """外部叫停（比如切了目标/手动关自动）—— 状态收干净，别再按键。"""
        # ⚠ **运行时字段一起收干净**（用户 2026-10-02 #8 ✓ 见 `_cancel_common` ✓）——
        #   原来这里只置相位，带着脏锚被复用就是隐患 ✗。
        self._cancel_common(why)
        return self._out(0, False)

    # ---- 内部 ----

    def _dir_to_center(self, px):
        """朝**目标集合 x 中点**该按哪个方向键 → +1（→）/ -1（←）/ 0（不用按）。

        "向量运算就够"（用户 2026-09-26）：`dst_x - px` 的**水平分量符号** —— 横版只有
        左右两个方向键，符号就是全部信息 ✓。
        `dst_x` 算不出来（那条边的目标集合没圈 foothold）或没有 x 读数 ⇒ 0：**直着跳**，
        并把"没有方向可依"如实写进 note（不猜方向 ✗）。
        """
        if self.dst_x is None or px is None:
            return 0
        dx = self.dst_x - float(px)
        if dx > 0:
            return 1
        if dx < 0:
            return -1
        return 0

    def _jump_down_beat(self, now, px):
        """「跳下绳梯」一拍：**先单独按住方向键** → 点按跳 → 松跳、方向继续按着。

        用户 2026-09-26 定的顺序：按住方向键 → 按跳 → 松开跳 → 松开方向（他把最后那一
        步改成"方向按到落地为止"，见 `_landed`）；跳是**点按** `TAP_ON_S`（≈ 一帧，
        复用现成的数，不新造）。

        ⚠ **第一步为什么单独占一拍**（和「下跳」那条「先按住 ↓ 再按跳」同一个理由）：
        同一次 tick 里把"方向"和"跳"一起发，游戏里未必算"按住方向再跳"（`KeyState` 一次
        下发多个键不保证顺序）⇒ 分两步发。这里**只隔一拍** —— 不引入新的时长常数
        （纪律见 README「不许拍脑袋补数」）。
        """
        sign = self._dir_to_center(px)
        _toward = ("→" if sign > 0 else ("←" if sign < 0 else "（没有方向可依）"))
        _why = ("" if self.dst_x is None
                else "（朝目标集合中心 x=%.0f）" % self.dst_x)
        if not self._press_dir_done:
            self._press_dir_done = True
            self.note = "跳下绳梯：按住 %s%s" % (_toward, _why)
            return self._out(sign, False, vert=0)
        if self._jump_off_at is None:
            self._jump_off_at = now
            self.note = "跳下绳梯：按跳（点按 %.0f ms），%s 一直按着" % (
                TAP_ON_S * 1000.0, _toward)
            return self._out(sign, True, vert=0)
        if (now - self._jump_off_at) < TAP_ON_S:
            return self._out(sign, True, vert=0)
        self.note = ("跳下来了：按住 %s 等落地（到目标面 / 落回集合 / y 稳定，先到算哪个）"
                     % _toward)
        return self._out(sign, False, vert=0)

    # ---- 「中途跳下」（2026-09-28 用户要求 ✓）----

    def _mid_sign(self, px):
        """「中途跳下」该按哪一边：`center` ⇒ 朝目标集合中心（`_dir_to_center` ✓）；
        `left`/`right` ⇒ 只看那一侧 ✓（⚠ 口径照 `WalkJob.walk_dir`：left=-1 / right=+1 ✓）。"""
        if self.mid_dir == "left":
            return -1
        if self.mid_dir == "right":
            return 1
        return self._dir_to_center(px)          # center（px 未知 ⇒ 0 = 直着跳 ✓）

    def _mid_why(self):
        return {"center": "（朝目标集合中心）", "left": "（仅向左）",
                "right": "（仅向右）"}.get(self.mid_dir, "")

    def _mid_jump_beat(self, now, px):
        """⭐ 「**中途跳下**」一拍（用户 2026-09-28 ✓）——照 `_jump_down_beat` 的形状，
        但⚠ **全程不松 ↑** ✗。

        用户原话："攀爬过程中当 y >= 该高度时按配置的方向**执行跳下绳梯**（**不松开 ↑**，
        直到**返回成功或失败后**再经过「**移动操作尝试间隔**」松开）"✓。

        时序（同 `_jump_down_beat` 的**两步法**，别把方向和跳挤到同一拍 ✗ —— 那边有踩坑说明）：
          ① 先**单独一拍**按住方向（`_mid_sign` ✓）；
          ② 再**点按**跳；
          ③ 松开跳，方向与 ↑ 继续按着，等落地（`_mid_landed` ✓）。

        ⚠⚠ **`hold_dir=True` 贯穿全场**（= `vert` 保持 `↑` ✓）——**别照抄下爬那边的 `vert=0`**
          ✗（那是主动松 ↓ ✓）：用户明确要"不松开 ↑" ✓，而且 `_out` 里"上爬算出 0 就强制按住 ↑"
          那条规则也靠 `hold_dir` 才稳 ✓。
        ⚠ 落地之后**还要再按住 ↑ `mid_hold_s`** 才真松（在 `_arrive_step` 的 `MID_JUMP` 分支里 ✓）
          —— 用户那句"**返回成功或失败后再经过「移动操作尝试间隔」松开**"就是它 ✓。
        """
        sign = self._mid_sign(px)
        _toward = {0: "（不按方向）", 1: "→", -1: "←"}[sign]
        if not self._mid_dir_done:                      # ① 先单独按住方向一拍
            self._mid_dir_done = True
            self.note = "中途跳下：按住 %s%s" % (_toward, self._mid_why())
            return self._out(sign, False, hold_dir=True)
        if self._mid_jump_at is None:                   # ② 点按跳
            self._mid_jump_at = now
            self.note = "中途跳下：按跳（点按 %.0f ms），↑ 一直按着" % (TAP_ON_S * 1000.0)
            return self._out(sign, True, hold_dir=True)
        if (now - self._mid_jump_at) < TAP_ON_S:
            return self._out(sign, True, hold_dir=True)
        self.note = "跳下来了：按住 %s 等落地（↑ 不松）" % _toward
        return self._out(sign, False, hold_dir=True)    # ③ 松跳；方向与 ↑ 继续按着

    def _mid_landed(self, now, py, on_rope):
        """「中途跳下」的落地判据 → 一句人话 / `None`（还没落）✓。

        ⚠ 用户明确："跳到**绳旁的平台**（**可能另一块**）" ⇒ **不能**用 `_landed` ✗
          （那个要求"够到目标面 / 脚下是目标集合" —— 中途跳下的落点**本来就不该**是沿途那些集合 ✓）。
          ⇒ 这里只要两件：**离开绳**（`on_rope` 为假 ✓）+ **y 稳定**（`_y_settled` ✓，口径一处 ✓）。
        ⚠ `on_rope` 是**带按键许可**那份（`ladder_id`）—— 这一相正按着 ↑，跳下来之后它变
          `None` ✓，那正是"离开绳了" ✓（不会自己把自己判成还在绳上 ✗）。
        """
        if on_rope:
            self._y_still_since = None       # 还在绳上 ⇒ 稳定计时作废，别跨界用 ✓
            return None
        if py is None:
            return None                      # 没读数 ⇒ 不判（观测问题，不是"没落" ✗）
        if self._y_settled(now, py):
            return ("中途跳下完成：已离开绳、y 稳定在 %.0f（落点不要求是沿途集合 ✓）"
                    % float(py))
        return None

    def _y_settled(self, now, py, still_s=None):
        """「等待 y 稳定」：y 已经不再变了 ⇒ 算落地（用户定的最后一步）。

        **复用现成的两个数**（`STALL_GAIN_PX` / 时长，不新造 —— 它们本来就是
        "y 动没动"那套判据用的：小地图读数在抖，动过 2px 才算"在动"；连续静一会儿算稳）。
        没有 y 读数（定位掉帧）时**不判** —— 那是观测问题，不是"落稳了"。

        `still_s`：要安静多久算稳（秒）。**None = `self.stall_s`**（设置里那格
        「卡住判定时长(s)」✓）。⭐ 2026-10-01 起「跳失败后等 y 稳定」那条**已删**（改由
        位置状态权威广播的 `here_sets` 判"还站在起跳平台"✓）⇒ 本方法只剩**下爬落地 /
        中途跳下**在用 ✓。
        """
        if py is None:
            return False
        _still = (self.stall_s if still_s is None
                  else max(0.0, float(still_s)))
        pyv = float(py)
        if self._y_ref is None or abs(pyv - self._y_ref) >= STALL_GAIN_PX:
            self._y_ref = pyv
            self._y_still_since = now
            return False
        return (self._y_still_since is not None
                and (now - self._y_still_since) >= _still)

    def _landed(self, now, py, here_sets, at_bottom=None, ground_y=None,
                on_rope=False):
        """下爬「跳下绳梯」之后**落地了没有** → 一句话（没落地给空串）。

        三个判据、**哪个先到算哪个**（用户 2026-09-26 明确要求）：
          ① 够到目标平台的面（`_arrived` 那条几何判据，即 `dst_y`）；
          ② 脚下已经是**目标集合** —— 它在别的任务里**不作到达依据**（读数会抖，会把
             差 38px 的地方报成"已在集合"），但在这儿是**落地兜底**：人已经踩在那块
             平台上了，就不用再等 y 稳定那 3 秒 ✓；
          ③ `y 稳定`（`_y_settled`）—— 落地平台没圈成集合 / `dst_y` 算不出来时的最后兜底。
        """
        why = self._arrived(py, here_sets, at_bottom=at_bottom, ground_y=ground_y)
        if why:
            return why
        # ⛔ **人还在绳上时，这条集合兜底不算数**（用户 2026-09-27：位置状态还没说到，
        #   执行器又擅自结束了 ✗）—— 爬绳时"脚下那条 foothold"可能是**别层**的
        #   （绳段横跨好几层 ✗，同一批数据就是"绳底那块面属三楼、人脚下属顶层"）
        #   ⇒ 只有**人已经离开绳**（`on_rope=False` ✓ = 广播说没贴着绳）时它才作数 ✓。
        if (not on_rope) and here_sets and self.dst_set and self.dst_set in set(here_sets):
            self._saw_dst_set = True
            return "到达：脚下已经是「%s」" % self.dst_set
        if self._y_settled(now, py):
            return "到达：y 稳定在 %.0f（%.1fs 没动过 ⇒ 落地了）" % (
                self._y_ref, self.stall_s)
        return ""

    def _target_y(self):
        """**这一方向的到达目标 y**（给提示话用；判据本身在 `_arrived` 里）。

        向上爬 = 绳梯**上端**的 y（用户 2026-09-26 改的口径）；
        向下爬 = 落地面（目标平台的面；算不出来时退回绳梯**下端**）。
        ⚠ 独立成一个方法，就是为了**别在多处各写一遍"目标是谁"** —— 改一次口径要动三处
        （判据、提示、日志）时，漏一处就会出现"提示说 -208、判据按 -205"这种自相矛盾 ✗。
        """
        if self.dir > 0:
            return self.y_top
        return self.dst_y if self.dst_y is not None else self.y_bot


    def _arrived(self, py, here_sets, at_top=None, at_bottom=None, ground_y=None):
        """到了没有 —— ⭐ **上下爬都看位置状态广播**（用户 2026-09-27 定的新架构）。

        **上爬**（`dir > 0`）：**不再自己比坐标** ✗ —— 读**位置状态机**广播的 `at_top`
        （`perception/pos_state.py` ✓，判据原文：y ≤ 绳梯上端 + 「坐标对齐误差范围」**且**
        y 在「移动操作尝试间隔」内**不再变小** ✓）。用户原话：
        "上爬到顶的判据修改为：**不再主动计算，而是等『位置状态』广播**" ✓。
        **下爬**（`dir < 0`）：同样**不再自己比坐标** ✗（2026-09-27 用户要求"下爬的到达
        （落地面 / 绳下端）也搬进广播" ✓）：
          · `at_bottom` —— 广播「**到没到某根绳的下端**」（y ≥ 绳下端 − 「坐标对齐误差范围」
            且 y 在「移动操作尝试间隔」内**不再变大** ✓，与到顶对称 ✓）；
          · `ground_y` —— 广播「**脚下那块面的 y**」（玩家 x 处的面 y ✓）⇒ 与**本任务的目标
            平台面 `dst_y`** 一比就是"落到目标平台的面了" ✓（那个比较必须在任务里做：
            机器不知道这一步要去哪 ✓；**几何读数本身只在机器里算** ✗）。
        ⚠ 三个广播量的**三态**（**这个区别很关键，别合并** ✗）：
          · `None`  ⇒ **判不出来**（这一拍没有世界坐标 / 没地形 ⇒ 机器给不出 ✓）⇒ 就是不认 ✓
            （**没有几何兜底了** ✗ —— 2026-09-27 用户明确"删掉过渡兜底" ✓）；
          · `""`    ⇒ 机器说"**判过了、没到**" ⇒ 就是没到（**别再自己算** ✗）；
          · `"L2"`  ⇒ 机器说"已到 L2 那一端" ⇒ 到达 ✓（且**必须是本任务要爬的那根** ✓）。

        ⚠ **口径变过两次，都把来龙去脉留在这儿**（免得下一个人再绕回去）：
          · 最早：`y_top ± ARRIVE_PAD(14)` —— 用户指出"从没提过这个数" ⇒ 删掉；
          · 中间：**够到目标平台的面**（`dst_y`）—— 理由是"绳顶常比平台面低一截，
            拿绳顶当目标等于到绳顶了还要求再往上"；
          · **现在（2026-09-26 用户改）**：向上爬**改回绳子上端的 y**（原话："之前是按
            目标 foothold 集合的 y，改为绳子上端的 y"）⇒ `dst_y` **不再参与上爬判定**，
            它只留给**下爬**当"落地面"（见 `_landed`）。
          剩下"迈上平台"那一步交给"到达后再按住 ↑ 误差时间"那一下 ✓（见 `update` 里
          `_arrived_at` 那段）。
        ⚠ **不加容差、不加 pad**（见文件头 ARRIVE_PAD 那条与 README「不许拍脑袋补数」）：
        绳上端是多少就是多少（差 1px 都不算）。
        ⚠ **这里不看 `here_sets` 了**（原来先查集合 ✗）：集合是"脚踩在哪条 foothold"，
        而定位读数会抖动 / 有几拍的滞留值，`-170`（离目标还差 5px）那种位置也可能被
        报成"已在目标集合" ⇒ 提前收工（用户实测：**在 -170 就松开了 ↑** ✗）。
        集合判据没丢，它挪到了它该在的地方：**失败之后 "已经到了就别再重试"**
        （见 `agent._climb_tick`）—— 那才是用户当初要它的意思（"结束重新激活的任务"）；
        下爬那边它还有一份用处：**落地兜底**（见 `_landed`）。
        """
        if here_sets is not None and self.dst_set and self.dst_set in set(here_sets):
            # 只记一笔给日志/提示用，**不作为到达依据**（到达只认下面的几何判据）
            self._saw_dst_set = True
        if py is None:
            return ""
        if self.dir > 0:
            # ---- ① 向上爬：⭐ **读位置状态广播**（用户 2026-09-27："不再主动计算" ✓）----
            if at_top and str(at_top) == self.ladder_id:
                return "到达：位置状态广播「已到 %s 上端」" % self.ladder_id
            return ""                          # 没到 / 判不出来 ⇒ 都不算（**别再自己比坐标** ✗）
        # ---- ② 向下爬：⭐ **同样读广播**（用户 2026-09-27："下爬的到达（落地面 / 绳下端）
        #      也搬进广播" ✓）—— 这里**一个字都不比坐标** ✗ ----
        # ②a 落到**本任务的目标平台的面**：广播给的"脚下那块面的 y" 与目标面比 ✓
        if self.dst_y is not None and ground_y is not None:
            if float(ground_y) >= float(self.dst_y):
                return ("到达：位置状态广播「脚下那块面 y=%.0f 已到目标平台的面（%.0f）」"
                        % (float(ground_y), float(self.dst_y)))
            return ""
        # ②b 目标面算不出来（`dst_y is None`）⇒ 认广播的"**已到绳下端**" ✓（与上爬对称 ✓）
        if at_bottom and str(at_bottom) == self.ladder_id:
            return "到达：位置状态广播「已到 %s 下端」" % self.ladder_id
        return ""

    def _fail(self, why):
        self.phase = self.FAILED
        self.note = why
        return self._out(0, False)

    def _out(self, move, jump, hold_dir=False, reassert=False, vert=None, replan=False):
        """`hold_dir`：**不按跳也要按住方向键** —— 下跳要求"先按住 ↓，再按跳"。

        （爬绳用不到它：那边只有"按住跳 + ↑/↓"一步。）

        `reassert`：请调用方**再 PRESS 一次**当前这几个键 —— 键可能在对面被丢掉了而
        本机不知道（`KeyState` 只在键集变化时才发键 ✗），见"y 不动 ⇒ 先补按"那段 ✓。

        `vert`：这一拍要不要发 ↑/↓。**None = 老规则**（按跳或 `hold_dir` 时发 `self.dir`，
        否则不发）。下爬的「跳下绳梯」必须传 `vert=0`：那几拍要**按住水平方向键 + 按跳、
        但绝不能再按 ↓**（↓ 是"还挂在绳上"的动作，用户 2026-09-26："松开 ↓"）。
        """
        d = (self.dir if (jump or hold_dir) else 0) if vert is None else int(vert)
        # ⭐⭐ **上爬的 ↑ 从「按跳那一刻」才开始按**（用户 2026-10-02 ✓ 原话："应该是**按跳之后
        #   再按住 ↑**，我观察到 ↑ **从任务下达就一直被按住了**"）：`_jumped_once` 是"按过跳
        #   就一直记着、`retry()` / 被打断重走都**不清**"（见下 ✓）⇒ 这一条同时满足两件事：
        #     · **跳之前**（对齐走位 / 点按 / 站住等保持窗口）⇒ 走"老规则"算出的 `dir=0`
        #       **保持 0** ✓ —— 原来一律改成按住 `self.dir` ⇒ 任务一挂上 ↑ 就按住 ✗
        #       （角色走到绳旁边会**提前把绳抓住 / 被路过的绳粘住**，正是要修的那件事 ✓）；
        #     · **按跳那一拍起** ⇒ 一路按住（斜跳飞行相 / CLIMB 爬升 / 到顶后再按住 /
        #       失败重跳与"回对齐"那几拍 ✓）—— 用户 2026-09-27 那条"向上攀爬**只有**「按住 ↑」
        #       和「补按住 ↑」，不能存在「松开 ↑」和「点按 ↑」"**原样成立** ✓（它管的就是
        #       跳之后那一段 ✓）；"补按住"由 `reassert=True` 负责（**只再发一次 PRESS** ✓、
        #       绝不先松 ✓）。
        # ⭐ **唯一的例外 = 人已经挂在绳上**（用户 2026-10-02 方案 B ✓）：位置状态广播说
        #   "**这一拍位置就在本任务那根绳的绳段里**"（`_in_rope_span_now` ✓，**纯几何、与
        #   按键许可无关** ✓）⇒ 照旧按住 ↑ ⇒ 接着爬。为什么必须留着它：没有 ↑ 就没有
        #   "按键许可" ⇒ 广播给不出 `ladder_id` ⇒ 执行器**认不出"已上绳"** ⇒ 会走 ALIGN 去做
        #   横向对齐 ⇒ **在绳上按左右在游戏里就是松手掉下来** ✗（任务刚下达时人已经挂在
        #   绳上那一类 —— 上一段留下的 / 手工站上去的）。
        # ⚠ 另外两个"能把 ↑ 压成 0"的口子（与上面那条例外正交，只有它们）：
        #   ① **明确传 `vert=0`** 的（下爬的「跳下绳梯」那几拍 ✓ —— 那是"主动松手离开绳"✓，
        #      语义与上爬无关 ✓）；
        #   ② **收工那几处**（`DONE` / `FAILED` / `cancel` ⇒ 该松手了 ✓）。
        #   ⚠ 所以这段**不改 `move`**：横向对齐的"点按节奏"（「对齐绳梯移动延迟」✓）照旧 ✓。
        if (d == 0 and vert is None and self.dir > 0
                and (self._jumped_once or self._in_rope_span_now)
                and self.phase not in (self.DONE, self.FAILED)):
            d = self.dir
        # ⚠ 记下**这一拍我们请他按的竖直键**（`dir` ✓）—— 下一拍判"感知说不在绳上"是不是
        #   **我们自己松的键**造成的（`_rope_seen` 那条记忆要用 ✓，见 `update` 里那段 ✓）。
        self._last_vert = int(d)
        # ⚠ 「**按过跳了**」—— 只要真按过一次就**一直记着**（`retry()` / 被打断重走都**不清** ✓）：
        #   "从按下跳到攀爬成功期间都不许进 attack"（用户 2026-09-27 ✓）要它 ✓，
        #   见 `holds_player` ✓。
        if jump:
            self._jumped_once = True
        # ⭐ 按跳这一下起，"强制重走对齐"那一轮就结束了 ✓（见 `_force_align` ✓）
        self._force_align = False
        # ⭐ 「**这一轮发过水平方向键没有**」—— 记账**只有这一处** ✓（用户 2026-09-28 要求：
        #   "朝目标绳梯的 x 方向对齐 x（**至少发 1 次点按方向键**）→ 跳 → 按住 ↑，这三步要
        #   循环"）：· **按了跳** ⇒ 这一轮结束（下一轮必须重新发方向键 ✓）；
        #             · **发了水平方向** ⇒ 这一轮满足 ✓（`_align_step` 那道闸就靠它 ✓）。
        #   ⚠ 判的是**水平** `move`（竖直那个 `d` 不算 —— ↑ 全程按着，不然永远算"发过" ✗）。
        if jump:
            self._align_pressed = False
        elif move:
            self._align_pressed = True
        return self._result(move, jump, d, reassert=reassert, replan=replan)


#: 「人**站在那块面上**吗」的判据：`|玩家 y − 脚下那块面的 y|` 超过它就说明**人悬着**
#: （挂在绳上 / 在空中 ✗），而不是站在面上 ✓ —— 下跳的「被绳吸住」判据用它 ✓。
#: 取值来历：**与 `foothold_below` 的 `tol` 默认值 40 同口径** ✓（那个 40 的语义就是
#: "黄点画的是玩家中心、而地面在脚底"的那点偏差 + 几像素读数抖动 ✓，见
#: `core/mapdata.Terrain.find_below` 的说明 ✓）⇒ 不新造数 ✓。
FOOT_GAP_PX = 40.0


class DropJob(_PausableJob):
    """一次「下跳」（`drop`）：**就近平齐到某个可下跳 foothold 的中心** → 站住 →
    按住 ↓ + **点按跳** → Y 开始变化就**松开 ↓** → 落到目标算成功。

    用户 2026-09-27 定的流程（照抄，别自己发明顺序）：

      ① 找**最近**的允许下跳的 foothold，走到它的**中心**；
      ② 判定**位于该 foothold**（x 落在它的范围里）持续 ≥「坐标对齐误差时间」⇒ 松开行走键；
      ③ **按住 ↓ + 点按跳**；
      ④ **Y 向下变化超过「坐标对齐误差范围」⇒ 松开 ↓**（松手，等落地 ✓）——
        用户 2026-09-27 明确："**当 Y 变化超过「坐标对齐误差范围」才能松开 ↓**"：
        **向上抖不算**（那是读数噪声，不是"开始下落"✗），而且**没有 y 读数就不按跳**
        （基准都拿不到 ⇒ 判不出下落 ⇒ 只能一路按到超时 ✗）；
      ⑤ 落到目标 foothold ⇒ 成功。

    ⭐⭐ **③ 之后三条出口（用户 2026-10-06 的流程图定稿 ✓，照抄别自己发明）**：

      · **位置状态说上绳了** ⇒ 松开 ↓、按方向 + 跳 **脱离**（→ `DETACH` 相 ✓，
        方向 = 有锁定目标朝目标、否则任意 ✓）；
      · **正常下落**（Y 真的往下走了 ✓）⇒ 离开"触发"这一环，转 `LANDING`/到达判定 ✓；
      · **「移动操作尝试间隔」内没反应**（既没下落、也没上绳）⇒ **回入口**：
        重新判"**当前这块 foothold 还能不能下跳**"（= 回到 `ALIGN` 相 ✓，
        `_to_entry` 那一步；判下来还是这块 ⇒ 重新"按住 ↓ + 跳" ✓，
        不是这块了 ⇒ 就近挑一块走过去 ✓）。

    ⛔ **"按键补按（重发 PRESS）"那套已删**（2026-10-06 ✓ 用户原话："**下跳 drop 执行器的
      按键补按逻辑移除**，改为当在「移动操作尝试间隔」内没反应就从最开始的判断走"✓）：
      `_reassert_at` / `_reassert_n` / `_hold_reassert()` / `out["reassert"]` 全部不在下跳里 ✗
      —— **爬绳那边的「补按 ↑」照旧保留**（那是另一条口径 ✓）。
    ⚠ 回入口那一拍**一个键都不按**（`_out(0, False)` ⇒ ↓ 真的松开一拍 ✓）：`KeyState` 只在
      **键集变化**时才发键 ⇒ 不松这一下、下一轮那个"按住 ↓"对面**根本收不到新的按下** ✗
      （人**不趴** ⇒ 后面每一下跳都只是**原地跳** ✓）—— 这正是原来 `_hold_reassert` 要解决的
      同一个坑，现在改用"**真的松一下 → 真的一次新按下**"来解（**不靠重发** ✓）。
    ⚠ 「点按跳」而不是"按住跳"：用户 2026-09-26 定的动作是**两次**按下（先 ↓ 再跳），
      一直按住跳会被游戏当成"还挂在上面"✗（`_jump_down_beat` 那套也是点按 ✓）。

    可下跳的 foothold 来自边上的 `footholds` 那一格（不填 = 起点集合的全部，见
    `zones.drop_footholds`）—— 一条边上常常有好几个能下去的点，**就近挑一个** ✓。

    接口和 `ClimbJob` **故意做成一样**（`update/retry/cancel/attempt/phase`）：
    agent 那边就只有一条执行路径（`_climb_tick`），不用为每种通行方式各写一遍
    —— 也保证两种的失败保护/重来行为一致。
    """

    ALIGN = "align"          # ① 就近平齐到某个可下跳 foothold（要**站在它上面**够久）
    ARMED = "armed"          # ② **先按住 ↓**（这一刻还不跳）
    DROP = "drop"            # ③ ↓ 按住不放 + **点按跳**（每次尝试一个"尝试间隔"的窗口）
    LANDING = "landing"      # ④ **松开 ↓**，等落到目标
    #: ⓪' **被绳吸住 ⇒ 脱离**（用户 2026-09-27）：下跳途中吸附到"通往下层的绳"上 ⇒
    #: **按住一个水平方向（= 松手）+ 连按跳**，把 ↓ **松开**（按 ↓ = 还挂在绳上 ✗）。
    #: 见 `_detach_step`。
    DETACH = "detach"
    DONE = "done"
    FAILED = "failed"

    def __init__(self, src_set, dst_set, spots, tol_px=ALIGN_TOL_PX, hold_ms=250,
                 y_tol_px=ALIGN_TOL_PX, retry_ms=3000, stall_s=STALL_S,
                 timeout_s=DEFAULT_TIMEOUT_S, dst_ys=None):
        self.src_set = str(src_set or "")
        self.dst_set = str(dst_set or "")
        #: ⭐ **目标平台的"面 y"**（世界坐标 y 的列表；空 = 不知道 ✓）—— 给"到了没有"的
        #: **几何兜底**用：**脚下这块面就是目标平台的面** ✓（读位置状态广播的 `ground_y` 判 ✓）。
        #: 用户 2026-09-28 明确要求换掉旧判据（原话："把『y 掉 40px』换成『脚下这块面 ==
        #: 目标面』"）：旧的那条**太松** —— 人只要往下掉 40px 就报"到了"，哪怕还在半空 /
        #: 落到了别处 ✗（实测：追击反复下发同一条下跳任务，就是它误报"到了" ⇒ 人其实没
        #: 下去 ⇒ 下一拍又判"怪不在我这块平台" ⇒ 又下 ✗）。
        #: ⚠ **目标集合里每条非墙 foothold 的面 y 都收进来**：运行时落点取决于从哪个下跳点
        #:   跳，这里**不预先绑定**那一条 ✓（命中任意一条即算 ✓）。
        self.dst_ys = [float(v) for v in (dst_ys or [])]
        #: [(中心 x, 左, 右, **面 y**, foothold id)] —— 可下跳的那几条（就近挑）。
        #: 形状**统一成 5 元组**（与 `WalkJob` 的"落点五元组"同款 ✓）：面 y 是
        #: `f.y_at(中心 x)`（与 `_set_spans` 同一口径 ✓），给 ALIGN 的"**人是不是站在
        #: 这一块上**"用 —— 用户 2026-10-02 现场（下跳 ALIGN **只看 x** ⇒ 人掉到别的层
        #: 也被判成"已经在下跳点上" ⇒ 从错误的层按 ↓+跳 ⇒ 一路穿到最底层 ✗）。
        #: ⚠ 传**老的 4 元组**（手写用例 / 老调用方）⇒ 面 y 记 `None` ⇒ 那一条**不参与
        #:   y 校验**（"判不出来不拦"，与 `ground_y is None` 那条**同一个口径** ✓
        #:   老行为一字不变 ✓）；形状既不是 4 也不是 5 ⇒ 报错（别猜 ✓）。
        self.spots = []
        for _s in (spots or []):
            _s = tuple(_s)
            if len(_s) == 4:
                _c, _a, _b, _i = _s
                self.spots.append((float(_c), float(_a), float(_b), None, str(_i)))
            elif len(_s) == 5:
                _c, _a, _b, _y, _i = _s
                self.spots.append((float(_c), float(_a), float(_b),
                                   None if _y is None else float(_y), str(_i)))
            else:
                raise ValueError(
                    "可下跳点的形状该是 (中心x, 左, 右, 面y, id)（或老的 4 元组）：%r" % (_s,))
        if not self.spots:
            raise ValueError("下跳任务没有可下跳的 foothold")
        #: 站在 foothold 范围两侧允许的**读数余量**（世界像素，见 `update` 的 ALIGN ✓）
        self.tol_px = max(1.0, float(tol_px))
        #: 「坐标对齐误差时间」（ms）：判定**位于该 foothold** 要持续这么久才松手 ✓
        self.hold_ms = max(0, int(hold_ms))
        #: 「坐标对齐误差范围」（世界像素）：Y 变化超过它才算**真的开始下落** ⇒ 松开 ↓ ✓
        self.y_tol_px = max(1.0, float(y_tol_px))
        #: ⭐ **下落过程中「补按跳」**的锚（用户 2026-09-28 口径 ✓ 原话："下落过程中也按照
        #:   『移动操作尝试间隔』补按 **按住 ↓ + 跳**"）—— 见 `_falling_jump` ✓。
        #: ⛔ **曾经还有一个 `_reassert_at`（"按下 ↓"的重发观察窗 ✓）—— 2026-10-06 删掉** ✗：
        #:   用户改口径了（原话："**按键补按逻辑移除**，改为当在「移动操作尝试间隔」内没反应
        #:   就**从最开始的判断走**（当前 foothold 是否可下跳）"✓）⇒ "没反应"的处置**不再是
        #:   重发一次 PRESS**，而是**回入口重判**（`_to_entry` ✓）。见 `update` 的 DROP 相 ✓。
        self._jump_reassert_at = None
        #: **已经在往下掉了**（Y 变化越过误差范围 ✓）：从这一刻起**不再点按跳**，
        #: 但 **↓ 一直按着** —— 直到 `_arrived` 说"位置状态到目的地了"才松 ✓
        #: （用户 2026-09-27："在 drop 时，除非位置状态到了目的地，否则 ↓ 是不能松开的" ✓）。
        self._falling = False
        #: 「移动操作尝试间隔」（ms）：③ 之后这么久 Y 还没动 ⇒ 补发一个"松开 ↓"重来 ✓
        #: 由 `agent.start_climb()` 从设置灌进来（0 = 不重试 ⇒ 老行为 ✓）。
        #: ⚠ 2026-09-27 起它还兼一个角色：**松 ↓ 之后隔多久再开始下一轮**（见 `_next_round_at` ✓）。
        self.retry_ms = max(0, int(retry_ms))
        #: 「**卡住判定时长(秒)**」（设置 → 判定参数 ✓）：一轮"按住 ↓ + **连按跳**"最长按多久 ——
        #: 到点 Y 还没动就算卡住 ⇒ 松开 ↓ 起身，隔「移动操作尝试间隔」再连按 ✓。
        #: 为什么用它：用户 2026-09-27 原话"按住↓，下一拍再按跳，**可以用「卡住判定时长」连按**" ✓。
        #: 下限 0.5：再小就等于"刚按一下就判卡住"✗（同 `ClimbJob.stall_s` 的钳法 ✓）。
        self.stall_s = max(0.5, float(stall_s))
        self.timeout_s = float(timeout_s)
        #: 第几次尝试 —— ⚠ **不是上限**（没有"最多试几次"了，见文件头那段 ✓）
        self.attempt = 1
        self.dir = -1                       # 下跳永远是"往下"（按住 ↓）
        #: 上一拍 `_out` 请他按的**竖直键**（-1 = ↓ / 0 = 没按 ✓）—— 给 ladder_id 许可的
        #: 「执行器通知」用（同 `ClimbJob._last_vert` ✓，用户 2026-09-28 诉求 1：drop 按 ↓ 时
        #: 也要给位置状态机发通知，让它能进"能上绳梯"的入口，直到 drop 收工再关上 ✓）。
        self._last_vert = 0
        self.phase = self.ALIGN
        self.note = "就近平齐到一个可下跳 foothold"
        self._t0 = None
        #: 被战斗打断时，`_PausableJob.interrupted/_resume` 要把**这些计时锚点**整体往后挪
        #: （= "任务的时间停了一会儿" ✓）—— 挨打那几秒不许算进"站住/按住↓/卡住"里 ✗。
        #: ⚠ 2026-09-27 之前 DropJob **没继承** `_PausableJob`（所以它从不跳过打架时长 ✗，
        #:   还吃不到 `_result` 那套统一回值 ✗ —— 本轮补齐 ✓）。`_y0/_y_base` 是 **y 值**不是
        #:   时刻 ⇒ 不在里面 ✓。
        #: ⛔ **`_reassert_n`（补按「按住 ↓」发了几次）也一起删了**（2026-10-06 ✓ 补按没了，
        #:   这个计数就没有来源了 ✗；日志里 `drop_reassert` 那条 `sample` 同步删 ✓）。
        self._ANCHORS = ("_in_tol_since", "_armed_at", "_attempt_at", "_jump_at",
                         "_landing_at", "_next_round_at",
                         "_jump_reassert_at", "_detach_tap_at")
        self._in_tol_since = None
        self._armed_at = None
        self._y0 = None
        self._pick = None
        #: 本次尝试（一次"按住 ↓ + 点按跳"）的起点时刻 / 起点 y / 跳按下的时刻 / 第几次
        self._attempt_at = None
        self._y_base = None
        self._jump_at = None
        self._tap_n = 1
        #: 松开 ↓ 的那一刻（"松了却没落下去"的退路计时用：超 `retry_ms` ⇒ 回入口 ✓）
        self._landing_at = None
        #: **下一轮**最早什么时候开始（= 松 ↓ 那一刻 + 「移动操作尝试间隔」✓）—— 不是 None 就说明
        #: 现在正"松着 ↓ 等间隔"（那几拍**一个键都不按**，让人真的站直 ✓）。
        self._next_round_at = None
        #: 「**被绳吸住、正在脱离**」那一下跳是什么时候按下去的（到 `TAP_PERIOD_S` 再按一下 ✓
        #: —— 和 ③ 那份点按节奏同一份，不新造时长 ✓）。见 `_detach_step`。
        self._detach_tap_at = None
        #: 「点按跳」的**上升沿**计数 + 上一拍跳的开关（`tap_count()` 用 ✓）。
        #: 用户 2026-09-28 报"**趴在那不动了也不按跳**"：光看 `drop_phase=3` 分不清"跳没发"
        #: 还是"发了游戏不响应" ✗ ⇒ `behavior.log` 里的 `drop_taps` 一眼就能判 ✓。
        self._taps = 0
        self._jump_on = False

    def update(self, now, px, py=None, ladder_id=None, here_sets=None, at_top=None,
               at_bottom=None, ground_y=None, on_rope_pos=None,
               climb_failed=None, climb_stalled=None):
        self._resume(now)        # 被战斗打断过 ⇒ 把挨打那几秒从计时锚点上扣掉（同其余三个执行器 ✓）
        if self._t0 is None:
            self._t0 = now
        if self.phase in (self.DONE, self.FAILED):
            return self._out(0, False)
        if now - self._t0 > self.timeout_s:
            return self._fail("超时 %.0fs：没能从「%s」下跳到「%s」"
                              % (self.timeout_s, self.src_set, self.dst_set))

        # ---- ⓪ **吸附在绳上 ⇒ 先脱离**（用户 2026-09-27 要求）----
        # 原话："现在在下跳执行器中可能会吸附到通往下层的绳子上，这种情况应该执行
        #   「**任意方向按住 + 连按跳**」脱离（**世界状态应该是能知道的**）"。
        # ⭐ 判据 = **两份"只看位置"的客观事实**（都是世界状态 ✓、**都与按键许可无关** ✓）：
        #   · `on_rope_pos` —— 位置就落在某根绳的**绳段**里（`pos_state._ladder_at` 那套
        #     几何 ✓，感知层同一次算出来的 ✓）；
        #   · `ground_y is None` —— **脚下没有面**（悬空 ✓）。
        #   两件同时成立 = 人**挂在绳上**（"被绳吸住"的字面事实 ✓）。
        # ⛔ **2026-09-28 修：原来只判「带按键许可的 `ladder_id`」⇒ 两头都错** ✗
        #   （用户现场："**下跳 drop 结果实际爬上了向下爬的绳子**"✗）：
        #     · **误报**：`ARMED` / `DROP` 相**自己按 ↓** ⇒ `climbing_vertical()` 为真 ⇒ 许可开
        #       ⇒ 人只要站在下跳点（那根"通往下层的绳"就在旁边；`LADDER_DX`=**24** /
        #       `LADDER_PAD`=**12** 一把**宽**尺盖得住 ✓）⇒ `ladder_id` **当场非空** ⇒ 进
        #       `DETACH`（现场：`align → armed → detach` 只隔 **28 ms** ✗）；而 `DETACH` 相
        #       **不按 ↓**（`vert=0` ✗）⇒ 下一拍许可关 ⇒ "又没在绳上" ⇒ 回 `ALIGN` ⟲；
        #     · **漏报**：人**真挂在绳上**时，`ALIGN` / `DETACH` 相**不按竖直键** ⇒ 许可关
        #       ⇒ `ladder_id` 恒 `None` ⇒ **判不出来** ✗ ⇒ 人一直挂在绳上（`behavior.log`：
        #       `climb_y=-90.7` 恒定 + `climb_on_ladder=0` 近 **9 秒** ✗）⇒ `ALIGN` 走不到
        #       下跳点中心 ⇒ `align→armed` 再也不发生（那 9 秒里**一条 `route_phase` 都没有**
        #       ✗）⇒ 10 秒「寻路超时」⇒ 重下 ⇒ 再超时 ⟲。
        #   ⚠ 这两份事实**本来就有**（`update` 的参数里都带着 ✓）—— 不新造感知 ✗、
        #     也不加"人到底在不在绳上"的第三份判断 ✓。
        # ⚠ 放在**所有相之前**：被吸住时"往下穿"这件事根本做不了（人挂在绳上 ✗），
        #   不论当时在哪一相（走去下跳点 / 站住 / 按压跳）都得先松手 ✓。
        # ⚠ **"脚下那块面离我有多远"才是"悬空"的判据**（2026-09-28 修 ✓）：
        #   ⛔ 原来写的是 `ground_y is None` ✗ —— 实测**不成立**：人挂在绳上时，感知照样给得出
        #     `ground_y`（`foothold_below` 只对"头顶上方"卡 40px、**下方不卡** ⇒ 绳下方那层
        #     的面会被认领 ✗）。实测（图 `106010105` 绳 L2）：人挂在绳正中 `y=-291`、离下面
        #     那块面还有 **109px**，`ground_y` 仍是 `-182` ✗ ⇒ `_hanging` 永远 False ⇒
        #     从不脱离（用户现场："drop 执行器没有从位置状态机拿到上绳通知而去执行跳开绳子的
        #     逻辑"✗）。
        #   ⇒ 改成"**位置在绳段里** 且 **脚下那块面离我超过容差**" ✓：人真站在平台上时
        #     `|py - ground_y|` 只有几像素（就是"黄点画中心 vs 地面在脚底"那点偏差 ✓
        #     `FOOT_GAP_PX` 与 `foothold_below` 的 40 同口径 ✓）。
        _foot_gap = (None if ground_y is None or py is None
                     else abs(float(py) - float(ground_y)))
        # ⭐⭐ **"被绳吸住"要分两档判**（用户 2026-10-06 ✓ 现场原话："**drop 触发 → 人上绳梯 →
        #   位置状态显示到了 fh：6 → 然后就不动了**"✓ —— 我按他的现象回查日志，完全对上 ✓）：
        #   ① 老那档（2026-09-28 那条 ✓ 不动它）：**在绳段里 且 脚下那块面离我超过
        #      `FOOT_GAP_PX`** ✓ = 人悬在绳中 ✓；
        #   ② ⭐ **新那档**：**在绳段里 且 相位已经是"要往下跳"那几相**（ARMED / DROP /
        #      LANDING ✓）—— 这几相的意图就是**往下跳**，人却在绳段里 ⇒ 说明**游戏把按住的 ↓
        #      当成"顺绳往下爬"、把他吸在绳上了** ✗。
        #      ⚠ 为什么非加这一档（实测证据 ✓）：人挂在**绳梯下部**时，脚下那块面就在 40px 内
        #      ⇒ ① 那档**判不出来** ✗ ⇒ 从不脱离 ⇒ 现场 `drop_phase=5`（DETACH）**一次都没进过** ✓
        #      （与日志完全吻合 ✓）。
        #   ⚠ **只在这几相**放宽 ✗：ALIGN 相（走去下跳点）路过绳段不算被吸住 ✓ 不许乱脱 ✗。
        #   ⚠⛔ **"在绳段里 + 那几相"这一档试过、又撤了**（2026-10-06 ✓ 如实记）：`on_rope_pos`
        #     和 `ladder_id` **两种信号都分不出**"人挂在绳梯上"与"人站在绳底平台上" ✗ ——
        #     **下跳点本来就常紧贴绳底**（`on_rope_pos` 真 ✓），而 ARMED/DROP 那几拍我们**正按着 ↓**
        #     ⇒ 许可开着 ⇒ 站在绳底平台上时 `ladder_id` **也报得出绳号** ✗ ⇒ 加这一档会把
        #     "规规矩矩站在下跳点上、准备往下跳"判成"被绳吸住" ⇒ 自己按的 ↓ 把自己判死 ✗
        #     （既有用例 `t_drop_detach_ladder` 当场按住 ✓ 它钉的就是这条 ✓）。
        #   ⇒ **要治"人被吸在绳梯上"，先得有一个能分辨这两者的信号** ✗（见开发日志里那条待办 ✓）。
        _hanging = bool(on_rope_pos) and (_foot_gap is None or _foot_gap > FOOT_GAP_PX)
        if _hanging:
            if self.phase != self.DETACH:
                self.phase = self.DETACH
                self._detach_tap_at = None
                self.note = "在下跳中被绳吸住了（%s）⇒ 按住方向 + 连按跳 脱离" % on_rope_pos
            return self._detach_step(now, px)
        if self.phase == self.DETACH:
            # 已经不在绳上了（出了绳段 **或** 脚下有面 = 落回平台 ✓）⇒ 回入口重走一遍下跳
            #（重新就近对齐 → 站住 → 按压跳 ✓）
            self.phase = self.ALIGN
            self._in_tol_since = None
            self._pick = None          # 重挑下跳点：人可能已经被绳子带到别处了 ✓
            self._armed_at = None
            self._attempt_at = None
            self._y_base = None
            self._jump_at = None
            self._landing_at = None
            self._next_round_at = None
            self._detach_tap_at = None
            self.note = "已经从绳上松开 ⇒ 回入口重走下跳"

        if self.phase == self.ALIGN:
            # ⭐⭐ **ALIGN 改成"当前是否可下跳"的判 + 走**（用户 2026-09-28 定稿 ✓ 原话：
            #   "问题出在 ALIGN 上"；流程图：入口先判「**当前是否可下跳**」⇒ **是** 就直接
            #   ARMED/DROP/LANDING；**否** 就"**就近挑一块『可下跳 foothold』并前往**" ⇒
            #   **进入范围** ⇒ **回入口再判** ✓）。
            #   ⭐ 2026-10-06：③''' 那条"「移动操作尝试间隔」内没反应"**就是回到这里** ✓
            #   （`_to_entry()` 把相位打回 `ALIGN` ✓）—— 所以本相**必须**保持"先判再决定"
            #   这个形状，别改成"直接从 ARMED 续上" ✗（那样就绕过了入口判断 ✓）。
            #
            # ⚠⚠ **改之前的病**（现场 2026-09-28 18:17 那次「三楼 → 二楼」超时 ✗）：
            #   老判据是"人的 x 落进**某一小块** foothold 的 `[left-tol, right+tol]`，
            #   **并站够 `hold_ms`**"（= 设置里「坐标对齐误差时间」，那个项目设的 **1000ms** ✗）。
            #   而**位置读数本身会摆**：实测那 10 秒里人的世界 x 在
            #   `1165 → 1159 → 1173 → 1185 → 1159 → 1134 → 1173` 之间跳，`drop_dx` 随之在
            #   **4.7 ⇄ 30.1** 来回摆 ✓ ⇒ 只要有一拍跳出那 ±10px 余量，`_in_tol_since` 就
            #   **清零重来** ⇒ 10 秒总闸内**永远凑不满一个连续的 1 秒** ⇒ 连"按住 ↓"都没进过
            #   ⇒ 超时 ✗（`drop_phase` 全程 `1.0` ✓、`drop_taps` 一直是 0 ✓）。
            #   ⚠ 而"走位"恰恰是**执行器自己**发方向键造成的：朝中心走一步就冲出范围、再反向
            #     ⇒ **振荡**（`drop_dx` 4.7 ⇄ 30.1 就是它 ✓）。
            #
            # ⇒ 现在只做两件事，**不站、不等** ✓：
            #   · **可下跳** = 人的 x 落在**任意一块**「可下跳 foothold」的范围里（`tol_px`
            #     那点余量保留 —— 它是给读数抖动的 ✓）⇒ **立刻**进 ARMED ✓
            #     （这一步就是流程图里"进入范围 ⇒ 回入口再判"的落点 ✓）；
            #   · 都不在 ⇒ **就近挑一块、朝它走**（图里"否"那条 ✓）—— 到了下一拍自然命中 ✓。
            # ⚠ **不再做"下方是不是目标集合"的二审**：那几块 foothold 是**你在编辑器里圈给
            #   这条下跳边**的（`zones.drop_footholds` ✓）⇒ "从这儿跳能到目标"是**你配的意图**
            #   ✓，执行器**不必也不该**再验一遍（同"编辑器编的是意图、连不连通归执行器自洽"✓）。
            # ---- ⓪ **别在错的层上做下跳**（用户 2026-10-02 现场 ✓，判据**只问广播** ✓）----
            #   2026-10-02「龙族打猎场卡 40 秒」的根因：这一段原来**只看 x** ⇒ 人从「上层」
            #   滑落平台、掉到「二楼」时，那个 x 正好落进**上层**某块可下跳 foothold 的
            #   ±`tol_px` 里 ⇒ 被判成"已经在下跳点上" ⇒ 从**错误的层**按 ↓+跳（在二楼穿平台）
            #   ⇒ 一路掉到最底层，而任务还在"等落到中层"⇒ 卡死 ✗✗。
            #   日志铁证：`align→armed` 那一拍 `pos sets=二楼 x=456.7 y=855.5`，而 spots 全是
            #   上层的面（y≈305）✓。
            #   ⇒ 两条闸（都只用广播，**执行器不自己算几何** ✓ 同 SKILL 77）：
            #     · **已经到目标层**（`here_sets` 命中 `dst_set`）⇒ **收工** ✓ —— 他可能是
            #       掉下来正好落到目标，那是"到"、不是"失败"（用现成的 `_arrived` ✓ 一处口径）；
            #     · **既不在起跳平台、也不在目标层**（`here_sets` 非空却两边都不沾）⇒
            #       **这一段做不了 ⇒ 如实失败**，让上层**按现在的位置重算**路线 ✓
            #       （现场就是掉到二楼 ⇒ 失败 ⇒ 追击重规划 ⇒ 从二楼出发 ✓）。
            #   ⚠ 脚下**没圈进任何集合**（`here_sets` 空 = 判不出来 / 半空中）⇒ **不拦** ✓
            #     （继续走流程，"站在对的面上/超时"那两条会兜住 ✓）。
            #   ⚠ `src_set` 空（手工建的任务 / 老调用方）⇒ 换层那条**不判** ✓。
            _why = self._arrived(py, here_sets, ground_y=ground_y)
            if _why:
                self.phase = self.DONE
                self.note = _why
                return self._out(0, False)
            _here = set(str(v) for v in (here_sets or ()) if str(v))
            if (_here and self.src_set and self.dst_set
                    and self.src_set not in _here and self.dst_set not in _here):
                return self._fail(
                    "人已经不在起跳的「%s」上了（脚下是「%s」）⇒ 这段下跳做不了，"
                    "交给上层按现在的位置重算"
                    % (self.src_set, "／".join(sorted(_here))))
            # ---- ① "就在下跳点上" = x 命中 **且** 脚下那块面就是它的面（y 判据 ✓）----
            #   ⚠ y 那把尺**只问广播的 `ground_y`**（= 位置状态给的"脚下那块面的 y"✓，
            #     与"是不是悬着"那条（`_hanging`）**同一把尺** `FOOT_GAP_PX` ✓ 不新造 ✓）。
            #   `ground_y` / 该点的面 y 任一拍拿不到（None）⇒ **退回只看 x** ✓
            #   —— "判不出来不拦"，老用例 / 老调用方行为一字不变 ✓。
            _gy = None if ground_y is None else float(ground_y)
            _hit = None
            for _c, _a, _b, _fy, _fid in self.spots:
                if _a - self.tol_px <= float(px) <= _b + self.tol_px:
                    if _gy is None or _fy is None or abs(_gy - float(_fy)) <= FOOT_GAP_PX:
                        _hit = (_c, _a, _b, _fy, _fid)
                        break
            if _hit is not None:
                self._pick = _hit
                self._in_tol_since = None    # 这套"站住计时"已经不用了（字段留给 DETACH 清 ✓）
                self.note = ("已经在可下跳的 fh %s 上（x 落在 %.0f~%.0f%s）⇒ 直接按住 ↓"
                             % (_hit[-1], _hit[1], _hit[2],
                                "" if (_gy is None or _hit[3] is None)
                                else "、脚下那块面差 %.0f px" % abs(_gy - float(_hit[3]))))
                self.phase = self.ARMED
            else:
                # ⚠ 这里**不做"重挑点"**（用户 2026-10-02 ② 的另一半，实测是空操作 ✓ 说明如下）：
                #   `spots` **全部来自起跳集合**（`zones.drop_footholds` 给的就是 `from` 集合
                #   那几块面 ✓）⇒ 人已经不在这一层时，重挑出来的还是同层的点 ⇒ 朝它走也走不到
                #   ✗。而"人到底在哪一层"这件事**只有广播说得清** ⇒ 交给上面 ⓪ 的两条闸：
                #   到了目标层 ⇒ 收工 ✓ / 在别的已知集合 ⇒ 失败让上层重算 ✓；**判不出来**
                #   （集合空）⇒ 就是下面这条：不许 ARMED，照旧走流程等它落定 ✓。
                if self._pick is None:
                    self._pick = min(self.spots, key=lambda s: abs(s[0] - float(px)))
                    self.note = ("就近平齐到 fh %s 的中心（x=%.0f，该 fh 范围 %.0f~%.0f）"
                                 % (self._pick[-1], self._pick[0], self._pick[1], self._pick[2]))
                _pc, _pl, _pr = self._pick[0], self._pick[1], self._pick[2]
                self.note = "对齐中：朝中心 x=%.0f 走（差 %.0f px）" % (_pc, _pc - float(px))
                return self._out(1 if _pc > float(px) else -1, False)
            self._armed_at = now
            self._y0 = float(py) if py is not None else None
            self.note = "松开行走键，按住 ↓（%d ms）再点按跳" % int(ARM_HOLD_S * 1000)

        if self.phase == self.ARMED:
            # **先按住 ↓ 一小会儿**（用户说的顺序：按住↓ → 点按跳）。
            # 这一刻只发方向键、不发跳（agent 那边靠 `hold_dir` 知道该怎么办）。
            #
            # ⚠ 出发 y 要**一直更新到起跳前**：世界坐标不是每拍都有（认不出黄点时是 None），
            # 只在"进 ARMED 那一拍"记一次的话，那拍没坐标 ⇒ 出发 y 是 None ⇒ 落地兜底
            # 判据（y 掉下去一段）**永远不会成立**（踩过）。
            if py is not None:
                self._y0 = float(py)
            if (now - self._armed_at) >= ARM_HOLD_S:
                self.phase = self.DROP
                self._attempt_at = None      # 下一拍开始第一次尝试 ✓
                self.note = "按住 ↓ + 点按跳"
            else:
                # ⚠ 这里就是流程图那个"**通知位置状态：允许判为在绳梯上**"的落点 ✓ ——
                #   按住 ↓（`hold_dir=True` ⇒ `_last_vert = -1` ✓）⇒ `agent.climbing_vertical()`
                #   为真 ⇒ 位置状态机**才**允许判"在绳上" ✓（2026-09-28 诉求 1 ✓）。
                #   **不另加一个"通知"开关** ✗：那会有第二份真相（同 `_last_vert` 打架 ✓）。
                return self._out(0, False, hold_dir=True)

        # ---- ④⑤ 到了没有（下跳中 / 已松开 ↓ 等落地，都要判）----
        if self.phase in (self.DROP, self.LANDING):
            # ⭐ 几何兜底要**位置状态广播的 `ground_y`**（"脚下那块面的 y" ✓）——
            #   用户 2026-09-28 定的新判据见 `_arrived` ✓。
            why = self._arrived(py, here_sets, ground_y=ground_y,
                                on_rope_pos=on_rope_pos)
            if why:
                self.phase = self.DONE
                self.note = why
                return self._out(0, False)      # 落地即松手（↓ 也不再按）✓

        if self.phase == self.DROP:
            # ③ 一轮 = **按住 ↓ + 连按跳**（用户 2026-09-27 现场口径，照抄）：
            #   原话："**按住↓，下一拍再按跳，可以用「卡住判定时长」连按**" +
            #   "按住↓就会趴，**可能还没趴你就按跳所以无效**" ⇒ 下跳的触发条件是
            #   **趴着时按跳** ✓ ⇒ 原来"只点按**一次**跳"太死 ✗：那一下要是还没趴下去，
            #   就白按了（现场就是"趴着不跳、起身才跳"✗）。
            #   所以：↓ **全程按着**（松了就起身 ⇒ 根本不触发 ✗），跳**按点按周期一遍遍连按** ✓
            #   （每下 `TAP_ON_S`、间隔 `TAP_PERIOD_S` —— 和「跳下绳梯」同一份节奏，不新造 ✓）。
            #   一轮窗口 = 「**卡住判定时长**」(`stall_s` ✓ 用户指定用它连按)：窗口内一直连按；
            #   到点 Y 还没动 ⇒ **松开 ↓ 一拍**（起身）⇒ 隔「移动操作尝试间隔」(`retry_ms`)
            #   再按住 ↓ 连按（下一轮 ✓；`0` = **不重试** ⇒ 一直按住连按，交给「寻路超时」✓）。
            if self._attempt_at is None:                  # 刚进 DROP（第一拍 ✓）
                self._falling = False                     # "已经在掉"从零开始 ✓
                self._jump_reassert_at = None             # （下行补按跳那笔账也重新记 ✓）
                # ⛔ **2026-09-28 删掉**：这里原来有"松着 ↓ 等「移动操作尝试间隔」到点再按住"
                #    那几拍（`_next_round_at` ✓）—— 用户口径是"**进了 DROP 就一路按住 ↓，
                #    只有判定 drop 上绳梯了才松开 ↓，其他只有补按**"✓ ⇒ **不许有空等的几拍** ✗
                #    （那几拍人是站直的 ⇒ 又要重新趴 ⇒ 永远趴不下去 ✓）。
                self._next_round_at = None
                self._attempt_at = now
                self._y_base = None                       # 基准 = "跳之前"的 y（下面那一小段拿 ✓）
                self._jump_at = None
                self.note = ("按住 ↓ + 连按跳（第 %d 轮，%.1f s 内看 Y 动不动）"
                             % (self._tap_n, self.stall_s))
            # ⚠ **没有 y 基准就先别按跳**（用户 2026-09-27："当 Y 变化超过「坐标对齐误差范围」
            #   **才能**松开 ↓"）：基准拿不到 ⇒ "有没有开始下落"根本判不出来 ⇒ 按了跳也只能
            #   一路按到超时 ✗。所以先按住 ↓ 等一拍 y 读数（通常下一拍就有 ✓）再按跳 ✓ ——
            #   这样"按下跳"和"记下基准"一定在同一拍上（判据才站得住 ✓）。
            if self._y_base is None:
                if py is None:
                    self.note = "按住 ↓：等一个 y 读数（没读数就没法判「开始下落了没有」）"
                    return self._out(0, False, hold_dir=True)
                self._y_base = float(py)
                self.note = ("按住 ↓ + 连按跳（第 %d 轮，%.1f s 内看 Y 动不动）"
                             % (self._tap_n, self.stall_s))
            # ④ **Y 真的开始下落 ⇒ 停掉「点按跳」，但 ↓ 一直按着** ✓
            #    用户 2026-09-27 明确（原话）："在 drop 时，**除非位置状态到了目的地，否则 ↓ 是
            #    不能松开的**" ✓ —— 它盖掉了当天早上那条"Y 一变就松 ↓"✗：
            #    早松会让人在半空 / 刚落地那几拍被迫起身（又去抓绳 / 站住不动 ✗）。
            #    ⇒ 到位只由 `_arrived(py, here_sets)` 判（上面那段 ✓，判到就 DONE 并松手 ✓）。
            if self._y_changed(py):
                if not self._falling:
                    self._falling = True
                    self.note = ("Y 从 %.0f 掉到 %.0f（向下 ≥%.0f px）⇒ **↓ 继续按着**，"
                                 "等落到「%s」再松"
                                 % (self._y_base, float(py), self.y_tol_px, self.dst_set))
                # ⭐⭐ **掉的过程中：↓ 一路按着 + 按「移动操作尝试间隔」补按跳**
                #   （用户 2026-09-28 口径 ✓ 原话："下落过程中也按照『移动操作尝试间隔』补按
                #    **按住 ↓ + 跳**"）。
                #   ⚠ 原来是"只按住 ↓、**不再点按跳**"✗ —— 病根是"跳是用来触发的、已经在掉了"
                #     这条**假设**：可下落途中**也可能又卡住**（被绳吸住 / 卡在半空的绳上 ——
                #     `_detach_step` 那条"被绳吸住"正是靠按跳脱离 ✓）⇒ 只按 ↓ 会**一路干等到
                #     超时** ✗（现场就是"按住 ↓ 不按跳、也不补按，直到超时"✗）。
                #   ⚠ 节奏照抄「移动操作尝试间隔」（`retry_ms`，与 `_hold_reassert` 同一份 ✓，
                #     不新造时长 ✓）⇒ `retry_ms <= 0` 仍**不补**（尊重设置 ✓）。
                #   ⚠ ↓ 仍由 `hold_dir=True` 保证**全程按着**（用户 2026-09-27："除非位置状态
                #     到了目的地，否则 ↓ 不能松开" ✓）—— 这里只决定"跳"按不按 ✓。
                jp = self._falling_jump(now)
                return self._out(0, jp, hold_dir=True)
            # ⭐⭐ **③'''  「移动操作尝试间隔」内没反应 ⇒ 回入口**（用户 2026-10-06 流程图 ✓
            #   原话："**当在「移动操作尝试间隔」内没反应就从最开始的判断走**
            #   （**当前 foothold 是否可下跳**）"）。
            #   · "**没反应**" = 既**没有正常下落**（`_y_changed` 上面那条没命中 ✓）、
            #     也**没被位置状态判成上绳**（那条更早、在 `update` 最前面 ✓）⇒ 走到这儿
            #     就是"按住 ↓ + 跳了半天，游戏**一点动静都没有**" ✓。
            #   · 处置 = `_to_entry()`（相位打回 `ALIGN` = 流程图顶部那个判断 ✓）⇒
            #     下一拍重新判"**当前这块 foothold 还能不能下跳**"：**是** ⇒ 重新"按住 ↓ + 跳"
            #     ✓；**否** ⇒ 就近挑一块、走过去 ✓。
            #   ⚠ **窗口从"进 DROP 那一刻"算**（`_attempt_at` ✓，进相时打的点 ✓），
            #     与流程图里"按住↓+跳 ⇒ 间隔到点还没反应"那一支对齐 ✓。
            #   ⚠ `retry_ms <= 0` ⇒ **不回头**（用户在设置里把重试关掉 = 老行为：一路按住 ↓
            #     连按，交给「寻路超时」✓ —— 尊重设置 ✓）。
            if (self.retry_ms > 0 and self._attempt_at is not None
                    and (float(now) - float(self._attempt_at)) * 1000.0 >= self.retry_ms):
                # ⚠ `_to_entry` 返回的那一拍**一个键都不按**（= 真的松开一拍 ✓）——
                #   那正是"下一轮按住 ↓ 是**新的一次按下**"的保证 ✓（见它的 docstring ✓）。
                return self._to_entry(
                    "按住 ↓ + 跳了 %.0f ms（「移动操作尝试间隔」）既**没下落**、也没**上绳** "
                    "⇒ 回入口，重新判「当前这块 foothold 还能不能下跳」"
                    % float(self.retry_ms))
            # ⛔⛔ **2026-09-28 整段删掉**：这里原来有"**一轮窗口（「卡住判定时长」`stall_s`）
            #   到点、Y 还没动 ⇒ 松开 ↓ 起身** ⇒ 隔「移动操作尝试间隔」再来一轮"✗。
            #   用户口径（2026-09-28 ✓ 原话）："**到点 Y 还没动，也不应该松开 ↓ 起身，只要进了
            #   DROP 就一路按住 ↓**"／"**流程中，只有判定 drop 上绳梯了才松开 ↓，其他只有补按**"✓
            #   ⇒ 那段"松手起身"**正是永远趴不下去的根因** ✗：每一轮只活 ~0.35 s 就站直一次
            #     （日志里 `drop_round` 3→9 ✓），游戏里**根本来不及趴** ⇒ 每一下跳都是**站着
            #     原地跳** ✓ —— 现场（用户 2026-09-28 报"又卡了、在原地跳"）就是这个 ✓。
            #   ⇒ 现在这一相**只剩三件事**：
            #     ① `_falling`（真开始落了 ⇒ 继续补按跳 ✓，见上面那段）；
            #     ② ⭐ **③'''「移动操作尝试间隔」内没反应 ⇒ 回入口**（2026-10-06 加 ✓）；
            #     ③ ③''「连按跳」（按 `TAP_ON_S` / `TAP_PERIOD_S` 的节奏 ✓）。
            #   ⚠ **↓ 松手的时机只剩三处**（与用户流程图**一致** ✓）：
            #     · 落地 `DONE` / `FAILED`（`_arrive_step` / `_fail` ✓ 该松了 ✓）；
            #     · `_detach_step`（**判定上绳梯** ⇒ 脱离，那几拍传 `vert=0` **主动松 ↓** ✓）——
            #       这正是用户说的"**只有判定 drop 上绳梯了才松开 ↓**"✓；
            #     · ⭐ **回入口那一拍**（③''' ✓ 一个键都不按 —— **必须**松一下，理由见下 ✓）。
            #   ⚠ `stall_s` / `_tap_n` 从这一刻起**不再参与决策**（留着字段只为日志/用例 ✗
            #     不删定义：设置里那两项还在，别让别的调用方当场炸 ✗）。
            # ③'' **连按**：到「点按周期」就**再按一下**（`_jump_at` = 这一下的起点 ✓）——
            #     用户口径的重点：下跳要"**趴着时按跳**"才触发，而趴下去要一点点时间 ⇒
            #     那一下要是按早了就白按 ⇒ **一遍遍连按**，总有一下落在趴着的时候 ✓。
            # ⛔ **2026-09-28 修：这一段的顺序反了** ✗（用户当天报"**趴在那不动了也不按跳**"）。
            #   原来"该**按**"写在前面、靠 `now - _jump_at >= TAP_PERIOD_S` 判 ⇒ **拍间隔一旦
            #   大于「点按周期」`TAP_PERIOD_S`(180ms)**，每拍都会命中"重新按"那条 ⇒
            #   **整段跳过"松窗"**（`[TAP_ON_S, TAP_PERIOD_S)`）⇒ 退化成**按住跳** ✗
            #   （实测：拍间隔 200ms ⇒ 输出序列全是"按住"、10 秒只算出 1 下 ✗；
            #    拍间隔 25ms ⇒ 正常"按 3 拍、松 5 拍"✓）⇒ 而**"一直按住跳会被游戏当成还挂在
            #   上面"**（用户 2026-09-26 口径 ✗）⇒ **下跳根本不触发** ✓ —— 现场"趴着不动"就是它 ✓。
            #   ⇒ 改成**先判"该松"**（按 `_jump_on` 这个**状态**判，不靠窗口落点 ✓）：
            #     跳按下去之后，只要过了 `TAP_ON_S` 就**必须松**；松了之后才轮到"该按" ✓。
            #     这样最差也只是"按一拍、松一拍"（周期 = 2 拍 ⇒ 慢拍下约 2.5 下/秒 ✓），
            #     **绝不会**再退化成按住 ✓。
            if self._jump_on and (float(now) - self._jump_at) >= TAP_ON_S:
                return self._out(0, False, hold_dir=True)
            if (self._jump_at is None
                    or (float(now) - self._jump_at) >= TAP_PERIOD_S):
                self._jump_at = now
                self.note = ("按住 ↓ + 连按跳（第 %d 轮，%.1f s 内看 Y 动不动）"
                             % (self._tap_n, self.stall_s))
                #                    ↓ 按住 + 这一下跳按下 ✓
                # ⛔ 原来这里带 `reassert=`（"顺手把 ↓ 也重发一次"✓）—— 2026-10-06 删 ✗：
                #   用户要求"**按键补按逻辑移除**"。对面要是把 ↓ 丢了，靠的是**③''' 那条
                #   回入口**（回入口那一拍把键全松开 ⇒ 下一轮的"按住 ↓"是**真正的新按下** ✓），
                #   不再靠"键集没变也重发一遍" ✗。
                return self._out(0, True)
            if (float(now) - self._jump_at) < TAP_ON_S:
                # 这一下还没够时长 ⇒ 继续按着 ✓
                return self._out(0, True)
            return self._out(0, False, hold_dir=True)   # ↓ 继续按着，等下一 下 ✓

        # ---- ④ 等落地：↓ 已经松开（用户口径"Y 变化超过误差范围**才能**松开 ↓"）⇒ 什么都不按 ----
        # ⚠ **"松了却没落下去"必须有退路**（否则它会一直"什么都不按"地挂到「寻路超时」✗）：
        #   超过「移动操作尝试间隔」（`retry_ms`，= 用户定的"移动操作尝试间隔"）还没到 ⇒
        #   **回入口**：重新对齐、再按跳 ✓。走到这儿通常意味着那次点按跳没生效
        #   （对面把键丢了 / 按早按晚了 / 人根本没离地 ✓）。
        if (self.retry_ms > 0 and self._landing_at is not None
                and (now - self._landing_at) * 1000.0 >= self.retry_ms):
            return self._to_entry("松开 ↓ 后 %.0f ms 还没落地 ⇒ **回入口**重来" % self.retry_ms)
        return self._out(0, False)

    def _to_entry(self, why):
        """**回入口**：相位打回 `ALIGN`（= 流程图顶部那个"**当前 foothold 是否可下跳**" ✓）
        + 把这一轮的运行时状态**全部清干净**。

        两处调用它（**一处实现** ✓，别各写一遍 ✗）：
          · ⭐ ③'''「**移动操作尝试间隔**」内没反应（用户 2026-10-06 ✓ 本轮改的口径）；
          · ④ 「松开 ↓ 之后 `retry_ms` 还没落地」（2026-09-27 的退路 ✓）。

        ⚠ `_pick = None` ⇒ 回到 `ALIGN` 会**重新就近挑**一块可下跳 foothold（流程图"否"那条 ✓）；
          ⚠ `_falling = False`：走到这儿就说明"这一轮没能落下去"，下一轮从头看 ✓；
          ⭐ **它的返回值就是"回入口那一拍"**（`_out(0, False)` ⇒ **一个键都不按** ✓）：
            调用方一律 `return self._to_entry(...)` ✓ —— 这一拍"真的松开"是**故意的**，
            因为 `KeyState` 只在**键集变化**时才发键 ⇒ 不松这一下，下一轮那个"按住 ↓"
            对面**收不到新的按下** ⇒ 人**不趴** ⇒ 以后每一下跳都只是**原地跳** ✗
            （原来靠"补按"绕开，现在靠"真的松一下 ⇒ 真的一次新按下"解 ✓ 见类 docstring ✓）。
        """
        self.attempt += 1
        self.phase = self.ALIGN
        self._in_tol_since = None
        self._pick = None
        self._armed_at = None
        self._attempt_at = None
        self._y_base = None
        self._jump_at = None
        self._landing_at = None
        self._next_round_at = None
        self._falling = False
        self._jump_reassert_at = None
        self.note = ("%s（第 %d 次；整体由「寻路超时时间」兜底）" % (why, self.attempt))
        return self._out(0, False)

    def _falling_jump(self, now):
        """**下落过程中**这一拍要不要按跳 —— 按「移动操作尝试间隔」补按（用户 2026-09-28 ✓）。

        口径（用户原话）："下落过程中也按照『移动操作尝试间隔』补按 **按住 ↓ + 跳**" ✓。

        ⚠ 为什么需要：原来这一段（`_falling`）是"只按住 ↓、**不再点按跳**"✗，理由是"跳是用来
          **触发**下落的、已经在掉了" —— 可下落途中**自己也会卡住**：**被绳吸住 / 卡在半空的
          绳上**（`_detach_step` 那条"被绳吸住"正是靠按跳脱离 ✓）⇒ 只按 ↓ 会**一路干等到
          寻路超时** ✗（现场就是"按住 ↓ 时没有按跳，也没有补按，直到超时"✗）。
        ⚠ 节奏**照抄**「移动操作尝试间隔」`retry_ms`（**同一份**节拍 ✓，不新造时长 ✓）：
          到一个间隔按一下跳、按满一小段就松开，如此反复 ✓；
          `retry_ms <= 0` ⇒ **不补**（用户在设置里关掉重试 ⇒ 尊重设置 ✓）。
        ⚠⚠ **只有这一处在"补按"了**（2026-10-06 ✓）—— "按住 ↓ 的重发"那套（`_hold_reassert`）
          已按用户要求删掉 ✗；这里的"补按跳"是**另一件事**（下落途中跳一下也救"被绳吸住"✓），
          且它是**真的重新按下跳**（键集变了 ⇒ 对面收得到 ✓），不是"重发一个已经在按的键"✓。
        ⚠ **第一下立刻按**（进"下落"那一拍就按 ✓）：下跳的触发条件是"**趴着时按跳**" ✓，
          早按不亏，还能救"被绳吸住"那种 ✓。
        ⚠ 这段**只判"跳"**：↓ 由调用方 `hold_dir=True` 保证**全程按着** ✓（用户 2026-09-27：
          "除非位置状态到了目的地，否则 ↓ 不能松开" ✓）。
        ⚠ ⚠ **别退化成"一直按住跳"**：`retry_ms` 若比「点按时长」还短 ⇒ 把这一下的按满时长
          钳到**间隔的一半**（保证至少松一拍 ✓）—— 用户 2026-09-26 口径："一直按住跳会被游戏
          当成**还挂在上面**" ⇒ 下跳根本不触发 ✗。
        ⚠ 点数会进 `drop_taps` 探针（`_out` 数上升沿 ✓）⇒ 日志里能看出"补按在跑" ✓。
        """
        if self.retry_ms <= 0:
            return False
        on_s = min(TAP_ON_S, (self.retry_ms / 1000.0) * 0.5)
        if self._jump_reassert_at is None:
            self._jump_reassert_at = float(now)
            self.note = ("下落中：↓ 一路按着 + 按「移动操作尝试间隔」（%.0f ms）补按跳"
                         "（等落到「%s」再松 ↓）" % (self.retry_ms, self.dst_set))
            return True
        dt = float(now) - self._jump_reassert_at
        if dt < on_s:
            return True                     # 这一下还没按满 ⇒ 继续按着 ✓
        if dt * 1000.0 >= self.retry_ms:
            self._jump_reassert_at = float(now)     # 又到了一个间隔 ⇒ 再按一下 ✓
            return True
        return False                        # 间隔期 ⇒ 跳松开（↓ 仍按着 ✓）

    def _y_changed(self, py):
        """**Y 是不是真的开始下落了**：相对本次尝试的基准**向下**变化 ≥「坐标对齐误差范围」。

        用户 2026-09-27 的口径（下跳第 ④ 条）："**当 Y 变化超过「坐标对齐误差范围」才能
        松开 ↓**" ⇒ 这就是**松开 ↓ 的唯一正常理由** ✓（另一处是第 ③' 条的"尝试间隔内没动
        ⇒ 补发一个松开 ↓ 再重来"，那也是用户定的 ✓）。

        ⚠ **只认向下**（y 变大 = 真的掉下去了 ✓）：**向上抖不算** ✗。以前这里写的是
          `abs(...)`，于是人还站在平台上、读数向上抖一下（>误差范围）就被判"开始下落"、
          把 ↓ 松掉 ⇒ 那一次下跳当场作废，而且之后停在"等落地"什么都不按 ✗
          （现在就算误松也有回入口兜底 ✓，但判据本身就该只认下落 ✓）。
        ⚠ 没有 y 读数（定位掉帧）⇒ **不判**（观测问题，不是"没动" ✗）；`_y_base is None`
          ⇒ 也不判（DROP 里已经保证"没基准就不按跳" ⇒ 正常走不到 ✓）。
        """
        if py is None or self._y_base is None:
            return False
        return (float(py) - self._y_base) >= self.y_tol_px

    def retry(self):
        """失败后**重新激活**：回到对齐那一步重来（和 ClimbJob 同一套保护）。"""
        self.attempt += 1
        self.phase = self.ALIGN
        self._t0 = None
        self._in_tol_since = None
        self._armed_at = None
        self._y0 = None
        self._attempt_at = None
        self._y_base = None
        self._jump_at = None
        self._landing_at = None
        self._tap_n = 1
        self._next_round_at = None      # "松着 ↓ 等间隔"也收干净（新的一轮从对齐开始 ✓）
        self._jump_reassert_at = None   # "下落中补按跳"那笔账同理（下次下落重新计 ✓）
        self._falling = False           # "已经在掉"同样收干净 ✓
        self._detach_tap_at = None      # "被绳吸住、正在脱离"同理收干净 ✓
        # ⚠ 不写分母（同 `ClimbJob.retry`：没有"最多试几次"了 ✓）
        self.note = "第 %d 次尝试：重新对齐（下跳）" % self.attempt
        return self._out(0, False)

    def cancel(self, why="取消"):
        # ⚠ **运行时字段一起收干净**（用户 2026-10-02 #8 ✓ 见 `_cancel_common` ✓）——
        #   原来这里只置相位，带着脏锚被复用就是隐患 ✗。
        self._cancel_common(why)
        return self._out(0, False)

    def _arrived(self, py, here_sets, ground_y=None, on_rope_pos=None):
        """到了没有：**先集合后几何**（和下跳那边同一套口径）。

        ⛔ **2026-09-28 加一条总闸：人在绳上就不算到**（用户现场："从**顶层到三楼**的下跳期间
        **上绳子了**，但是 drop 执行器没有从位置状态机拿到上绳通知而去执行跳开绳子的逻辑"✗）。
        根因：**感知的"脚下"会被绳段下方的平台骗**（实测图 `106010105` 的绳 L2：人挂在
        y=-291（绳正中）、离下面那块面还有 109px，`pos_state` 仍给
        `ground_y=-182` + `here_sets=['三楼']` ✗ —— 因为 `foothold_below` 只对"头顶上方"
        卡 40px 容差、**下方不卡** ✗）⇒ 于是上面两条判据**双双误报"到了"**：
        · 集合那条 ⇒ 直接 `done`（日志：`prev=drop to=done  note=到达：脚下已经是「三楼」`
          ✗ 而人还在绳上 ✗）⇒ 任务提前收工 ⇒ **根本轮不到"跳开绳子"** ✗；
        · 面 y 那条 ⇒ 绳段下方的面正好等于目标面时同样误报 ✗。
        ⇒ 判据：**`on_rope_pos` 非空（位置就落在某根绳的绳段里）⇒ 一律不算到达** ✓
        （`on_rope_pos` 与按键许可无关 ✓，正是"人挂在绳上"这个客观事实 ✓）。
        ⚠ 只在**下跳**这儿收这道闸（用户 2026-09-28 明确："不动 `foothold_below`"✓）——
        不动那个共用判据，避免波及集合归属 / 段 / 起点判定那些消费方 ✓。

        下面两条判据的细节：

        ⭐ **几何兜底 = 「脚下这块面就是目标平台的面」**（用户 2026-09-28 明确要求 ✓）：
        读**位置状态广播**的 `ground_y`（"脚下那块面的 y"，按玩家 x 取 ✓），命中目标集合
        里任意一条 foothold 的面 y（± `y_tol_px` ＝「坐标对齐误差范围」✓）就算落地 ✓。
        ⛔ **旧判据已删**（"y 比出发时大了 `DROP_DY_PX`(40px)"✗）：太松 —— 人只要往下掉
        40px 就报"到了"，哪怕还在半空、或者落到了**别的**平台上 ✗（实测：追击反复下发同一条
        下跳任务，就是它误报"到了" ⇒ 人其实没下去 ⇒ 下一拍又判"怪不在我这块平台" ⇒ 又下 ✗）。
        ⚠ 目标面算不出来（`dst_ys` 空：老调用方 / 目标集合没圈 foothold）⇒ **退回只看集合** ✓
        —— **不许**再拿"掉了多少像素"凑一个数 ✗（那正是这次要拆掉的东西 ✓）。
        """
        if on_rope_pos:
            # 人正挂在绳段里 ⇒ 上面的"脚下"读数**不可信**（绳段横跨好几层 ⇒ 报出来的
            # 常常是**绳下方那层**的面 ✗）⇒ 一律不算到 ✓（见 docstring 里那条实测 ✗）。
            return ""
        if here_sets and self.dst_set and self.dst_set in set(here_sets):
            return "到达：脚下已经是「%s」" % self.dst_set
        if ground_y is not None and self.dst_ys:
            _g = float(ground_y)
            for _y in self.dst_ys:
                if abs(_g - float(_y)) <= self.y_tol_px:
                    return ("到达：位置状态广播「脚下那块面 y=%.0f 就是目标平台的面（%.0f）」"
                            % (_g, float(_y)))
        return ""

    def _fail(self, why):
        self.phase = self.FAILED
        self.note = why
        return self._out(0, False)

    def _detach_dir(self, px):
        """脱离时按住哪个**水平方向**（±1）。

        ⭐ **用户 2026-09-28 按流程图定的口径**（原话："跳下绳子：按**任意方向**+跳（**若有锁定
        目标则是锁定目标方向**）"）：
          · **有锁定目标** ⇒ **朝它**（读注入的 `_target_dir_fn()` ✓：`+1` 右 / `-1` 左 / `0`
            没有目标或同列 ⇒ 落到下面那条 ✓）；
          · **其余情况** ⇒ **任意方向**（取一个**确定性**的：**背离下跳点中心** ✓ —— 顺手离它
            远一点，别刚松手又被吸回去 ✓）；还没挑定下跳点（或 x 正好在中心）⇒ 向右 ✓。
        ⚠ 注入位用 `getattr` 兜底：**没有注入 / 注入的回调抛异常** ⇒ 都当成"没有目标" ✓
          （**绝不许**因为拿不到目标就报错或停住 ✗ —— 脱离那几拍按不出方向就等于卡死在绳上）。
        """
        _td = 0
        _fn = getattr(self, "_target_dir_fn", None)
        if _fn is not None:
            try:
                _td = int(_fn() or 0)
            except Exception:                 # noqa: BLE001 —— 回调坏了 ⇒ 退回"任意方向" ✓
                _td = 0
        if _td > 0:
            return 1                          # ⭐ 锁定目标在右边 ⇒ 朝它 ✓
        if _td < 0:
            return -1                         # ⭐ 锁定目标在左边 ⇒ 朝它 ✓
        if self._pick is None:
            return 1
        return -1 if float(px) > float(self._pick[0]) else 1

    def _detach_step(self, now, px):
        """「**被绳吸住 ⇒ 按住方向 + 连按跳**」的一拍（用户 2026-09-27 口径，照抄）。

        ⚠ **绝不按 ↓**（`vert=0`）：在绳上按 **↓** 在游戏里是"**还挂在绳上**"（同一条口径见
          `ClimbJob._out` 的 `vert` 说明 ✓）⇒ 按 ↓ 等于把自己按回去 ✗；
          而按**左右**是"松手"（同一条口径的另一面 ✓）—— 所以这几拍只发"**左右 + 跳**" ✓。
        ⚠ 跳按**同一份点按节奏**（`TAP_ON_S` / `TAP_PERIOD_S` ✓，不新造时长 ✓）：
          和下面 ③ 的"连按跳"是同一个理由（那一下可能还没到"能起效"的时机 ⇒ 一遍遍按 ✓）。
        """
        step = self._detach_dir(px)
        if (self._detach_tap_at is None
                or (float(now) - self._detach_tap_at) >= TAP_PERIOD_S):
            self._detach_tap_at = now
        jump = (float(now) - self._detach_tap_at) < TAP_ON_S
        self.note = ("在下跳中被绳吸住了 ⇒ 按住 %s %s 脱离"
                     "（**不按 ↓**：在绳上按 ↓ = 还挂在绳上 ✗）"
                     % ("→" if step > 0 else "←", "并连按跳" if jump else "、等下一 下跳"))
        return self._out(step, jump, vert=0)

    #: 相 → 编码（**给 `behavior.log` 的 `drop_phase` 用** ✓）。
    #: 为什么非要有它（2026-09-28 现场）：上绳那套 `climb_phase` **只认 `ClimbJob` 的相名**
    #: （`CLIMB` / `JUMP_DOWN`）⇒ **下跳任务在它眼里恒 0** ✗ ⇒ 卡住的那近 9 秒里日志只剩一排
    #: `climb_phase=0.0`，**看不出卡在哪一相** ✗（用户当场只能报"实际爬上了向下爬的绳子"）。
    #: ⚠ 加新相时**两处一起改**（这里 + `update` 里的相名 ✓）。
    _PHASE_CODES = {ALIGN: 1, ARMED: 2, DROP: 3, LANDING: 4, DETACH: 5,
                    DONE: 6, FAILED: 7}

    def phase_code(self):
        """这一拍在哪一相（数字，见 `_PHASE_CODES` ✓）—— 日志/界面读它 ✓。"""
        return self._PHASE_CODES.get(self.phase, 0)

    def align_target_x(self):
        """这一轮挑中的**下跳点中心 x**（还没挑定 ⇒ `None` ✓）—— 日志里看"还差多远" ✓。"""
        return float(self._pick[0]) if self._pick else None

    def tap_count(self):
        """已经**点按跳**多少下（**上升沿**计数 ✓）。

        用户 2026-09-28 报"**趴在那不动了也不按跳**"：光看 `drop_phase=3`（在 DROP 相）**分不清**
        "跳压根没发出去"和"发了但游戏没响应" ✗ —— `drop_taps`（每秒记一次）数字在涨 ⇒ 跳在发 ✓；
        不动 ⇒ 见 `drop_round`（轮次有没有在转 ✓）。
        """
        return int(self._taps)

    def round_n(self):
        """现在是第几轮「按住 ↓ + 连按跳」（1 起 ✓）—— 看轮次**有没有在转** ✓。

        ⚠ 2026-10-06 起"轮"的含义变了：一轮 = **一次"按住 ↓ + 连按跳"的尝试**，
        轮与轮之间是 **③''' 回入口**（相位打回 `ALIGN` ⇒ 重新判"当前这块 fh 还能不能下跳" ✓），
        不再是"松 ↓ 空等「移动操作尝试间隔」"（那套早删了 ✗）。
        """
        return int(self._tap_n)

    # ⛔ **`reassert_count()` 已删**（2026-10-06 ✓ 用户要求"按键补按逻辑移除"）：
    #   它数的是"重发了几次「按下 ↓」"，而这个机制本身没了 ✗ ⇒ 没有来源 ✓
    #   （`behavior.log` 里那条 `drop_reassert` 探针同步删 ✓）。"有没有反应"现在看
    #   **`drop_round`（轮次转不转）** + `route_phase`（回没回 `ALIGN`）✓。

    def _out(self, move, jump, hold_dir=False, vert=None, replan=False):
        """`vert`：这一拍要不要发 ↓（`None` = 老规则：按跳或 `hold_dir` 时发 `self.dir`=↓ ✓）。

        ⚠ 「**被绳吸住要脱离**」那几拍必须传 `vert=0`：在绳上按 ↓ 是"还挂在绳上"（口径同
          `ClimbJob._out` ✓）⇒ 按 ↓ 等于把自己按回去 ✗；那几拍只按**左右 + 跳** ✓。

        ⛔ **没有 `reassert` 这个参数了**（2026-10-06 ✓ 用户要求"按键补按逻辑移除"）——
          `ClimbJob._out` 那边**照旧有**（爬绳的「补按 ↑」是另一条口径 ✓）。下跳不再"重发
          已经在按的键"，改成"**回入口**那一拍真的松开全部键"（见 `_to_entry` ✓）。
        """
        d = (self.dir if (jump or hold_dir) else 0) if vert is None else int(vert)
        # ⭐ **点按跳的"上升沿"计数**（见 `tap_count` ✓）：`jump` 会连着几拍为真（要按满
        #   `TAP_ON_S` ✓），只数"从没按到按"那一下 ⇒ 这个数 = **真发出去的"跳按下"次数** ✓
        #   （用户 2026-09-28："趴在那不动了也不按跳" —— 有它才能分清是"没发"还是"不响应" ✗）。
        if jump and not self._jump_on:
            self._taps += 1
        self._jump_on = bool(jump)
        # ⭐ 记下这一拍请他按的竖直键（给 ladder_id 许可的「执行器通知」用，同 ClimbJob ✓）
        self._last_vert = int(d)
        return self._result(move, jump, d, replan=replan)


def drop_job_for_edge(terrain, z, edge, **kw):
    """从一条「下跳」边造出任务：可下跳 foothold 取边上的那一格（不填 = 起点集合的全部）。

    抛 ValueError 的两种情况：一个可下跳的都没有、或者那些 id 在本图里找不到
    （换了地图/地形重导过）—— **不许猜**，让上层报警或跳过。

    坐标口径同 `job_for_edge`：地形数据本来就在世界坐标系里，玩家读数与它**直接比** ✓。
    """
    from core import zones

    if (edge.get("kind") or "") != "drop":
        raise ValueError("不是「下跳」边：%s" % edge.get("kind"))
    ids = zones.drop_footholds(z, edge)
    if not ids:
        raise ValueError("这条下跳边一个可下跳 foothold 都没有：%s → %s"
                         % (edge.get("from"), edge.get("to")))
    known = {str(f.fid): f for f in terrain.footholds}
    spots = []
    for fid in ids:
        f = known.get(str(fid))
        if f is None or f.is_wall:
            continue
        # ⭐ **五元组**（中心 x, 左, 右, **面 y**, id ✓ 同 `WalkJob` 的落点形状 ✓）：
        #   面 y = 该 foothold **中点 x** 处的面 y（与 `_set_spans` 同一口径 ✓）——
        #   ALIGN 用它判"**人是不是站在这一块面上**"（用户 2026-10-02 ✓ 见 `DropJob.update`
        #   的 ALIGN ✓，就是这次"掉到别的层还按 ↓+跳"那个 bug 的闸 ✓）。
        _mid = (f.left + f.right) / 2.0
        spots.append((_mid, f.left, f.right, float(f.y_at(_mid)), str(fid)))
    if not spots:
        raise ValueError("可下跳 foothold 在本图里都找不到（或都是墙）：%s" % (ids,))
    # ⭐ **目标平台的"面 y"**（用户 2026-09-28：下跳的到达判据换成"脚下这块面 == 目标面"✓）——
    #   取**目标集合里所有非墙 foothold 的面 y**（`_set_spans` 给的是"该 foothold 中点 x 处的
    #   面 y" ✓，与择路同一口径 ✓）；运行时落点是哪一条取决于从哪个下跳点跳 ⇒ 这里**不预先
    #   绑定**那一条，`DropJob` 命中任意一条即算 ✓。
    dst_ys = [float(s[2]) for s in _set_spans(terrain, z, edge.get("to"))]
    return DropJob(edge.get("from"), edge.get("to"), spots, dst_ys=dst_ys, **kw)


#: 走（walk）的到达容差：与目标 foothold 的 x 范围差 ≤ 它就算到（像素）。
#: 为什么给容差：走是"走到那块**地面**上"，不是"走到某个像素" —— 人站上那条 foothold
#: 的范围就该算到（集合判据优先，见 `WalkJob._arrived`）。
WALK_TOL_PX = 12.0

#: 几何兜底判据允许的高度差（像素）：站上去以后 y 和那条 foothold 的面差这么多以内
#: 才算"站在它上面"（防止 x 对了、其实人在上一层/下一层的平台上）。
WALK_Y_BAND_PX = 30.0


class WalkJob(_PausableJob):
    """一次「走过去」：沿地面走到目标集合的某条 foothold 上。

    对外形状和 `ClimbJob` / `DropJob` **完全一样**（`update()` 是纯函数 + `retry()` /
    `cancel()`）⇒ `agent._climb_tick` 里那套"任务优先 / 有怪先打 / 失败延迟重来 /
    结束原因挂在画面上"**一行都不用改**就能用（2026-09-26 用户要求"把 walk 的执行器做了"）。

    到达判据（**先集合后几何**，和别的任务同一口径）：
      · 脚下集合已经有目标集合 ⇒ 到了（人确实站在那块地上了 ✓ 走是唯一"站上去就算到"
        的任务 —— 上绳不行，因为定位抖一下会把差 38px 的地方报成"已在集合"，见
        `ClimbJob._arrived` 的说明）；
      · 否则几何兜底：站在目标集合某条 foothold 的 x 范围 ±`WALK_TOL_PX`、且 y 和它的面
        差 ≤`WALK_Y_BAND_PX`。

    动作：`move` 给 -1/0/+1（左右），**不按跳、不按上下** —— 走就是走；差得远按住走，
    快到了（≤`NEAR_PX`）改成点按，别冲过头（和上绳对齐同一个做法）。
    ⚠ 这条边配了 `dir`（仅向左 / 仅向右）时**没有"快到了"这一说**：一直按那一边，直到
    判到达、或者"一直不动"被判失败（见 `update` 里那一段与 `walk_dir` 的说明）。
    卡住（朝目标那侧的距离 `stall_s` 秒没变好）⇒ 失败并说清卡在哪个 x（被墙/台阶挡住
    时人要看得懂，而不是干等到超时 ✗）。
    """

    WALK = "walk"
    DONE = "done"
    FAILED = "failed"

    # ⚠ 这里**曾经**有 `MODE_CENTER / MODE_LEFT / MODE_RIGHT` 和一个 `mode` 参数
    #（还摆进了设置里的「走的方向」下拉）。2026-09-26 用户明确否掉：
    # **默认只有一种走法 —— 朝目标集合的 x 中点**，设置里不许有这个参数。
    # 并留了一句："将来若某一步真需要只按 ← 或 →，那是**逐边**的事：在
    # foothold 编辑器 →「可到达」窗口里配，而不是全局设置。"
    #
    # ⚠ 那个"将来"就是现在（2026-09-27 用户报"我配的通行方式是向左走，可它根本没向左"）：
    # **逐边**的 `dir` 真的接进来了 —— `walk_dir` 参数 ← `walk_job_for_edge` ← 边的 `dir` ✓。
    # **全局设置那条仍然禁止**（`t_walk_only_center` 反向钉着）：它只能来自某一条边 ✓。

    def __init__(self, dst_set, spots, tol_px=WALK_TOL_PX, hold_ms=None,
                 timeout_s=DEFAULT_TIMEOUT_S,
                 stall_s=STALL_S, walk_dir="", stall_jump=True):
        #: ⚠ `stall_s`（"走不动了"的判定时长）**故意只认这个常量默认值** ——
        #: 设置里那格「卡住判定时长(s)」**只管攀爬**（用户 2026-09-27 明确："移除对走的
        #: 相关判定，走用超时配置兜底"⇒ `job_for_edge` 会把那一格从走的参数里摘掉 ✓）。
        #: 走这边的卡住由「寻路超时时间」（`goto_timeout_s`）兜底 ✓。**别把它接回设置** ✗。
        #: ⚠ `hold_ms` 收下但**不用**：走没有"到达后再按住一会儿"这回事（那是上绳需要的，
        #: 因为读数滞后 + 游戏里迈上平台那一步要按着 ↑）。之所以要有这个参数：三个任务
        #: 走的是**同一个调用入口**（`route_panel._command_first_step` 会把对齐参数一起
        #: 传进来），少一个参数就是 `TypeError` —— 实测就是这么炸的 ✗。
        #: 目标集合名（`agent.current_goto_set()` 用它显示"前往：X"）。
        self.dst_set = str(dst_set or "")
        #: 候选落点 `[(中心x, 左, 右, 面y, foothold id)]` —— 由 `walk_job_for_edge` 给。
        self.spots = [tuple(s) for s in spots]
        self.tol_px = max(1.0, float(tol_px))
        self.timeout_s = float(timeout_s)
        self.stall_s = max(0.5, float(stall_s))
        #: 第几次尝试 —— ⚠ **不是上限**（没有"最多试几次"了，见文件头那段 ✓）
        self.attempt = 1
        self.phase = self.WALK
        #: 这条边配的走法 —— **逐边**配的（foothold 编辑器 →「可到达」窗口），
        #: 取值见 `core.zones.WALK_DIRS`：
        #:   ""      = 朝**目标集合的 x 中点**走（老行为，2026-09-26 用户定的唯一走法 ✓）
        #:   "left"  = **只按 ←**（"仅向左"）
        #:   "right" = **只按 →**（"仅向右"）
        #:
        #: 为什么现在才做它：`dir` 原来只是**空占位**（`core/zones.py` 里写着"逻辑等后面
        #: 做"）⇒ 用户 2026-09-27 现场报"配了「仅向左」根本没向左"就是踩在这上面：
        #: 「左上平台 → 左上」目标集合是**整片**「左上」（x 从 -387 到 657、中点 135），
        #: 人站在平台上（x≈2~87）⇒ 中点还在**右边** ⇒ 老代码一路按 → ✗，而且"到集合区间
        #: 的距离"恒为 0 ⇒ 3 秒后判「走不动了」= 卡住 ✗（复现见 tools 里那次探针）。
        #:
        #: ⚠ **全局设置里不许**有这个参数（2026-09-26 用户明确否掉，见本类注释）；它只能
        #:   来自**这一条边** ✓。
        self.walk_dir = (str(walk_dir or "") if str(walk_dir or "") in ("left", "right")
                         else "")
        self.note = ("走过去：「%s」（这条边配了**只能往%s**，一直按到踏上它）"
                     % (self.dst_set, "左" if self.walk_dir == "left" else "右")
                     if self.walk_dir else
                     "走过去：「%s」（%d 个落点，就近）" % (self.dst_set, len(self.spots)))
        self._t0 = None
        self._best_d = None            # 离"最近那个目标点"最好走到过多近
        self._best_at = None
        #: ⭐「走不动之后**单点跳一下**」的两个锚（用户 2026-09-28 要求："walk 执行器判定
        #: 走不动了之后，发个单点跳键"）：
        #:   `_hopped` = 这一轮（一次 `retry` 周期内）跳过没 —— **一轮只跳一次** ✓（跳过
        #:     还走不动才 `_fail`，别无限跳 ✗）；`_hop_at` = 跳键按下去的时刻（点按
        #:     `TAP_ON_S`，None = 没在跳）—— 走不动被小台阶挡住时跳一下就过去了 ✓。
        #:   ⚠ 这两个**不进 `_ANCHORS`**：跳进行中只有 `TAP_ON_S`(30ms) 那么短，而且战斗
        #:     打断回来也不该接着跳（keys 已经清空，重新走就行 ✓）。
        self._hopped = False
        self._hop_at = None
        #: ⭐⭐ 「**走不动按跳**」（用户 2026-10-06 ✓ 见 `DecisionSettings.walk_stall_jump`）：
        #:   **关** ⇒ 走不动**直接判失败**（= 加这个单点跳之前的老行为 ✓）。
        #:   ⚠ 由 `agent.start_climb` **一处**灌进来（所有走任务都过那儿 ✓ 见那边的说明 ✓）。
        self.stall_jump = bool(stall_jump)
        #: 被战斗打断时要"跳过时长"的锚点（见 `_PausableJob`）：不扣的话，打完架回来
        #: 第一拍就 `now - _best_at ≥ stall_s` ⇒ 当场报"走不动了" ✗。
        #: （`_t0` **不在里面** —— 它由 `interrupted()` 直接**重打**：每次进战斗超时重算 ✓。）
        self._ANCHORS = ("_best_at",)

    # ---- 对外 ----

    def update(self, now, px, py=None, ladder_id=None, here_sets=None, at_top=None,
               at_bottom=None, ground_y=None, on_rope_pos=None,
               climb_failed=None, climb_stalled=None):
        """喂一拍 → 下一步该干什么。

        ⚠ `px` 必须是**世界坐标 x**（`WorldState.Player.world_x`），不是画面坐标
        —— 和 `ClimbJob.update` 同一个坑（喂错了会往反方向走、来回抖）。
        `ladder_id` 收下但不用（走不看绳）。
        """
        # 被战斗打断过 ⇒ 把"挨打那几秒"从计时锚点上扣掉，并把 `_paused_at` 收掉。
        # ⚠ 必须收掉：不收的话，下一段战斗就**不会再**重打超时了 ✗
        #（`interrupted()` 只在 `_paused_at is None` 时才动手 ✓）。
        self._resume(now)
        if self._t0 is None:
            self._t0 = now
        if self.phase in (self.DONE, self.FAILED):
            return self._out(0)
        if now - self._t0 > self.timeout_s:
            return self._fail("超时 %.0fs：没能走到「%s」" % (self.timeout_s,
                                                          self.dst_set))
        why = self._arrived(px, py, here_sets)
        if why:
            self.phase = self.DONE
            self.note = why
            return self._out(0)
        if px is None:
            # 定不了位就别乱走（往哪边走都可能是错的）—— 如实说，让人去查小地图
            self.note = "走出去：拿不到世界坐标（小地图定位没有输出）"
            return self._out(0)
        # ---- 单点跳进行中（走不动后那一跳）：按够 `TAP_ON_S` 就松，回到正常走 ----
        # 用户 2026-09-28：走不动先"单点跳一下"跳过小台阶，别直接判失败（见 `_hop_or_fail`）。
        # 跳键是**点按**（按 `TAP_ON_S` ≈ 30ms 就松，和「跳下绳梯」同一份节奏，不新造时长 ✓）。
        if self._hop_at is not None:
            if (now - self._hop_at) < TAP_ON_S:
                self.note = "跳一下：跳过小台阶（走不动了，先跳一下试试）"
                return self._result(0, jump=True)   # 只跳、不横挪（跳起来挪会挪歪 ✓）
            self._hop_at = None                      # 跳完了 ⇒ 下面接着走
        # ---- 「仅向左 / 仅向右」（逐边配的 `dir`，2026-09-27 起真的生效）----
        # 只按那一个方向键、**不看集合中点**：这种边说的是"朝那个方向一直走，直到踏上
        # 目标集合"（典型：平台边缘往左走出去、掉到下面那层 ✓）。
        # 进度用**位移**本身（左 = px 变小、右 = px 变大）—— ⚠ 不能用上面那种"到集合
        # x 区间的距离"：目标集合整片盖住人的 x 时那个距离**恒为 0** ⇒ 走得好好的也会被
        # 判「走不动了」✗（用户 2026-09-27 现场就是这么卡住的：人站在 x≈2~87、「左上」
        # 的区间是 -387~657 ⇒ 距离恒 0 ⇒ 3 秒后必报卡住）。
        if self.walk_dir:
            sign = -1 if self.walk_dir == "left" else 1
            _prog = float(px) if sign < 0 else -float(px)
            if self._best_d is None or _prog < self._best_d - 1.0:
                self._best_d, self._best_at = _prog, now
            elif self._best_at is not None and (now - self._best_at) >= self.stall_s:
                return self._hop_or_fail(
                    now,
                    "走不动了：这条边是「仅向%s」，x 卡在 %.0f、%.0fs 没再%s"
                    " —— 可能被墙/台阶挡住，或者这条边配的方向反了（目标「%s」在另一头？）"
                    % ("左" if sign < 0 else "右", float(px), self.stall_s,
                       "变小" if sign < 0 else "变大", self.dst_set))
            self.note = "走过去：这条边是「仅向%s」⇒ 只按 %s（走到「%s」上才算到；现在 x=%.0f）" % (
                "左" if sign < 0 else "右", "←" if sign < 0 else "→",
                self.dst_set, float(px))
            return self._out(sign)
        # 目标 x = 集合的**中点**（所有落点 x 的中点）—— 走只有这一种走法（2026-09-26 用户定；
        # "仅向左 / 仅向右"那个选项已删，见 `__init__` 上面的说明）。
        target_x = (min(float(s[0]) for s in self.spots)
                    + max(float(s[0]) for s in self.spots)) / 2.0
        #: 提示里那句话（写清"目标是集合中点"）
        tgt_txt = "集合中心 x=%.0f" % target_x
        dx = target_x - float(px)
        d = abs(dx)
        # **卡住检测**：朝目标那侧的距离一直不变好 ⇒ 被挡住了（墙/台阶/逆风），
        # 报出来比干等到超时有用得多（上绳那边同一套判据，见 STALL_S）。
        # ⚠ 进度用**到"集合区间"的距离**，不用上面那个 `d`（`d` 是到"中点"的距离）：
        # 站在中点附近、还没踏进集合时它会一直不变 ⇒ 走得好好的也会被判"走不动" ✗
        # 到区间的距离才是单调下降的 ✓（这里原本还替"仅向左/仅向右"兜了一道，
        # 那个模式 2026-09-26 已按用户要求删掉，但这条判据本身仍然更对）。
        _lo = min(float(s[1]) for s in self.spots)
        _hi = max(float(s[2]) for s in self.spots)
        _prog = (0.0 if _lo <= float(px) <= _hi
                 else min(abs(float(px) - _lo), abs(float(px) - _hi)))
        self._best_d, self._best_at, _stalled = self._stalled_since(
            now, _prog, self._best_d, self._best_at, self.stall_s,
            lambda v, b: v < b - 1.0)             # 走路：离落点越近越好（缩小 ≥1px 才算进步 ✓）
        if _stalled:
            return self._hop_or_fail(
                now,
                "走不动了：卡在 x=%.0f（目标在%s，还差 %.0f px）"
                "—— 可能被墙/台阶挡住，或者这条边的落点/方向写错了"
                % (float(px), tgt_txt, d))
        if d <= self.tol_px:
            self.note = "走到落点附近了（差 %.0f px）—— 站住，等判到达" % d
            return self._out(0)
        sign = 1 if dx > 0 else -1
        if d <= NEAR_PX:
            # 快到了 ⇒ **点按**，别冲过头（和上绳对齐同一个做法，见 ClimbJob）
            if (float(now) % TAP_PERIOD_S) < TAP_ON_S:
                self.note = "微调：差 %.0f px（点按 %s）" % (d, "→" if sign > 0 else "←")
                return self._out(sign)
            self.note = "微调：差 %.0f px（松开这一拍，别冲过头）" % d
            return self._out(0)
        self.note = "走过去：目标在%s，还差 %.0f px（%s）" % (
            tgt_txt, d, "→" if sign > 0 else "←")
        return self._out(sign)

    def retry(self):
        """失败后**重新激活**（和上绳/下跳同一套：回到起始状态重来一遍）。"""
        self.attempt += 1
        self.phase = self.WALK
        self._t0 = None
        self._best_d = None
        self._best_at = None
        # ⚠ 单点跳也重新武装：新的一轮允许再"走不动 → 跳一下"一次 ✓
        self._hopped = False
        self._hop_at = None
        # ⚠ 不写分母（同 `ClimbJob.retry`：没有"最多试几次"了 ✓）
        self.note = "第 %d 次尝试：重新走过去「%s」" % (self.attempt, self.dst_set)
        return self._out(0)

    def cancel(self, why="取消"):
        # ⚠ **运行时字段一起收干净**（用户 2026-10-02 #8 ✓ 见 `_cancel_common` ✓）
        self._cancel_common(why)
        return self._out(0)          # ★ 走只有 move 一个位置参数 ✓

    # ---- 内部 ----

    def _arrived(self, px, py, here_sets):
        """到了没有（先集合后几何 —— 走是唯一"站上去就算到"的任务，理由见类注释）。"""
        if here_sets and self.dst_set and self.dst_set in set(here_sets):
            return "到达：脚下已经是「%s」" % self.dst_set
        if px is None or py is None:
            # ⚠ 几何兜底**必须有 y 读数**：只看 x 会误判"换层"（同一 x 上下两层平台很常见，
            # 实测被自己的用例逮到过：x 对了、人在上一层也判到达 ✗）。没有 y 就等下一拍
            #（定位每拍都在给；一直给不出来会走到超时并如实报警）。
            return ""
        for _xc, left, right, y, _fid in self.spots:
            if (left - self.tol_px) <= float(px) <= (right + self.tol_px):
                if abs(float(py) - float(y)) <= WALK_Y_BAND_PX:
                    return ("到达：走到「%s」那条 foothold 上"
                            "（x=%.0f，面 y=%.0f）" % (self.dst_set, float(px), float(y)))
        return ""

    def _fail(self, why):
        self.phase = self.FAILED
        self.note = why
        return self._out(0)

    def _hop_or_fail(self, now, why):
        """走不动了：**先单点跳一下**（跳过小台阶/小障碍），跳过还走不动才判失败。

        用户 2026-09-28 要求："walk 执行器判定走不动了之后，发个单点跳键"。
        · 一轮只跳一次（`_hopped` ✓）：跳完清掉 stall 锚点重新计时，再走不动才 `_fail`
          （被真墙挡住时不会无限跳 ✗）；
        · 跳的那一下**只跳、不横挪**（`move=0`）—— 跳起来横着挪会挪歪，和上绳"跳失败后
          站住等 y 稳定"同一个道理 ✓；
        · 跳键是**点按**（按 `TAP_ON_S` ≈ 30ms 就松，见 `update` 里那段"跳进行中"），
          不新造时长常数 ✓。
        """
        # ⭐⭐ **开关**（用户 2026-10-06 ✓ "走不动按跳"）：关掉 ⇒ 走不动**直接判失败** ✓
        #   （= 加这个单点跳之前的老行为 ✓ 一字不差：`note` 还是原来那句"走不动了…" ✓）。
        if not self.stall_jump:
            return self._fail(why)
        if not self._hopped:
            self._hopped = True
            self._hop_at = now
            self._best_d = None            # 跳之前那段"没动"不算数，跳完重新计时 ✓
            self._best_at = None
            self.note = "%s ⇒ 先单点跳一下，跳过小台阶" % why
            return self._result(0, jump=True)
        return self._fail("%s（跳了一下还是没过去）" % why)

    def _out(self, move):
        """走不按跳、也不按上下（`dir` 恒 0）—— 回值走 `_PausableJob._result` 的统一形状 ✓。"""
        return self._result(move)


def walk_job_for_edge(terrain, z, edge, **kw):
    """从一条「走」边造出任务：落点 = 目标集合里的非墙 foothold（**不许猜**）。

    抛 ValueError 的两种情况：目标集合里一条 foothold 都没有、或者那些 id 在本图里
    找不到（换了地图/地形重导过）—— 让上层如实报警，别下一条"不知道往哪走"的命令 ✗。

    ⚠ **这条边的走法（`dir` = 仅向左 / 仅向右）在这里灌进任务**（2026-09-27 起生效；
    它原来是空占位）。逐边配的东西只有这一条路能传进去 —— 全局设置里不许有它
    （2026-09-26 用户明确否掉，见 `WalkJob` 注释）✓。
    """
    from core import zones

    if (edge.get("kind") or "") != "walk":
        raise ValueError("不是「走」边：%s" % edge.get("kind"))
    ids = set(str(v) for v in
              ((z.sets.get(edge.get("to")) or {}).get("footholds") or []))
    if not ids:
        raise ValueError("目标集合「%s」里一条 foothold 都没有：%s → %s"
                         % (edge.get("to"), edge.get("from"), edge.get("to")))
    spots = []
    for f in terrain.footholds:
        if f.is_wall or str(f.fid) not in ids:
            continue
        spots.append(((f.left + f.right) / 2.0, float(f.left), float(f.right),
                      float(f.y_at((f.left + f.right) / 2.0)), str(f.fid)))
    if not spots:
        raise ValueError("目标集合「%s」的 foothold 在本图里都找不到（或都是墙）：%s"
                         % (edge.get("to"), sorted(ids)))
    # 逐边的走法（`dir`）灌进来；调用方显式给了就以调用方为准（写用例时用得上 ✓）
    kw.setdefault("walk_dir", zones.walk_dir(edge))
    return WalkJob(edge.get("to"), spots, **kw)


#: 传送点**到达**判据的容差：抄 `core.mapdata.Terrain.PORTAL_DX/PORTAL_DY`（`portal_at` 同一口径 ✓
#: —— 那边判"人在某扇门的判定框里"用的就是这两个数 ✓ 别各写一份 ✗）。
#: ⚠ 它管的是"**我已经站在出口门上了**"这件事 ✓；**对齐**（走多准才按 ↑）用的是
#:   「坐标对齐误差范围」(`tol_px` ✓ 用户 2026-10-06 ✓) —— 两件事别混 ✗。
PORTAL_TOL_X, PORTAL_TOL_Y = 15.0, 12.0


#: 「**对齐 x 有进步**」的判据（世界像素）：`|dx|` 比纪录**小了这么多**才算真的靠近了 ✓
#: （读数的抖动不算进步 ✗ —— 不然"补按方向"永远不触发 ✓）。
ALIGN_PROGRESS_PX = 1.0


def align_x_decide(now, dx, *, press_dir, press_at, gap_ms, near_px, tol_px,
                   retry_ms=0, progress_at=None, best_dx=None):
    """「**把 x 对齐到某个数**」这一拍该怎么办 —— **爬绳与走传送点共用的一处实现** ✓。

    ⭐ 来源与用户口径（2026-10-06 ✓ 原话："我们应该**整套照搬对齐式爬绳梯的逻辑**，
      **还要补按方向**"✓）：规则**逐条**都是 2026-09-27/28 在爬绳上踩出来的 ✓
      （原实现内联在 `ClimbJob._align_step` ✓ 现在两边都调这里 ✓ 约定 10：一处实现 ✓）。

    规则（`kind` 三选一）：
      · `"wait"` —— 这一拍**不按键**（`move` 无意义 ✓）：
        ⓐ 近处（`|dx| ≤ near_px`）点按**按够了 `TAP_ON_S`(30ms)** ⇒ 松开
           （"别一路蹭过去 = 冲过头"✓）；
        ⓑ ⭐ 上一次按下距今**还没到「对齐绳梯移动延迟」`gap_ms`** ⇒ 站住等 ——
           ⚠⚠ **过冲之后往回按（换了方向）也走这一条** ⇒ **不会在目标两边来回抖** ✗✓
           （用户 2026-10-06 现场："在从5到4的 h010 传送门**左右来回晃**"✗ = 老 `PortalJob`
            每拍都按方向键 ✓ 这条正是治它的 ✓）；
      · `"press"` —— 这一拍按 `move`（±1 的横向方向键 ✓）；`reassert=True` ⇒ 调用方
        **再发一次 PRESS**（键集没变也发 ✓ —— `KeyState` 只在键集变化时发键，
        "对面把键丢了"本机不知道 ✗ 同 `ClimbJob` 那套补按 ✓）；
      · `"in_tol"` —— `|dx| ≤ tol_px` ⇒ **对齐好了**（调用方站住 / 稳住 `hold_ms` / 动作 ✓）。

    ⚠ **"远（> `near_px`）一口气按住 / 近了点按"** 这个分档也在里面：远距离点按会走得太慢、
      直接撞超时 ✗（同 `ClimbJob` 的口径 ✓）。
    ⚠ **只有"新的一次按下"才记 `press_at`**（2026-09-27 修的坑 ✓）：每拍都记 ⇒
      `now - press_at` 只有一帧(<60ms) ⇒ "按够 60ms 就松"**永不成立** ⇒ 变成一路按住 ✗（⚠ 那时 `TAP_ON_S` 是 **60ms**；**2026-10-06 起改成 30ms** ✓ 这条说的是当年的现象 ✓）。
    ⭐ **补按方向**（`retry_ms > 0` 才开 ✓ 用户 2026-10-06："还要补按方向"✓）：已经按着某个
      方向、可 `|dx|` 在「移动操作尝试间隔」(`retry_ms` ✓) 内**没进步**（改善 < `ALIGN_PROGRESS_PX`）
      ⇒ 回 `reassert=True` ⇒ 再发一次 PRESS ✓。
      ⚠ `ClimbJob` 的对齐相**用 `retry_ms=0` 关掉它** ✓（那边行为一个字不改 ✓ 它 CLIMB 相
        本来就有自己的补按 ↑ ✓ 别叠两层 ✗）。

    → `(kind, move, reassert, why, state)`；`state` 是**该写回**的记账
      `{press_dir, press_at, progress_at, best_dx, reasserts}` ✓（调用方自己存哪儿都行 ✓）。
    """
    now = float(now)
    dx = float(dx)
    gap_ms = max(0, int(gap_ms or 0))
    retry_ms = max(0, int(retry_ms))
    near_px = max(1.0, float(near_px))
    tol_px = max(1.0, float(tol_px))
    st = {"press_dir": int(press_dir or 0),
          "press_at": None if press_at is None else float(press_at),
          "progress_at": None if progress_at is None else float(progress_at),
          "best_dx": best_dx,
          "reasserts": 0}
    # ---- 进步记账（只服务"补按方向" ✓）：真的靠近了才刷新 ✓ ----
    _d = abs(dx)
    if st["best_dx"] is None or _d < float(st["best_dx"]) - ALIGN_PROGRESS_PX:
        st["best_dx"] = _d
        st["progress_at"] = now
    elif st["progress_at"] is None:
        st["progress_at"] = now
    # ---- ① 对齐好了 ⇒ 松开方向（"站住"✓ 剩下的交给调用方 ✓）----
    if _d <= tol_px:
        st["press_dir"] = 0
        return ("in_tol", 0, False,
                "对齐好了：差 %.0f px（容许 %d）—— 站住 ✓" % (dx, int(tol_px)), st)
    sign = 1 if dx > 0 else -1
    _held = (st["press_dir"] == sign)
    _since = (None if st["press_at"] is None else now - st["press_at"])
    # ---- ② 近处点按：按够 TAP_ON_S 就松开（别冲过头 ✓）----
    if (_held and _d <= near_px and _since is not None and _since >= TAP_ON_S):
        st["press_dir"] = 0
        return ("wait", 0, False, "微调：差 %.0f px（松开这一拍，别冲过头）" % dx, st)
    # ---- ③ 两次按下之间要隔 gap_ms（**换方向回来按也算** ⇒ 不会两边来回抖 ✓）----
    if (not _held and _since is not None and gap_ms > 0
            and _since * 1000.0 < gap_ms):
        st["press_dir"] = 0
        return ("wait", 0, False,
                "对齐中：差 %.0f px（等移动延迟 %d ms）" % (dx, gap_ms), st)
    # ---- ④ 补按方向（可选）：按着却一直没进步 ⇒ 再发一次 PRESS ✓ ----
    if (retry_ms > 0 and _held and st["progress_at"] is not None
            and (now - float(st["progress_at"])) * 1000.0 >= retry_ms):
        st["press_at"] = now
        st["progress_at"] = now
        st["reasserts"] += 1
        return ("press", sign, True,
                "对齐：差 %.0f px 一直没动 ⇒ **补按一次 %s**（第 %d 次 ✓）"
                % (dx, "→" if sign > 0 else "←", st["reasserts"]), st)
    # ---- ⑤ 按下去（远距离 ⇒ 一口气按住 ✓ / 近距离 ⇒ 一下一下点 ✓）----
    if not _held:
        st["press_at"] = now          # ⚠ 只有"新的一次按下"才记 ✓
    st["press_dir"] = sign
    if _d <= near_px:
        return ("press", sign, False,
                "微调：差 %.0f px（点按 %s）" % (dx, "→" if sign > 0 else "←"), st)
    return ("press", sign, False, "对齐中：差 %.0f px（容许 %d）" % (dx, int(tol_px)), st)


class PortalJob(_PausableJob):
    """一次「走传送点」：**走到门前 ⇒ 点按一下 ↑** ⇒ 等到达（用户 2026-10-06 ✓）。

    用户原话："操作方式是走到该点位按↑" ＋ "点一下↑" ✓（按 `TAP_ON_S` ≈30ms 就松 ✓ 不拍新常数 ✓）。
    对外形状同 `WalkJob` / `ClimbJob` / `DropJob`（`update()` 纯函数 + `retry` / `cancel` ✓）
    ⇒ `agent._climb_tick` 那一套（任务优先 / 有怪先打 / 失败延迟重来 / 原因挂画面）**一行都不用改** ✓。

    三段（`phase`）：
      WALK —— 朝**门**的 x 走（进步跟踪借 `_stalled_since` ✓ 卡住如实报 ✓ 同走路那条 ✓）；
      TAP  —— 人**进了「坐标对齐误差范围」**(`tol_px` ✓) 且 y 也对 ⇒ **点按一下 ↑**（`dir=+1` ✓）；
      WAIT —— 松手之后等"真到了那边"；**位置状态没回执 ⇒ 补按 ↑**（见下 ✓）。

    ⭐⭐ **对齐与补按：与攀爬执行器**同一套**（用户 2026-10-06 ✓ 原话："去传送门的对齐需要调用
      攀爬执行器对齐那个方法：在「坐标误差范围」内就可以按 ↑ ＋ **位置状态没回执补按 ↑**"✓）：
      · **对齐判据用 `tol_px`**（= 设置里的「**坐标对齐误差范围**」✓ 与 `ClimbJob.tol_px`
        是**同一把尺** ✓ 由 `plan_jobs` 一处灌进来 ✓）—— 不再自己拍一个"门的框"当对齐线 ✗；
      · **没回执 ⇒ 补按 ↑**：在 WAIT 相里，"已经到了"就是**回执** ✓；还没到 ⇒ 每
        「**移动操作尝试间隔**」(`retry_ms` ✓ 与爬绳 / 下跳同一个参数 ✓) **再发一次 PRESS ↑**
        （`reassert=True` ✓ 由 `agent._climb_tick` 统一执行 —— `KeyState` 只在键集变化时才发键，
        对面把键丢了本机不知道 ✗，见那里那段说明 ✓）。
      ⚠ **不再自己判"按了 ↑ 多久还没到"** ✗：原来那个 `PORTAL_WAIT_S`(2.5s) 会在**第一次补按
        还没到点**时就把任务判死 ✗（补按间隔默认 3s > 2.5s，等于**永远补不上**✗✓）。
        现在与爬绳同一口径：**真过不去由「寻路超时时间」兜底**（用户 2026-09-29 定的 ✓
        见 `agent._climb_tick` 那道总闸 ✓）。

    ⚠ **判到达优先看集合**（与 `WalkJob` 同一套口径 ✓）：传送的落点由**出口门**决定 ✓
      （`zones.portal_exit` 按 `tn` 解析 ✓ —— 这正是 2026-09-27 移除这个通行方式时缺的"落点" ✓），
      而"目标集合"由用户在编辑器里指 ✓（通常就是出口门所在那个集合 ✓）。
    ⚠ 拿不到坐标 / 门 / 落点 ⇒ **如实说、不乱走**（宁可失败，也别瞎按 ↑ 把自己送错地方 ✓）。
    ⚠ **这里不接「走不动按跳」** ✗：那个开关管的是**走路**执行器（见 `WalkJob._hop_or_fail` ✓）；
      传送点这一段走不动就如实报 ✓（两件事别混 ✓）。
    ⚠ **寻路代价**（用户 2026-10-06 定的口径 ✓）：代价 = **当前 → 起点门** + **出口门 → 目标**
      ⇒ 前一半由"走到门口"这段本身体现 ✓、后一半由 `exit_portal` 的坐标给 ✓
      （规划那边取代价时按这个算 ✓ 见 `zones.portal_exit` 的说明 ✓）。
    """

    # ⚠ `DONE` / `FAILED` **必须自己定义** ✗ —— 它们**不在基类上**（每个任务各一份 ✓，
    #   `_PausableJob._result` 里 `self.phase == self.DONE` 就是这么判的 ✓）：
    #   实测漏定义 ⇒ `AttributeError: 'PortalJob' object has no attribute 'DONE'` ✓，
    #   而且**第一拍就炸** ✓（因为它一进 `update` 就要拼回值 ✓）。取值与走/爬/下跳那三个一致 ✓。
    WALK, TAP, WAIT = "walk", "tap", "wait"
    DONE, FAILED = "done", "failed"

    def __init__(self, dst_set, portal, exit_portal=None, tol_px=ALIGN_TOL_PX,
                 hold_ms=250, near_px=NEAR_PX, align_gap_ms=None, retry_ms=0,
                 timeout_s=DEFAULT_TIMEOUT_S, stall_s=STALL_S):
        self.dst_set = str(dst_set or "")
        self.portal = portal
        self.exit_portal = exit_portal          # 出口门（`tn` 解析出来的 ✓ 可能是 None ✓）
        #: 「**坐标对齐误差范围**」（世界像素 ✓）—— 与 `ClimbJob.tol_px` **同一把尺** ✓
        #: （`plan_jobs` 一处灌进来 ✓ 用户 2026-10-06："在「坐标误差范围」内就可以按 ↑"✓）。
        self.tol_px = max(1, int(tol_px))
        #: 「**坐标对齐误差时间**」(ms)：进了容差还要**稳这么久**才按 ↑ ✓（与爬绳同一把尺 ✓
        #: 用户 2026-10-06："整套照搬对齐式爬绳梯的逻辑"✓）—— 免得"路过一下"就按 ↑ ✗。
        self.hold_ms = max(0, int(hold_ms))
        #: 「**开始对齐…的距离(px)**」（`near_px` ✓）：差得比它远 ⇒ **一口气按住走**；
        #: 进到它以内 ⇒ **改成点按**（一下一下，受 `align_gap_ms` 约束 ✓）—— 同 `ClimbJob` ✓。
        self.near_px = max(1.0, float(NEAR_PX if near_px is None else near_px))
        #: 「**对齐绳梯移动延迟(ms)**」：两次按下方向键之间至少隔这么久 ✓（0 = 不限制 ✓）。
        #: 默认 = `TAP_PERIOD_S`（= 原来那个点按周期 ✓ 老行为 ✓）；由 `agent.start_climb`
        #: 一处灌进来 ✓（它对**每个**任务都灌 ✓ 所以这里只需给个默认 ✓）。
        self.align_gap_ms = (int(TAP_PERIOD_S * 1000.0) if align_gap_ms is None
                             else max(0, int(align_gap_ms)))
        #: 「**移动操作尝试间隔**」(ms) ⇒ `_iv` 秒没回执就**补按一次 ↑** ✓（0 = 不补 ✓ 老行为 ✓）。
        #: ⚠ `agent.start_climb` 会给每个任务灌 `job.retry_ms`（它读设置 ✓ 一处换算 ✓）——
        #:   `DropJob` 用毫秒、这里也用毫秒 ✓（爬绳那边是秒，见 `ClimbJob.reassert_s` ✓）。
        self.retry_ms = max(0, int(retry_ms))
        self.timeout_s = float(timeout_s)
        self.stall_s = max(0.2, float(stall_s))
        self.phase = self.WALK
        self.attempt = 0
        self.note = ("走传送点：「%s」—— 走到门 %s（对齐到 ±%d px）、按一下 ↑"
                     % (self.dst_set, getattr(portal, "pn", "?"), self.tol_px))
        self._t0 = None
        self._best_d = None
        self._best_at = None
        self._tap_at = None
        self._wait_at = None
        #: **上一次发 ↑ 的时刻**（补按的节拍锚 ✓ 见 WAIT 相 ✓）。
        self._press_at = None
        #: 补按了几次（只给 note / 排查看 ✓）。
        self._retap_n = 0
        # ---- 对齐相的记账（`align_x_decide` 的 `state` 就存这几个 ✓ 一处写、一处读 ✓）----
        #: 现在按着哪边（0 = 没按 ✓）—— 也是"这一次按下"的判据（同 `ClimbJob._press_dir` ✓）。
        self._alx_dir = 0
        #: 这一次按下的时刻（⚠ 只有"新的一次按下"才写 ✓ 见 `align_x_decide` ✓）。
        self._alx_press_at = None
        #: 上一次"真的靠近了"的时刻（**补按方向**的判据 ✓）。
        self._alx_progress_at = None
        #: 目前为止最小的 `|dx|`（进步记账 ✓）。
        self._alx_best_dx = None
        #: 对齐相补按了几次（note / 排查 ✓）。
        self._alx_reasserts = 0
        #: **进容差的时刻**（稳 `hold_ms` 用 ✓）。
        self._in_tol_since = None
        # ---- ⭐ **对齐期间"点按 ↑"的记账**（用户 2026-10-06 新口径 ✓ 传送点**专属** ✓）----
        # 「**增加传送点的特殊对齐逻辑**：对齐过程开始时就可以按 ↑，并以「移动操作尝试间隔」
        #   连续点按 ↑」 —— 为什么要它：门是**按 ↑ 才开**的 ✓，而"先对齐到 ±10px 再按 ↑"
        #   等于把人**钉在门口**等对齐 ✗ ⇒ 只要人已经走到门的判定框附近，**站着点按 ↑**
        #   就有可能直接开门（用户口径：对齐过程里就该一直试 ✓）。
        #: 这一下 ↑ 是从哪一刻按下的（`None` = 现在没按着 ✓）—— 按满 `TAP_ON_S` 就松 ✓
        #:   （与后面 `TAP` 相**同一个时长口径** ✓ 不新造时长 ✓）。
        self._up_tap_at = None
        #: 下一按该在什么时候（`None` = **还没打过** ⇒ 这一拍就开打 ✓
        #:   —— 这就是"**对齐过程开始时就可以按 ↑**"那一条 ✓）。
        self._up_next_at = None
        #: ⭐ **连续点按的节拍 = 全项目那份「点按周期」`TAP_PERIOD_S`(180ms)**（用户 2026-10-06
        #:   第二轮 ✓ 原话"**取消传送点通行方式对齐的时候 ↑ 以「移动操作尝试间隔」按，直接连续
        #:   发点按**"✓）—— ⚠ **不再有 `_up_repeat` 这个开关** ✗：原来"`retry_ms=0` ⇒ 只打开头
        #:   那一下"是按「移动操作尝试间隔」那个口径来的 ✓ 现在一律连续 ✓ 与它无关 ✓
        #:   （`retry_ms` 只再管进容差之后 `WAIT` 相的"补按 ↑"✓ 那条一个字没动 ✓）。
        #: 打了多少下（note / 排查 ✓，同 `_retap_n` 的用法 ✓）。
        self._up_taps = 0
        # 被战斗打断时要把这几个时刻整体往后挪（`_PausableJob` ✓ 同 WalkJob 的取舍 ✓）
        # ⚠ `_press_at` 也要挪 ✗：不挪的话"打完架回来"会拿打架前那个锚算 ⇒ 一回来就立刻补按 ✗。
        # ⚠ 对齐相的 `_alx_press_at` / `_alx_progress_at` / `_in_tol_since` **同样要挪** ✗ ——
        #   不挪就是"打完架回来立刻补按一次方向 / 立刻算稳够 hold_ms"✓（假的 ✓）。
        # ⚠ 那里↑点按的两个锚点也一样（`_up_tap_at` / `_up_next_at`）✗：不挪 ⇒ 打完架回来
        #   立刻又打一下 ↑（假的 ✓ 而且那一下本该在打架前就打完 ✓）。
        self._ANCHORS = ("_best_at", "_tap_at", "_wait_at", "_press_at",
                         "_alx_press_at", "_alx_progress_at", "_in_tol_since",
                         "_up_tap_at", "_up_next_at")

    # ---- 内部 ----

    def _arrived(self, px, py, here_sets):
        """到了没有：**集合优先、出口门兜底**（见类说明 ✓）。"""
        if here_sets and self.dst_set and self.dst_set in set(here_sets):
            return "到达：脚下已经是「%s」" % self.dst_set
        ep = self.exit_portal
        if (self.phase == self.WAIT and ep is not None
                and px is not None and py is not None
                and abs(float(px) - float(ep.x)) <= PORTAL_TOL_X
                and abs(float(py) - float(ep.y)) <= PORTAL_TOL_Y):
            return "到达：已经站在出口门 %s 上" % getattr(ep, "pn", "?")
        return ""

    def _fail(self, why):
        self.phase = self.FAILED
        self.note = why
        return self._out(0)

    def _out(self, move):
        """走/等的时候不按跳、不按上下（`dir` 恒 0 ✓）—— 回值走统一形状 ✓。"""
        return self._result(move)

    def _up_tap_step(self, now):
        """⭐ 对齐期间**点按 ↑** 的节拍（用户 2026-10-06 传送点专属口径 ✓）—— True = 这一拍按 ↑。

        口径（用户原话："**增加传送点的特殊对齐逻辑**：**对齐过程开始时就可以按 ↑**，
        并以「**移动操作尝试间隔**」连续点按 ↑"✓）：
          · **进对齐第一拍就打**（`_up_next_at is None` ⇒ 立刻开打 ✓）—— **不等对齐好** ✓；
          · ⭐ **之后一"下"接一"下"，直接连续发点按**（用户 2026-10-06 第二轮 ✓ 原话：
            "**取消传送点通行方式对齐的时候 ↑ 以「移动操作尝试间隔」按，直接连续发点按**"✓）：
            两"下"起点之间隔 `TAP_PERIOD_S`(180ms ✓ = 全项目那份点按周期 ✓ 不新造时长 ✓)，
            每"下"按 `TAP_ON_S` 就松 ✓（与 `TAP` 相**同一个时长口径** ✓）；
          · ⚠ **与 `retry_ms`「移动操作尝试间隔」无关** ✗（那个默认 3 秒 ⇒ 太稀 ✓ 用户实测 ✓）——
            它只再管进容差之后 `WAIT` 相的"补按 ↑" ✓（那条口径一个字没动 ✓）。
        ⚠ 与横向对齐**互不干扰** ✓：`update` 把两路并进**同一份回值**（`move` ＋ `dir` ✓）——
          消费端 `agent._climb_tick` 本来就是分开装配的（`_steer` 管横向、`dir` 管竖直 ✓
          同一拍可以都有 ✓ = 爬绳"朝绳走 + 按住 ↑"那条路 ✓）。
        ⚠ 这几下 ↑ **不算**「爬绳 / 下跳的执行器通知」✓：`agent.climbing_vertical()` 只认
          `ClimbJob` / `DropJob` ✗ ⇒ 走传送点时**不会**打开"能上绳梯"的口 ✓ —— **正是要这样**
          （用户 2026-09-27 定的"碰到绳子不许判在绳上"✓；走传送点更不该被判成在爬绳 ✗）。
        """
        now = float(now)
        if self._up_tap_at is not None and (now - float(self._up_tap_at)) < TAP_ON_S:
            return True                                  # 这一下还按着 ✓
        self._up_tap_at = None                           # 按够 `TAP_ON_S` ⇒ 松手 ✓
        # ⭐ **一"下"接一"下"，直接连续发点按**（用户 2026-10-06 第二轮 ✓ 原话："**取消传送点
        #   通行方式对齐的时候 ↑ 以「移动操作尝试间隔」按，直接连续发点按**"✓）：
        #   两"下"的**起点**之间隔 `TAP_PERIOD_S`(180ms ✓) —— 全项目**同一份点按周期** ✓
        #   不新造时长 ✓（同爬绳对齐 / 走路微调那套节奏 ✓）。
        #   ⚠ **不再看 `retry_ms`** ✗：那是「移动操作尝试间隔」（默认 3 秒 ✓ 用户实测"太稀"✓）；
        #     它仍然管**进容差之后 `WAIT` 相的"补按 ↑"** ✓（那条口径一个字没动 ✓）。
        #   ⚠ "开头那一下"仍然**不等对齐好** ✓（`_up_next_at is None` ⇒ 立刻打 ✓）。
        if self._up_next_at is None or now >= float(self._up_next_at):
            self._up_tap_at = now
            self._up_next_at = now + TAP_PERIOD_S
            self._up_taps += 1
            return True
        return False

    # ---- 对外 ----

    def update(self, now, px, py=None, ladder_id=None, here_sets=None, at_top=None,
               at_bottom=None, ground_y=None, on_rope_pos=None, **kw):
        if self._t0 is None:
            self._t0 = float(now)
        if here_sets is None:
            here_sets = ()
        # ① 超时（口径同走路：这一段跑了多久 ✓）
        if self.timeout_s > 0 and (float(now) - self._t0) >= self.timeout_s:
            return self._fail("走传送点超时：这一段已经跑了 %.0f 秒（门 %s）"
                              % (self.timeout_s, getattr(self.portal, "pn", "?")))
        # ② 到达（集合优先 ✓ 出口门兜底 ✓）
        why = self._arrived(px, py, here_sets)
        if why:
            self.phase = self.DONE
            self.note = why
            return self._out(0)
        p = self.portal
        if p is None:
            return self._fail("这条传送点边没指名哪扇门（数据坏了 ⇒ 回编辑器选一个 ✓）")
        if px is None:
            # 定不了位就别乱走、更别按 ↑（按了可能把自己送到别处 ✗）
            self.note = "走传送点：拿不到世界坐标（小地图定位没有输出）"
            return self._out(0)

        dx = float(p.x) - float(px)
        # ⭐ **按 ↑ 只看 x 对齐**（⚠ 不再拿 `dy_ok` 当门 ✗）：这是**照搬爬绳那条口径** ✓ ——
        #   用户 2026-09-27 在爬绳上定的："**对齐了就按跳开始爬啊，不需要判定别的**"✓
        #   （原话，见 `ClimbJob._align_step` 里"按跳的许可条件"那段 ✓）⇒ 传送点同理：
        #   **x 对齐 + 稳够 `hold_ms` ⇒ 按 ↑** ✓，不再额外要求"人正在门的判定框里"✗。
        #   ⚠ y 差多少**照样写进 note** ✓：人在别的那层时按了也不动 ⇒ **必须从日志看得出来** ✗
        #     （用户 2026-10-06 就是盯着日志发现"左右晃却不按 ↑"的 ✓ 别再让他猜 ✓）。
        _dy = None if py is None else abs(float(p.y) - float(py))
        _y_tip = ("" if (_dy is None or _dy <= PORTAL_TOL_Y)
                  else "　⚠ 人 y=%.0f 与门 y=%.0f 差 %.0f px（> %d）：按 ↑ 只看 x ✓"
                       " 但这一层未必是门那层 ⇒ 按了可能不动 ✓"
                       % (float(py), float(p.y), _dy, int(PORTAL_TOL_Y)))

        # ③ ↑ 正按着（TAP 相）⇒ 按够 `TAP_ON_S` 就松手、进 WAIT ✓
        # ⚠⚠ **`dir` 的正负号是"↑ = +1"** ✗（权威在 `agent._climb_tick` 的消费点：
        #   `dk = km.get("up") if out["dir"] > 0 else km.get("down")` ✓ —— 与 `ClimbJob`
        #   的"向上爬 d=+1"同一套 ✓）。
        #   ⛔ 这里原来写的是 **`dir=-1`** ✗ ⇒ **一直按的是 ↓** ⇒ 用户报的"**站在传送点门口
        #     不按↑**" ✓（现场：走到门口就停住、什么都不发生 ✓ 因为发出去的是"↓"、
        #     而人正站在地上，看着就是"没按"✗）。**自检也没抓住** ✗ —— 因为用例里的期望
        #     （`o["dir"] == -1`）是**照着实现写的** ✗（把 bug 钉成了"期望"✓ 教训同 SKILL **273**）⇒
        #     现在用例改成断言 **`+1`** ✓（照**消费点**的口径，而不是照实现 ✗）。
        #   ⚠ 这里**只看"按够 `TAP_ON_S` 没有"**、不看"人还在不在容差里" ✓：走到一半滑出去也把
        #     这一下按完 ✓（老版下半段那条 ✓ 同一件事 ✓ 别拆成两处 ✗）。
        if self.phase == self.TAP:
            if (float(now) - float(self._tap_at or now)) < TAP_ON_S:
                return self._result(0, dir=1)      # 只按 ↑、不横挪 ✓
            self._tap_at = None
            self.phase = self.WAIT
            self._wait_at = float(now)
            self.note = ("已按 ↑（门 %s）—— 等到达「%s」%s"
                         % (getattr(p, "pn", "?"), self.dst_set, _y_tip))
            return self._out(0)

        # ④ 按过 ↑ 之后的等待窗：**位置状态还没回执 ⇒ 补按 ↑**（用户 2026-10-06 ✓ 同爬绳那套 ✓）
        #   "回执" = **已经到了那边**（上面 `_arrived` 已经判过 ✓）⇒ 走到这儿就是**还没到** ✓。
        #   ⚠ **不自己判"按了多久还没到"** ✗：老那版 `PORTAL_WAIT_S`(2.5s) 会在**第一次补按
        #     还没到点**时就把任务判死 ✗（补按间隔默认 3s > 2.5s ⇒ 等于**永远补不上** ✗✓）；
        #     现在与爬绳同一口径 —— **真过不去由「寻路超时时间」兜底** ✓（见类说明 ✓）。
        #   ⚠ 节拍 = 「**移动操作尝试间隔**」(`retry_ms` ✓ 用户 2026-10-06 追问确认 ✓)。
        if self.phase == self.WAIT:
            waited = float(now) - float(self._wait_at or now)
            _iv = self.retry_ms / 1000.0
            _last = float(self._press_at if self._press_at is not None
                          else (self._wait_at or now))
            if _iv > 0 and (float(now) - _last) >= _iv:
                self._press_at = float(now)
                self._retap_n += 1
                self.note = ("按过 ↑ 之后 %.1f 秒还没到「%s」⇒ **补按一次 ↑**"
                             "（第 %d 次；对面把键丢了也能救回来 ✓）%s"
                             % (waited, self.dst_set, self._retap_n, _y_tip))
                return self._result(0, dir=1, reassert=True)
            self.note = ("已经按过 ↑（门 %s），等到达「%s」（%.1fs%s）%s"
                         % (getattr(p, "pn", "?"), self.dst_set, waited,
                            "，补按过 %d 次" % self._retap_n if self._retap_n else "",
                            _y_tip))
            return self._out(0)

        # ⑤ **对齐 x** —— ⭐ **与爬绳同一处实现**（`align_x_decide` ✓）。
        #   用户 2026-10-06 原话："我们应该**整套照搬对齐式爬绳梯的逻辑**，**还要补按方向**"✓ ——
        #   现场症状："在从 5 到 4 的 h010 传送门**左右来回晃**、**但是没有按 ↑**"✗。
        #   三个要点（都在那个函数里，逐条有注释 ✓）：
        #     · 远（> `near_px`）⇒ 一口气按住；近 ⇒ 一下一下**点按**（按够 `TAP_ON_S` 就松 ✓）；
        #     · ⭐ **两次按下之间隔「对齐绳梯移动延迟」**（默认 180ms ✓）—— **过冲之后往回按
        #       也照样等** ⇒ **不会在目标两边来回晃** ✗✓（老版这里是"这一拍按一下、下一拍
        #       看方向又按回来"✗ ⇒ 人就在门口抖 ✓）；
        #     · ⭐ **补按方向**（"还要补按方向"✓）：按着某个方向却一直没进步 ⇒
        #       `reassert=True` ⇒ 调用方**再发一次 PRESS** ✓（对面把键丢了也能救 ✓）。
        #   ⭐⭐ **另一半：对齐期间**同时**"点按 ↑"**（用户 2026-10-06 追加的**传送点专属**口径 ✓
        #   原话："**增加传送点的特殊对齐逻辑：对齐过程开始时就可以按 ↑，并以「移动操作尝试
        #   间隔」连续点按 ↑**"✓）—— 门是**按 ↑ 才开**的 ✓，而原来"先对齐到 ±`tol_px`
        #   再按 ↑"等于把人**钉在门口**等对齐 ✗ ⇒ 现在**一进对齐就开打** ✓、之后每
        #   「移动操作尝试间隔」再打一下 ✓（节拍口径全在 `_up_tap_step` ✓）。
        #   两路（横向 / ↑）**同一拍一起发** ✓ —— 消费端分开装配（`_steer` / `dir` ✓）。
        _up = self._up_tap_step(now)        # ⭐ 这一拍要不要点按 ↑（见方法说明 ✓）
        kind, move, _re, why, st = align_x_decide(
            now, dx, press_dir=self._alx_dir, press_at=self._alx_press_at,
            progress_at=self._alx_progress_at, best_dx=self._alx_best_dx,
            gap_ms=self.align_gap_ms, near_px=self.near_px, tol_px=self.tol_px,
            retry_ms=self.retry_ms)
        self._alx_dir = st["press_dir"]
        self._alx_press_at = st["press_at"]
        self._alx_progress_at = st["progress_at"]
        self._alx_best_dx = st["best_dx"]
        self._alx_reasserts = st["reasserts"]
        if kind == "in_tol":
            # 对齐好了 ⇒ **站住稳 `hold_ms`** 再按那一下「正式的 ↑」（照搬爬绳"站住等 hold_ms
            #   ⇒ 按跳"✓）：⚠ 不做这一道就是"路过一下也按 ↑"✗（过冲经过门口那一瞬也按 ✓）。
            # ⚠⚠ 但**稳住的这几拍不再把 ↑ 停下** ✗（用户 2026-10-06 新口径："**对齐过程**
            #   开始时就可以按 ↑" ✓ —— 稳住也是对齐过程的一部分 ✓）：继续按 `_up_tap_step`
            #   的节拍点按 ✓；门真在这一下开了 ⇒ 上面 ② 的到达判据当场接走 ✓。
            if self._in_tol_since is None:
                self._in_tol_since = float(now)
                self.note = ("%s（站住稳 %d ms；对齐期间一直在点按 ↑，已打 %d 下）%s"
                             % (why, self.hold_ms, self._up_taps, _y_tip))
                if self.hold_ms > 0:
                    return self._result(0, dir=1) if _up else self._out(0)
            elif (float(now) - float(self._in_tol_since)) * 1000.0 < self.hold_ms:
                self.note = ("对齐好了，保持中（差 %.0f px；对齐期间点按 ↑ 已打 %d 下）%s"
                             % (dx, self._up_taps, _y_tip))
                return self._result(0, dir=1) if _up else self._out(0)
            self._tap_at = float(now)
            self._press_at = float(now)            # 补按 ↑ 的节拍从这一下起算 ✓
            self.phase = self.TAP
            self._best_d = self._best_at = None
            self.note = ("走到门 %s 了（差 %.0f px ≤ 容许 %d，已稳 %d ms）⇒ 点按一下 ↑%s"
                         % (getattr(p, "pn", "?"), abs(dx), self.tol_px,
                            self.hold_ms, _y_tip))
            return self._result(0, dir=1)
        # ---- 还没对齐：站住等的那几拍**别把"进容差"那次记账留着** ✗（不然下次进容差秒按 ✓）----
        self._in_tol_since = None
        # 走不动就如实报（被墙/台阶挡住、或者门不在这层 ✓ —— 老版那条兜底，留着 ✓）
        self._best_d, self._best_at, _stalled = self._stalled_since(
            now, abs(dx), self._best_d, self._best_at, self.stall_s,
            lambda v, b: v < b - 1.0)
        if _stalled:
            return self._fail(
                "走传送点走不动了：卡在 x=%.0f（门 %s 在 x=%d，还差 %.0f px）"
                "—— 可能被墙/台阶挡住，或者这扇门不在你站的这层%s"
                % (float(px), getattr(p, "pn", "?"), int(p.x), abs(dx), _y_tip))
        # ⚠ 说明里**报的是「点按周期」**（用户 2026-10-06 第二轮 ✓）：现在是**连续发点按** ✓
        #   —— 节拍与「移动操作尝试间隔」**无关** ✓（那个只再管 `WAIT` 相的补按 ↑ ✓）。
        _cad = "每 %d ms 一下（连续发点按）" % int(TAP_PERIOD_S * 1000.0)
        self.note = ("%s（对齐期间点按 ↑：%s，已打 %d 下）%s"
                     % (why, _cad, self._up_taps, _y_tip))
        if kind == "press":
            # ⭐ 横向「press」与 ↑ 的点按**同一拍一起发** ✓（`dir=1` 叠加在 `move` 上 ✓）
            return (self._result(move, dir=1, reassert=_re) if _up
                    else self._result(move, reassert=_re))
        # "wait"（横向这一拍不按：点按松开 / 等移动延迟 ✓）—— ↑ 的点按**照旧**可能要发 ✓
        return self._result(0, dir=1) if _up else self._out(0)

    def retry(self):
        """失败后重新激活（同上绳/下跳：回到起始状态重来一遍 ✓）。"""
        self.attempt += 1
        self.phase = self.WALK
        self._t0 = None
        self._best_d = self._best_at = None
        self._tap_at = self._wait_at = None
        self._press_at = None            # 补按的节拍锚也清掉 ✓（新一轮从头算 ✓）
        self._retap_n = 0
        # 对齐相的记账**全部**清掉 ✓（新一轮从头对齐 ✓ —— 留着"上一轮已经按着哪边/稳了多久"
        # 就是脏状态：会一上来就判"早按够了"⇒ 立刻按 ↑ ✗）
        self._alx_dir = 0
        self._alx_press_at = None
        self._alx_progress_at = None
        self._alx_best_dx = None
        self._alx_reasserts = 0
        self._in_tol_since = None
        # 对齐期间"点按 ↑"的记账也清干净 ✓（⚠ `_up_next_at = None` = **下一拍就开打** ✓
        # 正是"新的一轮从对齐开始就按 ↑" ✓；留着旧值 ⇒ 新一轮一上来先空等一个间隔 ✗）
        self._up_tap_at = None
        self._up_next_at = None
        self._up_taps = 0
        self.note = ("第 %d 次尝试：走传送点「%s」（门 %s）"
                     % (self.attempt, self.dst_set, getattr(self.portal, "pn", "?")))
        return self._out(0)

    def cancel(self, why="取消"):
        self.phase = self.FAILED
        self.note = why
        return self._out(0)


def portal_job_for_edge(terrain, z, edge, **kw):
    """从一条「传送点」边造出任务（用户 2026-10-06 ✓）：**必须指名门** ✓，且落点要能解析出来 ✓。

    抛 ValueError 的三种（都**如实说清** ✓ 绝不静默 ✗；上层会照实报给界面 ✓）：
      · 边里没写 `portal`（哪扇门 ✗）—— 编辑器里选一个 ✓；
      · 本图没有这扇门（换了地图 / 地形重导过 ✓）；
      · 这扇门**跨图**、或 `tn` 指的门本图里找不到 ⇒ **本功能不支持跨图** ✓（用户明确 ✓）。
    """
    # ⚠ `core.zones` **在 route 里没有顶层 import** ✗（别处用的是函数内懒加载 ✓）——
    #   照同款在这里懒加载 ✓（实测：写成 `zones.portal_by_pn(...)` 而不 import ⇒
    #   `NameError: name 'zones' is not defined` ✓ 而且**只有走到这条边才炸** ✓）。
    from core import zones

    pn = str(edge.get("portal") or "").strip()
    if not pn:
        raise ValueError("「传送点」边没指名是哪扇门：%s → %s（编辑器里选一个 ✓）"
                         % (edge.get("from"), edge.get("to")))
    p = zones.portal_by_pn(terrain, pn)
    if p is None:
        raise ValueError("「传送点」边引用的门本图里没有：%r（换一扇，或重导地形 ✓）" % pn)
    ex = zones.portal_exit(terrain, pn)
    if ex is None:
        # ⚠ 判据（2026-10-06 修正后 ✓）：`portal_exit` 只看"**`tn` 指的那扇门在不在本图**"✓
        #   ⇒ 走到这儿就是"目标门不在本图"（真跨图 ✓ 如 `west00 → east00` ✓）或 `tn` 是空的 ✓。
        raise ValueError("「传送点」%r 的目标门**不在本图**（跨图 / 或 WZ 里没配去向）⇒ "
                         "不支持跨图 ✓（换一扇本图内的门，或改成别的通行方式）" % pn)
    # ⚠⚠ **吃什么 / 不吃什么**（各自有主 ✓ —— `plan_jobs` 是给四种边**一起灌**参数的 ✓，
    #   漏摘一个就是 `PortalJob.__init__() got an unexpected keyword argument` ✗ 实测漏过 ✓）：
    #   · `stall_s`「卡住判定时长」⇒ **摘** ✗（那是攀爬 / 跳跃的 ✓ 走也摘 ✓）；
    #   · `jump_start_px`「起跳距离」⇒ **摘** ✗（那是跳 / 斜跳的 ✓）；
    #   · ⭐ `hold_ms`「坐标对齐误差**时间**」⇒ **留着** ✓（用户 2026-10-06："整套照搬
    #     对齐式爬绳梯的逻辑"✓ —— 爬绳就是"进容差 ⇒ **站住稳 hold_ms** ⇒ 再动作"✓，
    #     传送点现在同一套 ✓ 点按 ↑ 那一下仍然只按 `TAP_ON_S`(30ms) ✓ 两件事不混 ✗）；
    #   · ⭐ `tol_px`「坐标对齐误差**范围**」⇒ **留着** ✓（用户 2026-10-06 ✓："在「坐标误差
    #     范围」内就可以按 ↑" ✓ —— 与攀爬**同一把尺** ✓；**原来这里把它摘掉了** ✗，
    #     于是传送点用的是自己那个"门的框"当对齐线 ✓）。
    #   ⚠⚠ **只摘这两个** ✗（`tol_px` / `hold_ms` 都留着 ✓ —— 见上面两条 ✓ 实测漏改过一次：
    #     注释写着"留着 `hold_ms`"、而这行还摘着它 ⇒ 任务里永远是最默认的 250 ✗
    #     被自检 `t_portal_align_like_climb` ⑦ 当场抓住 ✓ 教训：**注释和代码要对得上** ✗）。
    for _k in ("stall_s", "jump_start_px"):
        kw.pop(_k, None)
    return PortalJob(edge.get("to"), p, ex, **kw)


#: 「跳(jump)」的**起跳距离**（世界像素）——⚠ **临时参数**，只是"先配一个测试用"：
#:   用户 2026-09-27："先配一个起跳距离测试用，后续物理相关逻辑实现后，移除起跳距离参数，
#:   增加角色移动速度、跳跃力的配置后台换算" ✓。
#: 含义：角色 x 到**最近那条目标 foothold 的 x 范围**（也就是最近端点）的距离 ≤ 它 ⇒ 按跳。
#: **0 = 只有 x 真的进了目标 foothold 范围才跳**（默认值 —— 不拍脑袋补数 ✓）；
#: 正数 = 提前那么多起跳 ✓。设置里在「路线识别 → 物理参数」那一组 ✓。
JUMP_START_PX = 0.0


class JumpJob(_PausableJob):
    """一次「跳」（`jump`）：走到目标平台最近的那条 foothold 边 → **按跳** → 落到目标集合。

    用户 2026-09-27 定的流程（照抄流程图，每个节点都在 `update` 里能指到）：

    ```
    入口（被打断了，还原时从这开始）
      ├─ 角色 x 已经在**目标 foothold 集某条的 x 范围**里 ⇒ **直接按跳**
      └─ 否则 ⇒ 朝**最近的那条目标 foothold**走，进了「起跳距离」⇒ 按跳
    等角色位于**目标 foothold 集合** ⇒ 成功（这一步结束，交给下一段）
    按跳之后「卡住判定时长」还没到目标集合 ⇒ **回入口**（重走、再跳）
    ```

    ⚠ 四条口径（都是用户定的，别自己发明 ✗）：
      · 「最近」= **到那条 foothold 的 x 范围的距离**最近（= 到它**最近端点**的距离 ✓），
        范围内算 0 ✓；
      · 「起跳距离」`jump_start_px` 是**临时参数**：默认 0 ⇒ 进了范围才跳 ✓；
      · **不设"最多试几次"**（用户 2026-09-27）：回入口可以一直重来，整天由 agent 的
        「**寻路超时时间**」兜底 ⇒ 本执行器**自己不判失败** ✓（只在"拿不到世界坐标"时
        如实说，并等着 ✓）；
      · 到达**只认集合**（`here_sets` 里有目标集合 ✓）—— **不用几何兜底**：人还在空中时
        x 早就落在目标范围里了，几何会**误判"到了"** ✗（等跳跃标定 + 落点预测做完，
        才有资格判"落哪儿了" ✓）。

    **跳过之后方向键一直按着**（用户 2026-09-27："当进入起跳距离后按跳这一步，方向键不能
    松开，要等成功或超时判定才能松"✓）—— 方向就是起跳前那一下在走的方向（朝最近那条
    foothold ✓），按到**到了**（`_arrived` ⇒ 松 ✓）或**卡住判定**到点（回入口 ⇒ 松 ✓）为止；
    跳键本身是**点按**（`TAP_ON_S` 之后松手，和「跳下绳梯」同一个节奏，不新造时长常数 ✓）。

    对外形状与走 / 爬 / 下跳**完全一样**（`update/retry/cancel/attempt/phase` +
    `interrupted/_resume`）⇒ `agent._climb_tick` **一行都不用改** ✓。
    """

    ENTRY = "entry"          # 入口：判"要不要按跳"，不要就朝最近的 foothold 走
    JUMP = "jump"            # 已按跳：点按 + 等落到目标集合（超 `stall_s` ⇒ 回入口）
    DONE = "done"
    FAILED = "failed"

    def __init__(self, dst_set, spots, src_set="", tol_px=WALK_TOL_PX, hold_ms=None,
                 stall_s=STALL_S, jump_start_px=JUMP_START_PX,
                 timeout_s=DEFAULT_TIMEOUT_S):
        self.dst_set = str(dst_set or "")
        self.src_set = str(src_set or "")
        #: 候选落点 `[(左, 右, foothold id)]` —— 由 `jump_job_for_edge` 给（目标集合的全部 ✓）
        self.spots = [(float(a), float(b), str(i)) for a, b, i in (spots or [])]
        if not self.spots:
            raise ValueError("跳跃任务没有候选 foothold")
        #: 收下但**不用**：入口只有一条（`job_for_edge` 会把对齐那套参数一起传进来 ✓，
        #: 少一个参数就是 `TypeError`，和 `WalkJob.hold_ms` 同一个理由 ✓）
        self.tol_px = max(1.0, float(tol_px))
        self.hold_ms = hold_ms
        #: 「卡住判定时长(s)」：**按跳之后**这么久还没进目标集合 ⇒ 回入口 ✓
        #: （用户 2026-09-27 同意把它从"只管攀爬"扩成"攀爬 + 跳跃" ✓）
        self.stall_s = max(0.5, float(stall_s))
        #: 「起跳距离」（世界像素；0 = 进了目标 foothold 范围才跳 ✓，见 `JUMP_START_PX`）
        self.jump_start_px = max(0.0, float(jump_start_px))
        self.timeout_s = float(timeout_s)
        #: 第几次尝试 —— ⚠ **不是上限**（用户 2026-09-27 起**四个执行器都不设**"最多试
        #: 几次"了 ⇒ 整段由 agent 的「寻路超时时间」收口 ✓，见文件头那段）。
        self.attempt = 1
        self.dir = 0                       # 跳**不带上下**（不走 ↑/↓ 那一套 ✓）
        self.phase = self.ENTRY
        self.note = "跳过去：「%s」（%d 个候选落点，就近）" % (self.dst_set, len(self.spots))
        self._t0 = None
        #: 这一次按跳的时刻（= 「卡住判定时长」的起点 ✓；None = 还没按 ✓）
        self._jump_at = None
        #: 起跳那一刻**手上的方向**（-1/0/+1，0 = 起跳前本来就没在走 —— 人已经在目标 fh
        #: 范围里 ⇒ `JUMP` 那一相不发方向键 ✓）。用户 2026-09-27："当进入起跳距离后按跳
        #: 这一步，方向键不能松开，要等成功或超时判定才能松" ⇒ 这个值**冻结在起跳那一刻**
        #: （跳出去以后不再跟着 px 变 —— 那时人已经在空中，读数拿它做方向没意义 ✓）。
        self._jump_dir = 0
        #: 被打断时要"跳过时长"的锚点（见 `_PausableJob`）：不扣的话，打完架回来第一拍
        #: 就会 `now - _jump_at ≥ stall_s` ⇒ 当场判"跳过去没到"✗（其实刚按下去）。
        self._ANCHORS = ("_jump_at",)

    # ---- 对外 ----

    def update(self, now, px, py=None, ladder_id=None, here_sets=None, at_top=None,
               at_bottom=None, ground_y=None, on_rope_pos=None,
               climb_failed=None, climb_stalled=None):
        """喂一拍 → 下一步该干什么。

        ⚠ `px` 必须是**世界坐标 x**（`WorldState.Player.world_x`），不是画面坐标
        —— 和其它三个执行器同一个坑（喂错了方向会反、来回抖 ✗）。
        `py` / `ladder_id` 收下但不用（跳不看高度、不看绳 ✓）。
        """
        self._resume(now)
        if self._t0 is None:
            self._t0 = now
        if self.phase in (self.DONE, self.FAILED):
            return self._out(0, False)
        if now - self._t0 > self.timeout_s:
            # ⚠ 实际跑起来 `timeout_s` 被 agent 设成 1e9（「寻路超时时间」统一在那边管 ✓）
            #   ⇒ 这里只是执行器单独用（写用例）时的兜底 ✓
            return self._fail("超时 %.0fs：没能从「%s」跳到「%s」"
                              % (self.timeout_s, self.src_set, self.dst_set))

        # ---- 节点①：到了没有（每一拍都判：站在地上、跳在空中都算 ✓）----
        why = self._arrived(here_sets)
        if why:
            self.phase = self.DONE
            self.note = why
            return self._out(0, False)

        # ---- 节点②：已经按跳 ⇒ 点按完就等落地；「卡住判定时长」到点还没到 ⇒ 回入口 ----
        if self.phase == self.JUMP:
            if (now - self._jump_at) >= self.stall_s:
                self.phase = self.ENTRY
                self._jump_at = None
                self._jump_dir = 0      # 「超时判定」到点 ⇒ 这里才松方向（用户 2026-09-27 ✓）
                self.attempt += 1
                self.note = ("跳过去 %.1fs 还没到「%s」⇒ **回入口**重来（第 %d 次；"
                             "整体由「寻路超时时间」兜底）"
                             % (self.stall_s, self.dst_set, self.attempt))
                # 这一拍**只记这一笔**（什么都不按）：下一拍才重新判"要不要再跳 / 要不要
                # 走近" ✓。为什么要单独占一拍：不占的话这句"回入口"会**当场被下面那句
                # 走位说明盖掉**，日志里就再也看不出"刚才那次跳失败了"✗（实测踩过）。
                return self._out(0, False)
            # ⚠ 方向键**一直按着**（`self._jump_dir`，起跳那一刻冻结的）：用户 2026-09-27
            #   "当进入起跳距离后按跳这一步，方向键不能松开，要等成功或超时判定才能松" ✓
            #   —— 跳键点按、方向键长按，正是"跑跳"的手感（松手就变成原地跳 ✗）。
            if (now - self._jump_at) < TAP_ON_S:
                return self._out(self._jump_dir, True)   # 点按还没够 ⇒ 跳键也继续按着 ✓
            else:
                self.note = "跳了：方向键继续按着（%s），等落到「%s」（%.1fs 没到就回入口）" % (
                    "←" if self._jump_dir < 0 else ("→" if self._jump_dir > 0 else "无"),
                    self.dst_set, self.stall_s)
                return self._out(self._jump_dir, False)  # 松跳、**方向不松** ✓

        # ---- 节点③：入口 —— x 在目标 foothold 范围里就"直接按跳"，否则先走近 ----
        if px is None:
            # 定不了位就别乱跳（跳出去落在哪完全不可知 ✗）—— 如实说，让人去查小地图 ✓
            self.note = "跳出去：拿不到世界坐标（小地图定位没有输出）"
            return self._out(0, False)
        px = float(px)
        near = min(self.spots, key=lambda s: self._span_dist(px, s))
        d = self._span_dist(px, near)
        if d <= self.jump_start_px:
            self.phase = self.JUMP
            self._jump_at = now
            # 记下起跳前**手上的方向**（= 朝最近那条 foothold 那一边）——`JUMP` 那一相不松手 ✓
            # （用户 2026-09-27："进入起跳距离后按跳这一步，方向键不能松开"✓）。
            # 已经在范围里（d ≤ 0）说明本来就没在走 ⇒ 0（那一相也就不发方向键 ✓）。
            self._jump_dir = (1 if near[0] > px else (-1 if near[1] < px else 0))
            self.note = ("已经在目标 foothold（fh %s）的 x 范围里 ⇒ **直接按跳**" % near[2]
                         if d <= 0 else
                         "进了起跳距离（离 fh %s 的范围还差 %.0f px ≤ %.0f）⇒ **按跳**，"
                         "方向键（%s）继续按着"
                         % (near[2], d, self.jump_start_px,
                            "←" if self._jump_dir < 0 else "→"))
            return self._out(self._jump_dir, True)
        self.phase = self.ENTRY
        self.note = ("走向目标 foothold：fh %s 的范围是 %.0f~%.0f，还差 %.0f px"
                     "（起跳距离 %.0f）" % (near[2], near[0], near[1], d,
                                          self.jump_start_px))
        return self._out(1 if near[0] > px else -1, False)

    def retry(self):
        """失败后重新激活：**回到入口**（和流程图一致 ✓）；本执行器一般不判失败 ✓。"""
        self.attempt += 1
        self.phase = self.ENTRY
        self._t0 = None
        self._jump_at = None
        self._jump_dir = 0
        self.note = "第 %d 次尝试：回入口（跳）" % self.attempt
        return self._out(0, False)

    def cancel(self, why="取消"):
        # ⚠ **运行时字段一起收干净**（用户 2026-10-02 #8 ✓ 见 `_cancel_common` ✓）——
        #   原来这里只置相位，带着脏锚被复用就是隐患 ✗。
        self._cancel_common(why)
        return self._out(0, False)

    # ---- 内部 ----

    @staticmethod
    def _span_dist(px, spot):
        """`px` 到那条 foothold 的 **x 范围**的距离：在范围里 = 0，否则＝到**最近端点**的距离 ✓。"""
        left, right, _fid = spot
        if px < left:
            return left - px
        if px > right:
            return px - right
        return 0.0

    def _arrived(self, here_sets):
        """到了没有：**只认集合**（用户 2026-09-27 口径 ✓，见类说明里为什么不用几何 ✗）。"""
        if here_sets and self.dst_set and self.dst_set in set(here_sets):
            return "到达：脚下已经是「%s」" % self.dst_set
        return ""

    def _fail(self, why):
        self.phase = self.FAILED
        self.note = why
        return self._out(0, False)

    def _out(self, move, jump):
        """跳的执行器输出：**不带 ↑/↓**（`dir` 恒 0）✓。"""
        return self._result(move, jump)


def jump_job_for_edge(terrain, z, edge, **kw):
    """从一条「跳」边造出任务：候选落点 = **目标集合**里的非墙 foothold（**不许猜** ✗）。

    抛 ValueError 的两种情况：目标集合里一条 foothold 都没有、或者那些 id 在本图里
    找不到（换了地图 / 地形重导过）—— 让上层如实报警，别下一条"不知道往哪跳"的命令 ✗。

    ⚠ **不读**边上的 `footholds` 格（「下跳」有那一格）：用户 2026-09-27 确认先用
      "**目标集合的全部 foothold、就近挑一条**"（要逐边指定是以后的事 ✓）。
    ⚠ 坐标口径同 `walk_job_for_edge`：地形数据本来就在**世界坐标系**里，玩家读数
      与它直接比 ✓（别再加减偏移 ✗）。
    """
    if (edge.get("kind") or "") != "jump":
        raise ValueError("不是「跳」边：%s" % edge.get("kind"))
    ids = set(str(v) for v in
              ((z.sets.get(edge.get("to")) or {}).get("footholds") or []))
    if not ids:
        raise ValueError("目标集合「%s」里一条 foothold 都没有：%s → %s"
                         % (edge.get("to"), edge.get("from"), edge.get("to")))
    spots = [(float(f.left), float(f.right), str(f.fid))
             for f in terrain.footholds if not f.is_wall and str(f.fid) in ids]
    if not spots:
        raise ValueError("目标集合「%s」的 foothold 在本图里都找不到（或都是墙）：%s"
                         % (edge.get("to"), sorted(ids)))
    return JumpJob(edge.get("to"), spots, src_set=edge.get("from"), **kw)


def _x_span_gap(x, left, right):
    """`x` 到区间 `[left, right]` 的距离（**1D** x，世界像素）—— 落在区间里算 0 ✓。

    口径同 `JumpJob._span_dist`（那边是同一个意思，只是写在类里 ✓）。
    """
    x = float(x)
    if x < float(left):
        return float(left) - x
    if x > float(right):
        return x - float(right)
    return 0.0


def _set_spans(terrain, z, name):
    """集合 `name` 里所有**非墙** foothold → `[(左, 右, 面y, id)…]`（没有就 `[]` ✓）。"""
    ids = set(str(v) for v in ((z.sets.get(name) or {}).get("footholds") or []))
    out = []
    for f in terrain.footholds:
        if f.is_wall or str(f.fid) not in ids:
            continue
        out.append((float(f.left), float(f.right),
                    float(f.y_at((f.left + f.right) / 2.0)), str(f.fid)))
    return out


def set_span(terrain, z, name):
    """集合 `name` 在世界上占的 **x 范围** `(左, 右)`（所有非墙 foothold 的并集）；没有给 `None`。

    用户 2026-09-27 要求 2 用到它（原话）："…且其框底边与角色玩家当前 foothold 集合的
    **(x 范围 + 最大攻击距离)** 有交集…" —— "我这块平台横着占多宽"就是这里 ✓
    （外扩量 `attack_dist` 由调用方 `agent._reachable_without_path` 加，这里只管"范围"本身 ✓）。

    ⚠ **复用 `_set_spans`**（一处实现 ✓，它才是"集合里有哪些非墙 foothold"的口径）：
      这里只把它的 `(左, 右)` 取并集 ✓，不另算一遍 ✗。
    ⚠ 坐标是**世界**坐标（和 foothold 数据同系 ✓）；画面坐标要先用 `screen_to_world` 那套
      平移过去才能比 ✓（画面 1 像素 = 世界 1 像素 ✓）。
    """
    if terrain is None or z is None:
        return None
    spans = _set_spans(terrain, z, str(name))
    if not spans:
        return None
    return (min(s[0] for s in spans), max(s[1] for s in spans))


def set_box(terrain, z, name):
    """集合 `name` 在世界上的**包围盒** `(左, 右, 上y, 下y)`；没有给 `None`（用户 2026-09-28 ✓）。

    ⛔ **为什么单开一个**（2026-09-28 现场修 ✗）：`live_thread._make_toward_set_resolver`
    （"**朝『玩家 → 怪』方向、最近的那个集合**"那条降级 ✓）原来是这样写的：
        `sp = route_mod.set_span(t, z, nm)`  ⇒ 拿到的只是 **(左, 右)** ✗
        `x0, x1, y0, y1 = sp[0], sp[1], sp[2], sp[3]`  ⇒ **`sp[2]` 直接 IndexError** ✗
    而调用方 `agent._mob_goto_towards` 里那句 `except Exception: return False` **把它吞了** ✗
    ⇒ **这条降级从上线起一次都没成功过**，而且**一条痕迹都不留** ✗ —— 现场看到的就是
    "怪判不出集合时**原地卡住**、也不下任务"（用户原话："**没有重新查询、没找到也没根据
    向量下达寻路任务**" ✓）。
    ⇒ 口径**复用 `_set_spans`**（一处实现 ✓ 别另算一遍 ✗）：
      · `左 / 右` = 所有非墙 foothold 的 x 包络（和 `set_span` **同一个值** ✓）；
      · `上y / 下y` = 那些面 y 的 **min / max**（世界坐标**越小越靠上** ✓
        ⇒ 上界 = min、下界 = max ✓ —— 调用方那两行 `if y0 < py` / `if y1 > py` 的语义就是它 ✓）。
    ⚠ 别把它和 `core.zones.set_span` 搞混：那个是**编辑器**用的、收 foothold id 列表、返回四元组 ✓；
      这个是**决策层**用的、收集合名、返回四元组 ✓（两个不同的函数，名字像而已 ✗）。
    """
    if terrain is None or z is None:
        return None
    spans = _set_spans(terrain, z, str(name))
    if not spans:
        return None
    ys = [float(s[2]) for s in spans]
    return (min(s[0] for s in spans), max(s[1] for s in spans),
            min(ys), max(ys))


#: ⭐ **「自然下落垂直折扣系数」**（用户 2026-09-28 定）：**往下掉的垂直距离要打折** ——
#: 掉下去比走过去 / 爬上去快得多，不能按 1:1 算进"要花多远" ✓。
#: 取值来历（用户："先内置为目标值，后续开发物理参数时再细化"）：
#:   MapleNecrocer（`E:\MyPrograms\RippleRogue\MapleNecrocer`）里**玩家**的下落终速
#:   `Player.MaxFallSpeed = 8`（`Client/MapleCharacter.cs:138` ✓）；同一份代码里"标准实体
#:   移速"取 `MoveSpeed = 2.5`（`Client/Pet.cs:75` / `Client/Familiar.cs:79` 都用它 ✓；
#:   玩家自己的移速是键盘直接驱动的、没写成常量 ✗）⇒ 比值 = 8 / 2.5 = **3.2** ✓。
#: ⇒ 语义："**同样一段垂直距离，掉下去只相当于走 1/3.2**" ✓。
#: ⚠ 这是个**内置目标值、不是量出来的**：等物理参数做起来（走速 / 跳 / 重力可配）再换成
#:   算出来的 ✓（用户明确这么安排 ✓）。
FALL_DISCOUNT = 3.2


def _vert_cost(from_y, to_y):
    """**垂直段**的代价：**往下（`to_y` 更低）按「自然下落折扣」折算；往上按原值**（不折 ✓）。

    用户 2026-09-28 要的是「**自然下落**垂直距离折扣系数」—— 只有"掉下去"才算自然下落 ✓，
    跳上去 / 走上去照样得花时间 ⇒ 不打折 ✓。
    ⚠ 世界坐标 **y 向下增大** ⇒ `to_y > from_y` 就是"目标更低" ✓。
    ⛔ **只给"真的会下落"的通行方式用**（2026-09-28 用户第二次明确："**所有的垂直下落端都要
      打折**（**下攀爬不是垂直下落**）"✓）：
      · `jump` 往下 ✓、`drop` ✓ —— 那是下落 ✓；
      · **`walk` 不用它** ✗（走路往下走一层不是自然下落 ⇒ 直接 `abs(fy - py)` ✓）；
      · **`climb` 也不用** ✗（爬上去 / **往下爬**都不是"自然下落"⇒ 不打折 ✓，现在是原值 ✓）。
    """
    d = float(to_y) - float(from_y)
    return (d / FALL_DISCOUNT) if d > 0 else -d


def hop_cost(terrain, z, edge, at):
    """这条边"**从我现在站的地方过去**"要花多少**距离**（世界像素）；算不出来给 `None`。

    用户 2026-09-27 定的口径（**纯距离，不加任何动作惩罚** ✓）；
    **2026-09-28 用户又要求把"垂直段"算进来、并且按「自然下落折扣」折算** ✓：

    | 通行方式 | 代价 |
    |---|---|
    | **走 `walk`** | **横向** = max（玩家 → 目标集合 foothold 端点的距离, **玩家 → 当前集合最近端点的距离**）✓（后半句是 2026-09-28 用户加的："**最小也是**当前 foothold 集合的最边缘端点距离"✓ —— 多层平台 x 重叠时，光看"我的 x 落在目标面的范围里"会算成 0 ✗）+ **垂直段**：玩家脚下 → 那条 foothold 的面 y，**原值不折** ✓（走路不是自然下落 ✓）|
    | **跳 `jump`** | **横向**：玩家 → 目标集合 foothold 端点的距离 + **垂直段**：按 `_vert_cost`（**往下按 `FALL_DISCOUNT` 折算**✓、往上原值 ✓）—— 跳**可以原地起跳**，所以**不加**"源集合边缘"下限 ✓ |
    | **爬 `climb`** | 玩家 → **入绳点**的距离（上爬下端 `L.bottom` / 下爬上端 `L.top` ✓）+ **绳长**（`abs(y2-y1)` ✓ —— 爬得越高越贵 ✓）⚠ **不折扣**（爬上去不是"自然下落" ✓）|
    | **下跳 `drop`** | 玩家 → **最近那条「允许下跳的 foothold」**的**横向**距离 + **该 foothold → 落点的落差**（要落多深 ✓；**往下 ⇒ 按 `FALL_DISCOUNT` 折算** ✓；落点 = 目标集合里离它最近的那片面 ✓） |
    | **传送点 `portal`** ⭐ | 用户 2026-10-06 定："**角色当前到传送起点的距离 ＋ 传送终点距离到目标点的距离**" ✓ ⇒ 玩家 → **起点门**（那扇门 ✓）＋ **出口门** → 目标集合（横向间隙 + 垂直，**不打折** ✓ 落点之后是走过去、不是自然下落 ✓）|

    ⚠ **为什么垂直段要折扣**（用户 2026-09-28）：**掉下去是"自然下落"，比走过去 / 跳上去快得多**
    ⇒ 不折算的话"从高处绕一格"会被算得和"平地走一格"一样贵 ⇒ 择路会挑错 ✓
    （系数的取值来历见 `FALL_DISCOUNT` ✓：先内置目标值，等物理参数做起来再换成算出来的 ✓）。
    ⛔ **但只有"下落"才折**（同一天第二次明确："**所有的垂直下落端都要打折**（**下攀爬不是
      垂直下落**）"✓）⇒ 收窄成：**`jump` 往下** + **`drop`** 折 ✓；**`walk` 不折** ✗
      （走路往下不是下落 ✓）、**`climb` 不折** ✗（上下爬都不是 ✓）。

    ⚠ **算不了就不猜**：没有玩家位置（`at is None`）/ 几何缺失（绳找不到、上下说不清、
      目标集合没有非墙 foothold）⇒ `None` ⇒ 由 `pick_edge` 退回老口径
      （类型优先级 → 文件顺序 ✓）。
    ⚠ 坐标**不做换算**：地形数据本来就在世界坐标系里，和玩家的 `world_x/world_y` 直接比 ✓
      （同 `job_for_edge` 的 ⚠）。
    """
    from core import zones as zones_mod

    if at is None:
        return None
    kind = str((edge or {}).get("kind") or "")
    x = float(at[0])
    if kind == "walk":
        spans = _set_spans(terrain, z, edge.get("to"))
        if not spans:
            return None
        # ⭐⭐ **2026-09-28 用户第二次修这条**（原话："walk 横向我说过了，**最小也是当前
        #   foothold 集合的最边缘端点距离**"✓ + "**所有的垂直下落端都要打折**（**下攀爬不是
        #   垂直下落**）"✓）：
        #   · **横向有下限**：走到"目标集合那条面"其实**不一定够** —— 人得先走到**当前集合的
        #     边缘端点**那一带（多层平台 x 大量重叠，"我 x 落在目标面的范围里"**不等于**
        #     "我这一层就能过去" ✗）。实测现场（图 `106010105`、三楼 → 二楼）：玩家 x=836、
        #     目标二楼 fh=22 的 x 范围 `[738,902]` **罩住了他** ⇒ 老算法横向算成 **0** ✗，
        #     整条 walk 只剩 29.4（垂直打折后）⇒ 险胜 drop 的 29.8 ✗ ⇒ 用户看到的
        #     "**三楼 #91 到二楼**竟然选了 walk"✓。
        #     ⇒ 横向取「目标集合的 x 间隙」与「**到当前集合最近端点的距离**」的**较大者** ✓
        #     （用户口径是"**最小也是**……"⇒ 就是取大 ✓）。
        #   · **垂直不打折**：走路往下走一层**不是自然下落** ✓ ⇒ 按原值算 ✓
        #     （⛔ 原来 walk / jump 共用一个 `_vert_cost` ✗ ⇒ walk 也被打了折 ✗ —— 那正是
        #      "95px 高差只算 29.4"的来源 ✓）。
        _src = _set_spans(terrain, z, edge.get("from"))
        _edge_min = None
        if _src:
            _lo = min(s[0] for s in _src)
            _hi = max(s[1] for s in _src)
            # 到**最近那个端点**的距离（"最边缘端点"✓；人往哪边走近就往哪边走 ✓）
            _edge_min = min(abs(x - _lo), abs(x - _hi))
        best = None
        for a_, b_, fy, _i in spans:
            _h = _x_span_gap(x, a_, b_)
            if _edge_min is not None:
                _h = max(_h, _edge_min)          # "**最小也是**当前集合边缘端点的距离" ✓
            c = _h + abs(float(fy) - float(at[1]))   # 垂直**不打折**（走路不是下落 ✓）
            if best is None or c < best:
                best = c
        return best
    if kind == "jump":
        spans = _set_spans(terrain, z, edge.get("to"))
        if not spans:
            return None
        # 「跳」保持**垂直打折**（往下跳就是自然下落 ✓、往上按原值 ✓ 见 `_vert_cost`）；
        # ⚠ **不加**"源集合边缘"下限（跳可以从原地起跳，不必先走到边缘 ✓ —— 那是 walk 的事〕。
        best = None
        for a_, b_, fy, _i in spans:
            c = _x_span_gap(x, a_, b_) + _vert_cost(at[1], fy)
            if best is None or c < best:
                best = c
        return best
    if kind == "climb":
        lids = zones_mod.ladder_ids(terrain)
        want = str(edge.get("ladder") or "")
        L = next((q for q in terrain.ladders if lids.get(id(q)) == want), None)
        if L is None:
            return None
        # ⚠ `mid_jump` 一定要传（用户 2026-09-28 ✓）：配了「中途跳下」的边，终点**本来
        #   就不在绳端**（爬到 mid_y 侧面跳出去 ✓）⇒ 不传的话这里算不出代价 ⇒ 这条边
        #   在择路时会**排到最后**（哪怕它是唯一一条）✗ —— 与 `job_for_edge` 的口径必须
        #   一致（同一件事两处判 ⇒ 必然漂，§12 的老教训 ✓）。
        d = zones_mod.climb_direction(terrain, z, L, edge.get("from"), edge.get("to"),
                                      mid_jump=bool(edge.get("mid_dir")))
        if d is None:
            return None
        pt = L.bottom if d > 0 else L.top
        # ⭐ 「绳只是**路过**起点这一层」（2026-10-06 用户口径 ✓ 见 `zones.climb_via_jump`）：
        #   这种情况**入绳点不是绳端** ✗ —— 是"**人跳到绳上的那一点**" = `(L.x, 这一层的面 y)` ✓；
        #   **爬升也不是整根绳** ✗ —— 只有"这一层 → **绳的那一端**"那一段 ✓（见下面那段 ⚠⚠）。
        #   ⚠ 照绳端算入绳点会**离谱地大** ⇒ 择路永远不选它 ⇒ "建得出来却从不被用" ✗
        #     （与上一轮传送点那个坑**同一个形状** ✓ 所以必须一起接 ✓）。
        #   ⚠ 判据 = **只看"起点不在绳两端"** ✓（老情形"起点在绳端"一个字不变 ✓）——
        #     ⛔ 原来这里还 `and climb_via_jump(...)` ✗：那只是"要不要**斜**跳"（x 含不含绳 x ✓
        #       `job_for_edge` 灌斜跳区间时才用它 ✓），**与"从哪上绳"无关** ✗ ——
        #       起点不在绳端 + **x 罩住绳 x**（人正站在绳**底下** ⇒ 原地跳就够 ✓ 不用斜跳 ✓）时，
        #       老条件会把代价打回老分支 ⇒ 按**绳端**算入绳点 ⇒ 距离虚大 ⇒ **能建却几乎不被选** ✗
        #       （与上一轮传送点那个坑**同一个形状** ✓ 这正是用户要我"检查"出来的第二处 ✓）。
        #     ⇒ 这类边一律：入绳点 = **(L.x, 这一层的面 y)** ✓（人从这一层跳到绳上 ✓
        #       斜跳还是原地跳，是 `climb_via_jump` 的事 ✗ 与代价无关 ✓）。
        _up, _dn = zones_mod.ladder_ends(terrain, L)
        _su = {n for f in (_up,) if f is not None for n in z.set_of(str(f.fid))}
        _sd = {n for f in (_dn,) if f is not None for n in z.set_of(str(f.fid))}
        if str(edge.get("from")) not in (_su | _sd):
            a = zones_mod.set_span(
                terrain, (z.sets.get(str(edge.get("from"))) or {}).get("footholds") or [])
            if a is None:
                return None
            near = ((x - float(L.x)) ** 2 + (float(at[1]) - float(a[2])) ** 2) ** 0.5
            # ⚠⚠ **爬升那一段必须跟执行器的"停止点"同一套**（用户 2026-10-06 ✓ 原话：
            #   "注意这种寻路代价算法与斜跳上升算法一样，检查一下" ✓）——
            #   执行器爬到哪儿由 `ClimbJob._arrived` / `_target_y` 说了算 ✓：
            #     · **上爬（d>0）** ⇒ 停在**绳梯上端** ✓（用户 2026-09-26 改的口径 ✓
            #       "改为绳子上端的 y" ✓ —— `dst_y`（目标平台面）**不参与上爬判定** ✗）；
            #     · **下爬（d<0）** ⇒ 停在**绳梯下端**（广播 `at_bottom` ✓；落到目标平台面
            #       `dst_y` 也算 ✓ 而本支的放行条件保证"目标层贴着某一端" ⇒ 两者同一处 ✓）。
            #   ⇒ 一律取**绳的那一端**到**起点这一层的面 y** ✓（**不是**目标层的 y ✗：
            #     那是我第一版写错的地方 ✓ 差虽小（本图 2px）但口径必须一处 ✓）。
            #   ⚠ 老分支（起点在绳端）那行 `abs(L.y2 - L.y1)`（整根绳长）**不用改** ✓ ——
            #     起点在绳端 ⇒ 起点层就是那一端 ⇒ 整根绳长**恰好等于**"从起点层爬到另一端" ✓
            #     （两套写法在这里是同一个数 ✓ 这也是它当年能对的原因 ✓）。
            _end_y = min(float(L.y1), float(L.y2)) if d > 0 else max(float(L.y1), float(L.y2))
            return near + abs(_end_y - float(a[2]))
        near = ((x - float(pt[0])) ** 2
                + (float(at[1]) - float(pt[1])) ** 2) ** 0.5
        return near + abs(float(L.y2) - float(L.y1))
    if kind == "drop":
        ids = set(zones_mod.drop_footholds(z, edge))
        spans = [s for s in _set_spans(terrain, z, edge.get("from")) if s[3] in ids]
        if not spans:
            return None
        left, right, fy, _fid = min(spans,
                                    key=lambda s: _x_span_gap(x, s[0], s[1]))
        lands = _set_spans(terrain, z, edge.get("to"))
        if not lands:
            return None
        # 落点 = 目标集合里**x 方向离这条 foothold 最近**的那片面（从这儿掉下去落到的就是它 ✓）
        lf = min(lands, key=lambda s: _x_span_gap((left + right) / 2.0, s[0], s[1]))
        # ⭐ 横向 + **落差**（用户 2026-09-28：**往下 ⇒ 按「自然下落折扣」折算** ✓）——
        #   原来是 `abs(lf[2] - fy)`（1:1 全算）✗ ⇒ 下跳会被算得比实际贵得多 ✓。
        return _x_span_gap(x, left, right) + _vert_cost(fy, lf[2])
    if kind == "portal":
        # ⭐⭐ **传送点的代价**（用户 2026-10-06 ✓ **原话**）："至于寻路代价：我们应该能知道这个
        #   传送点通向哪里，**寻路代价就等于角色当前到传送起点的距离 ＋ 传送终点距离到目标点的
        #   距离**" ✓ ⇒ 拆成两段，跟用户说的一字对应 ✓：
        #     · 前半 `near` = 玩家 → **起点门**（那扇门在哪儿很清楚 ✓ 见 `portal_by_pn` ✓）；
        #     · 后半 `back` = **出口门** → 目标集合（出口 = `tn` 指的那扇门 ✓ 见 `portal_exit` ✓）。
        #   ⚠ 拿不到门 / 出口（跨图 ✓ 用户明确不支持 ✓）⇒ **`None`：不猜** ✓ ——
        #     `pick_edge` 会把这条排到最后，`job_for_edge` 那边也会如实抛 ✓ 两处口径一致 ✓。
        #   ⚠ 后半**不打折**（同 `climb` 的取舍 ✓）：传送落点之后是**走过去**，不是自然下落 ✓
        #     ⇒ 只有 `jump` 往下 / `drop` 才用 `_vert_cost` ✓。
        _pn = str((edge or {}).get("portal") or "")
        p = zones_mod.portal_by_pn(terrain, _pn)
        if p is None:
            return None
        ex = zones_mod.portal_exit(terrain, _pn)
        if ex is None:
            return None
        spans = _set_spans(terrain, z, edge.get("to"))
        if not spans:
            return None
        back = None
        for a_, b_, fy, _i in spans:
            c = _x_span_gap(float(ex.x), a_, b_) + abs(float(ex.y) - float(fy))
            if back is None or c < back:
                back = c
        near = ((x - float(p.x)) ** 2 + (float(at[1]) - float(p.y)) ** 2) ** 0.5
        return near + back
    return None


#: 执行器类名 → 通行方式键（就是 `zones.EDGE_KINDS` 那四个 ✓）—— **这里只做映射，不写中文**：
#: 中文名一律走 `core.zones.kind_label`（`走(walk)` / `爬（绳梯）(climb)` / `跳(jump)` /
#: `下跳(drop)` ✓），别在这儿再抄一份 ✗（两边一旦不一致，界面说的和日志说的就对不上了）。
JOB_KINDS = {"ClimbJob": "climb", "DropJob": "drop",
             "WalkJob": "walk", "JumpJob": "jump",
             # ⭐ 传送点（2026-10-06 ✓ 见 `PortalJob` ✓）—— 少这一格，画面/日志里就会
             #   显示成裸类名 `PortalJob` ✗（这一处只做映射，中文名一律走 `zones.kind_label` ✓）。
             "PortalJob": "portal"}


def job_label(job):
    """当前**执行器**的一行文本（界面用）：`下跳(drop):{详细内容}`；没有 job 给空串 ✓。

    用户 2026-09-27 的要求（原话）："你能把当前的执行器写一下吗？例如格式：`下跳(drop):{详细内容}`"
    —— 卡住的时候，第一件想知道的事就是"**现在跑的是哪个执行器、它卡在哪一步**" ✓；
    原来画面上只有一句自由文本（`agent.current_goto_note` ✓），**看不出是哪一类执行器** ✗。

    「详细内容」= 这个 job 的 `note`（各执行器自己维护的那句话：对齐差几像素 / 谁不在哪块面上 /
    爬不动了 / 到达了 …✓）；note 空的时候退回 `phase`（至少告诉你在哪个相位 ✓）。
    中文名走 `zones.kind_label`（**一处口径** ✓）；类名认不出来时**退回类名**（不猜中文 ✗）。
    """
    if job is None:
        return ""
    from core import zones as zones_mod

    kind = JOB_KINDS.get(type(job).__name__, "")
    name = zones_mod.kind_label(kind) if kind else type(job).__name__
    note = str(getattr(job, "note", "") or "").strip()
    if not note:
        note = str(getattr(job, "phase", "") or "").strip()
    return ("%s:%s" % (name, note)) if note else name


def pick_edge(terrain, z, a, b, at=None):
    """`a → b` **这一步用哪条边** —— 同一对集合有多条时的**唯一判据**。

    ⚠ **路径本身不在这儿定**：集合序列由 `core.zones.find_path`（无权 BFS =
      **最少段数**）决定 ✓ —— 这里只决定"**同一段内走哪条**"，**距离只在同一段内比** ✓
      （用户 2026-09-27 明确："路径仍按最少段数、距离只在同一段内比"）。

    判据（按顺序）：
      1. **只留能用的边**：不在 `zones.EDGE_KINDS` 里的（老数据残留的 `unconfirmed` ✓；
         ⚠ `portal` **2026-10-06 起是正经通行方式了** ✓ 见 `EDGE_KINDS` ✓）、以及
         **建不出任务**的（爬：绳找不到 / 上下说不清；走·跳·下跳：目标集合没有非墙 foothold；
         传送点：门找不到 / **跨图** ✓）⇒ **不参选** ✓（不然会挑出一条根本执行不了的边 ✗）；
      2. 有玩家位置 ⇒ 按 **`hop_cost`**（纯距离 ✓）取**最小**的那条；
         代价**算不出来**的边排到最后 ✓；
      3. 并列 / 没有位置 / 全算不出 ⇒ 退回**老口径**：类型优先级
         （`zones.KIND_PRIORITY`：走 > 爬 > 下跳 > 跳）→ **文件顺序** ✓
         （`edges_between` 的排序就是它 ⇒ 取第一个 ✓ —— 稳定、可预期 ✓）。

    「入绳点」= 真正开始爬的那个点：**上爬在下端**（`L.bottom`）、**下爬在上端**（`L.top`）
    —— 那才是"要走到哪儿才能上绳"，比到绳中点的距离贴近实际 ✓（它是 `hop_cost` 里
    爬绳那一项的一半 ✓）。
    """
    from core import zones as zones_mod

    hit = zones_mod.edges_between(z, a, b)
    if not hit:
        return None
    usable = []
    for e in hit:
        if str(e.get("kind") or "") not in zones_mod.EDGE_KINDS:
            continue
        try:
            job_for_edge(terrain, z, e)      # 只"试造"一下（不要它的结果 ✓）
        except Exception:                    # noqa: BLE001
            continue                         # 建不出来 ⇒ 这条不参选 ✓
        usable.append(e)
    if not usable:
        return None
    if at is None:
        return usable[0]                     # 老口径：类型优先级 → 文件顺序 ✓
    best, best_cost = usable[0], None
    for e in usable:
        c = hop_cost(terrain, z, e, at)
        if c is None:
            continue                         # 算不出 ⇒ 排到最后 ✓
        if best_cost is None or c < best_cost:
            best, best_cost = e, c           # 严格小于 ⇒ 并列时保留**先出现**的那条 ✓
    return best if best_cost is not None else usable[0]


def path_cost(terrain, z, src_sets, dst_sets, at=None):
    """「我站的集合 → 目标的集合」的**寻路距离**（世界像素）；算不出来给 `None`。

    用户 2026-09-27 的需求（原话）："优化：锁定目标优先级要按「**寻路距离**」最近，而不是旧的
    应该是**绝对距离**" —— 挑要打哪只怪时，"哪只更值得先打"该看**走过去多贵** ✓，而不是画面上
    的直线距离（隔着平台 / 要绕一根绳的怪，直线可能很近、实际要走很远 ✗）。

    口径（**完全沿用择路那一套，一格都不新造** ✓）：
      · **路径本身** = `core.zones.find_path`（无权 BFS = **最少段数** ✓ —— 用户 2026-09-27 定的
        "路径仍按最少段数、距离只在同一段内比" ✓）；
      · **每一段的代价** = `pick_edge` 选中的那条边的 `hop_cost`（纯距离 ✓，四类边的表见它那儿 ✓）；
      · **总代价** = 逐段相加（世界像素 ⇒ 天然可比 ✓）。

    ⚠ 这**不是**"加权最短路"：先最少段数、再在段内比距离 —— 与 `plan_jobs` / `pick_edge`
      同一套口径 ✓（约定 39：**别把 `hop_cost` 塞进 `find_path`** ✗）。
    ⚠ **任何一段算不出来（`None`）⇒ 整条给 `None`**（**不猜** ✓，调用方退回老口径 ✓）；
      没有玩家位置（`at is None`）时必然算不出 ⇒ 也是 `None` ✓。
    ⚠ 来源/目标都可能**不止一个集合**（脚下一般 1 个、怪那边 1~3 个 ✓）⇒ 去重后试组合，
      取**能算出来的那些里最小的** ✓（同一集合记 0 ✓）。
    ⚠ **开销**：一次 = 一次 BFS + 每段一次 `pick_edge`（里面还要"试造 job" ✗ 偏重）⇒
      **别挂进每拍、更别对每只怪都算** ✗ —— 同 `route_plan` 的纪律
      （`docs/寻路设计.md` 明说 BFS 不在帧循环里 ✓）。现在只在"**要挑目标**"那一刻、
      对当时候选的怪算一次 ✓（`agent._nearest`）。
    """
    from core import zones as zones_mod

    srcs = [str(s) for s in (src_sets or []) if str(s)]
    dsts = [str(d) for d in (dst_sets or []) if str(d)]
    if z is None or terrain is None or not srcs or not dsts:
        return None
    best = None
    seen = set()
    for a in srcs:
        for b in dsts:
            if (a, b) in seen:
                continue
            seen.add((a, b))
            if a == b:
                return 0.0                     # 同一个集合 ⇒ 一步都不用走 ✓
            try:
                path, _why = zones_mod.find_path(z, a, b)
            except Exception:                  # noqa: BLE001
                continue
            if not path or len(path) < 2:
                continue
            total, ok = 0.0, True
            for i in range(len(path) - 1):
                e = pick_edge(terrain, z, path[i], path[i + 1], at)
                if e is None:
                    ok = False
                    break
                c = hop_cost(terrain, z, e, at)
                if c is None:
                    ok = False
                    break
                total += float(c)
            if ok and (best is None or total < best):
                best = total
    return best


def plan_jobs(terrain, z, src, dst, tol_px=ALIGN_TOL_PX, hold_ms=250, stall_s=None,
              jump_start_px=None, at=None):
    """「从 `src` 走到 `dst`」→ `{"path", "jobs", "why", "here"}`（**一处实现，两边共用**）。

    谁在用：
      · `gui/route_panel._command_first_step`（「命令前往」下整条路径）；
      · `gui/live_thread` 给 agent 注入的**路径解析器**（「定点休息」要 agent 自己走过去）。
    ⚠ 两边**必须同一套判据** —— 各写一份迟早分叉（出现"面板能下发、休息却走不过去"
    这种最难查的怪事 ✗），所以判据只放这里。

    判据（就是「命令前往」原来那套 ✓）：
      · `zones.find_path` 找不到路 ⇒ `jobs=[]`，`why` 说清（它会把"从起点能走到的全部
        集合"列出来 —— 那就是缺边的位置，比一句"没有路径"有用得多）；
      · 每一步**走哪条边**：`pick_edge`（同一对集合有多条绳时**挑最近的** ✓）；
      · 路径里出现**还没做执行器的通行方式**（现在只剩「传送门」；「跳」2026-09-27 已接 ✓）
       ⇒ **整条都不造**并说清是第几步、靠什么（半途停半空比不下更糟 ✗）；
      · 任何一段造任务抛 `ValueError`（绳找不到 / 说不清上下 / 落点找不到）⇒ **抛给
        上层**，让它如实报警或跳过，**不许猜**。
    `src == dst` ⇒ `here=True`（人已经在目标上，不用走 ✓）。
    `at` = **玩家世界坐标** `(x, y)`：给 `pick_edge` 用来挑最近的绳 ✓（None ⇒ 按文件顺序，
    老行为；两个调用方都传得起：面板有定位读数、实时线程有 WorldState ✓）。
    返回的 `jobs` 直接喂 `agent.start_route`；`edges` = **这一步实际选中的那些边**
    （给"命令前往"那行显示用 —— 显示和执行必须是同一条边 ✓）。
    """
    from core import zones as zones_mod

    src, dst = str(src or ""), str(dst or "")
    path, why = zones_mod.find_path(z, src, dst)
    if not path:
        return {"path": [], "jobs": [], "why": why, "here": False, "edges": []}
    if len(path) < 2:
        return {"path": path, "jobs": [],
                "why": "已经在「%s」上了，不用走" % dst, "here": True, "edges": []}
    kinds = []
    #: 每段**选中的那条边**的代价（世界像素；`None` = 算不出来 ⇒ 那一段是按老口径
    #: 的类型优先级取的 ✓）—— 给界面解释"为什么走这条"用 ✓（`docs/寻路设计.md`「择路」✓）。
    costs = []
    for a, b in zip(path, path[1:]):
        e = pick_edge(terrain, z, a, b, at=at)
        if e is None:
            return {"path": path, "jobs": [], "edges": kinds, "costs": costs,
                    "why": ("%s → %s 之间**没有一条能走的边**（已经不存在的通行方式 / "
                            "建不出任务 / 绳或落点找不到）—— 回「寻路编辑器」看看" % (a, b)),
                    "here": False}
        kinds.append(e)
        costs.append(hop_cost(terrain, z, e, at))
    # 「卡住判定时长(s)」从这里灌进**攀爬 + 跳跃**这三类任务（None ⇒ 模块默认 `STALL_S`=3 ✓）：
    # 它管**上爬"爬不动了"**、**下爬"等落地"**、**跳跃"按跳后没落到目标集合"** 三个判据 ✓
    #（用户 2026-09-27 明确同意把它的范围从"只管攀爬"扩成"攀爬 + 跳跃" ✓）。
    # ⚠ **走 / 下跳都不吃它**（`job_for_edge` 会把这一格摘掉 ✓）：走照旧用它自己的
    #   `STALL_S`，卡住由「寻路超时时间」兜底 ✓。
    _stall = STALL_S if stall_s is None else float(stall_s)
    # 「起跳距离(px)」（**临时参数**，见 `JUMP_START_PX`）也一起传 —— 只有「跳」用得上，
    # 别的边由 `job_for_edge` 摘掉 ✓（同一个写法：谁不认这个参数谁 pop ✓）。
    _jump_start = JUMP_START_PX if jump_start_px is None else max(
        0.0, float(jump_start_px))
    jobs = [job_for_edge(terrain, z, e, tol_px=int(tol_px), hold_ms=int(hold_ms),
                         stall_s=_stall, jump_start_px=_jump_start)
            for e in kinds]
    return {"path": path, "jobs": jobs, "why": "", "here": False, "edges": kinds,
            "costs": costs}


def job_for_edge(terrain, z, edge, **kw):
    """从一条「爬」边造出上绳任务 —— **上下由目标那边在绳的上端还是下端判**。

    这条把三样东西接起来（都走现成设施，不自己发明）：
        · `zones.ladder_ids` 找绳（与编辑器画在绳上的编号同一套）；
        · `zones.climb_direction` 判上下（用户 2026-09-26 的规则）；
        · `ClimbJob` 执行。
    判不出来（绳找不到 / 目标不在绳的两端）就抛 ValueError —— 调用方要么报警要么跳过，
    **不许猜**（猜错就是"往反方向爬"，比不做更糟）。

    ⚠ **坐标口径**（2026-09-26 用户澄清，这里曾经改错过一次）：`L.x / L.y1 / L.y2 /
    dst_y` 全来自地形数据，而**地形数据本来就在游戏的世界坐标系里**（例：105090600 的
    fh44 地形 y=-208，它的世界 y 就是 -208）⇒ 玩家读数（= 定位 + 那个"坐标系偏移" ✓）
    与它们**直接比大小**就是对的 ✓。**不要**给这些数再加偏移 —— 加了会把"到达目标平台面"
    从 -208 放宽成 -175（差 33px），看起来像"提前算到了" ✗。
    """
    from core import zones

    kind = edge.get("kind") or ""
    if kind == "drop":
        # 下跳**没有**"卡住"那套判据（它只管"落地了没有"✓）⇒ 把「卡住判定时长」摘掉再传，
        # 不然 `DropJob` 会收到一个不认识的参数 ✗（`plan_jobs` 是给四种边一起灌的 ✓）。
        kw.pop("stall_s", None)
        kw.pop("jump_start_px", None)      # 下跳不吃「起跳距离」（那是「跳」的参数 ✓）
        return drop_job_for_edge(terrain, z, edge, **kw)
    if kind == "walk":
        # ⚠ **走不吃「卡住判定时长(s)」**（用户 2026-09-27 明确："移除对走的相关判定，走用
        # 超时配置兜底"）：那格设置是给**攀爬 / 跳跃**用的 ✓；
        # 走照旧用它自己的常量 `STALL_S`（默认 3s ✓ 老行为不变），另外「寻路超时时间」
        # （`goto_timeout_s`，agent 那一层 ✓）本来就是走的兜底 ✓。
        kw.pop("stall_s", None)
        kw.pop("jump_start_px", None)
        return walk_job_for_edge(terrain, z, edge, **kw)
    if kind == "portal":
        # ⭐ 传送点（用户 2026-10-06 ✓）：**走到门 ⇒ 点按一下 ↑** ✓ 见 `PortalJob` ✓。
        #   ⚠ 它**不吃**「卡住判定时长」/「起跳距离」（那两个是攀爬 / 跳的参数 ✓）；
        #   ⚠ 也**不接**「走不动按跳」那个开关 ✗（那是走路执行器的事 ✓ 见 `PortalJob` 说明 ✓）。
        return portal_job_for_edge(terrain, z, edge, **kw)
    if kind == "jump":
        # 「跳」**吃**「卡住判定时长」（按跳后多久没落到目标集合就回入口 ✓）
        # 和「起跳距离」（临时参数 ✓）—— 两个都留着 ✓。
        return jump_job_for_edge(terrain, z, edge, **kw)
    if kind != "climb":
        raise ValueError("这个模块只认「走」「爬」「下跳」「跳」，收到：%s" % kind)
    # ⚠ 「起跳距离」**爬现在也吃**（2026-09-27 用户要求）：它是「**斜跳上绳**」的区间上界
    #   （`ClimbJob.jump_start_px` ✓，`0` = 关 ⇒ 与老版本**完全一致** ✓）—— 所以原来那行
    #   `kw.pop("jump_start_px", None)` **删掉** ✗，让它顺着下面的 `**kw` 传进 `ClimbJob`
    #   （`plan_jobs` 的两个调用方本来就都在传这个参数 ✓，不用改调用方 ✓）。
    lids = zones.ladder_ids(terrain)
    want = str(edge.get("ladder") or "")
    L = next((x for x in terrain.ladders if lids.get(id(x)) == want), None)
    if L is None:
        raise ValueError("这张图上找不到绳 %s" % (want or "(空)"))
    # ⭐ **方向只看起点在哪端**（用户 2026-09-28）；配了「中途跳下」时，终点**允许不在
    #   绳端**（爬到 `mid_y` 再往 `mid_dir` 跳出去 ✓）—— 见 `zones.climb_direction` ✓。
    d = zones.climb_direction(terrain, z, L, edge.get("from"), edge.get("to"),
                              mid_jump=bool(edge.get("mid_dir")))
    if d is None:
        raise ValueError(
            "说不清 %s →(爬 %s)→ %s 是向上还是向下"
            "（起点不在绳的两端；或终点不在绳端、而这条边又没配「中途跳下」；"
            "或一头圈进了两个集合）—— 回编辑器看一下。"
            % (edge.get("from"), want, edge.get("to")))
    dst_y = dst_surface_y(terrain, z, edge.get("to"), L, d)
    # ⚠ 这里原来还造一个 `entry_span`（入绳端那块 foothold）给「按跳许可」用 ——
    #   2026-09-27 用户明确否掉那道门（"**对齐了就按跳开始爬啊，不需要判定别的**" ✓）
    #   ⇒ 一起删了 ✓（`zones.ladder_ends` 别处还在用 ✓）。
    # ⭐ 「中途跳下」（用户 2026-09-28 ✓）：**逐边**配置，原样转给执行器 ✓
    #   ⚠ `mid_y` 只有配了方向才有意义（老边两个都没有 ⇒ `None`/`""` ⇒ 执行器那条路整条不走 ✓）
    kw.setdefault("mid_dir", zones.mid_jump_dir(edge))
    kw.setdefault("mid_y", edge.get("mid_y"))
    # ⭐⭐ **「斜跳上绳」默认判定**（用户 2026-10-06 ✓ 原话："这个比较特殊，在 x 范围不包含绳梯 x
    #   的情况下默认走斜跳上绳梯，攀爬执行器需要默认判定出来并支持" ✓）：
    #   `ClimbJob` 里那条「斜跳上绳」（①' ✓ 2026-09-27 用户的设计 ✓）**默认是关的** ——
    #   要人在设置里配「起跳距离」才开 ✗。这里替它**从数据判**：
    #     · 判据就一条（用户给的 ✓）：**起点那一层的 x 范围不含绳的 x** ⇒ 人不在绳底下 ⇒
    #       **斜着跳**过去抓绳 ✓（`zones.climb_via_jump` ✓）；含 ⇒ 原地跳就够 ✓ 不启用 ✓；
    #     · 跳得够不够得着 ⇒ 上界 = **这一层离绳最近的那条边到绳的距离** ✓
    #       （`zones.climb_jump_reach` ✓ 现场 7/L6 = 44px ✓ —— **从数据算，不拍数字** ✓）。
    #   ⚠ 只在调用方**没显式配**（`jump_start_px` ≤ 0 ✓）时才兜底 ✗ —— 别盖掉设置里的值 ✓
    #     （那还是那个"兼容开关"：老项目没配 + 判据不成立 ⇒ 一个字不变 ✓）。
    if float(kw.get("jump_start_px") or 0.0) <= 0 and \
            zones.climb_via_jump(terrain, z, L, edge.get("from")):
        _reach = zones.climb_jump_reach(terrain, z, L, edge.get("from"))
        if _reach and float(_reach) > 0:
            kw["jump_start_px"] = float(_reach)
    return ClimbJob(want, L.x, L.y1, L.y2, d, dst_set=edge.get("to"),
                    # src_set：没上绳时用来分"跳没生效（接着按跳）"和"真掉下来了"（要求 ②）
                    src_set=edge.get("from"),
                    dst_y=dst_y, dst_x=dst_center_x(terrain, z, edge.get("to")),
                    **kw)


def dst_center_x(terrain, z, dst_set):
    """目标集合里所有**非墙** foothold 的 x 中点（世界坐标）—— 只有"下爬"要用它。

    给 `ClimbJob.dst_x`：下爬最后那一步「跳下绳梯」要朝**目标集合的中心**按住方向键
    （用户 2026-09-26："向量运算就能解决"）。口径**照抄「走」那条边**（`walk_job_for_edge`
    算 `target_x` 就是"各条 foothold 的中心 x 的 (min+max)/2"✓）—— 两边必须同一套，
    否则"走"和"爬"对"集合中心"的理解会分叉 ✗。

    算不出来（集合没圈 foothold、或圈的全是墙）⇒ 返回 None：让执行器**如实说"没有方向
    可依"**，别自己猜一个方向 ✗（同 README「不许拍脑袋补数」）。
    """
    ids = set(str(v) for v in
              ((z.sets.get(str(dst_set)) or {}).get("footholds") or []))
    xs = [((f.left + f.right) / 2.0) for f in terrain.footholds
          if not f.is_wall and str(f.fid) in ids]
    if not xs:
        return None
    return (min(xs) + max(xs)) / 2.0


def dst_surface_y(terrain, z, dst_set, L, direction=1):
    """目标集合里**爬上去会踩上的那一层**的面（y）。

    ⚠ **向上爬已经不用它当到达判据了**（2026-09-26 用户改口径：上爬按**绳梯上端**的 y，
    见 `ClimbJob._arrived`）—— 现在它的用处是**向下爬的落地面**（`ClimbJob._landed`
    的判据①）。这条函数本身留着（`dst_y` 还在灌），但上爬不再读它 ✓。
    挑选（**按方向**，2026-09-26 用户实测定的口径）：
      · 向上爬 ⇒ 只要**在绳上端之上（或齐平）**的那些面（`y <= y_top`），取**最靠下**
        的那个（也就是最先踩上的那层）；
      · 向下爬 ⇒ 对称：只要 `y >= y_bot` 的，取最靠上的那个。
      两组都空（绳顶悬在平台面**下面**这种事很常见）⇒ 退回"离绳端最近的那个面"。

    ⚠ 为什么不能只取"离绳端最近"（第一版就是这么写的，当场挑错了）：同一个集合里
    可能有**只差几像素的两层**（实测「左上平台」里既有一条 -204、又有一条 -208），
    "最近"会挑中绳端**下方**那条 ⇒ 判据比用户要的松 ✗。

    找不到（集合里没有 foothold / 本图没有这些 id）⇒ None ⇒ 调用方退回几何兜底
    （下爬那边退回"绳梯下端"，见 `_target_y`）。
    """
    ids = set(str(v) for v in ((z.sets.get(dst_set) or {}).get("footholds") or []))
    if not ids:
        return None
    y_top, y_bot = min(L.y1, L.y2), max(L.y1, L.y2)
    cand = []
    for f in terrain.footholds:
        if f.is_wall or str(f.fid) not in ids:
            continue
        cand.append(float(f.y_at((f.x1 + f.x2) / 2.0)))
    if not cand:
        return None
    if direction >= 0:                            # 向上：绳端之上的那些面，取最靠下的
        up = [y for y in cand if y <= y_top]
        return max(up) if up else min(cand, key=lambda y: abs(y - y_top))
    dn = [y for y in cand if y >= y_bot]          # 向下：对称
    return min(dn) if dn else min(cand, key=lambda y: abs(y - y_bot))
